INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脚走路，不用车。", "primary_collocate": null, "pronunciation": "bù xíng", "ipa": "pu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "今天车坏了，我只能步行去上班。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里步行到车站要十分钟。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天步行上学，不坐公交车。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不让车进，只能步行。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们步行去了市场。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，我想步行回家。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢步行，不喜欢坐车。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在家里，步行去了超市。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天步行了一个小时。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站不远，我们步行就行。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "步行了", "label": "体标"}, {"form": "步行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不坐车，用脚走路去某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4275a2c9-4bff-40c5-ac87-bdb8abddd072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23464, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确答案。步行（bù xíng）指用脚走路，不乘车。"}, {"text": "不幸", "is_correct": false, "explanation": "不幸（bù xìng）与步行的第二音节声调不同：行读xíng（第二声），幸读xìng（第四声），意思是运气不好。"}, {"text": "不信", "is_correct": false, "explanation": "不信（bù xìn）与步行的第二音节不同：xíng与xìn的韵尾不同（ng与n），意思是不相信。"}, {"text": "不兴", "is_correct": false, "explanation": "不兴（bù xīng）与步行的第二音节声调不同：行读xíng（第二声），兴读xīng（第一声），意思是不流行。"}], "explanations": {"步行": "正确答案。步行（bù xíng）指用脚走路，不乘车。", "不幸": "不幸（bù xìng）与步行的第二音节声调不同：行读xíng（第二声），幸读xìng（第四声），意思是运气不好。", "不信": "不信（bù xìn）与步行的第二音节不同：xíng与xìn的韵尾不同（ng与n），意思是不相信。", "不兴": "不兴（bù xīng）与步行的第二音节声调不同：行读xíng（第二声），兴读xīng（第一声），意思是不流行。"}, "sentence_index": null, "correct_answer": "步行"}, "level_3": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确。车坏了，只能用脚走路去上班，“步行”与语境相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：前一句说“车坏了”，再说“开车去上班”与前文矛盾。"}, {"text": "搭乘", "is_correct": false, "explanation": "配价：“搭乘”必须带交通工具作宾语，不能直接作谓语，“搭乘去上班”不完整。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：去上班不能用游泳的方式，句子读不通。"}], "explanations": {"步行": "正确。车坏了，只能用脚走路去上班，“步行”与语境相符。", "开车": "语义：前一句说“车坏了”，再说“开车去上班”与前文矛盾。", "搭乘": "配价：“搭乘”必须带交通工具作宾语，不能直接作谓语，“搭乘去上班”不完整。", "游泳": "语义：去上班不能用游泳的方式，句子读不通。"}, "sentence_index": 0, "correct_answer": "步行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆公交车步行到了终点站。", "explanation": "这里应该用〈行驶〉。“步行”指人用脚走路，公交车不能步行，应说“行驶到终点站”。"}, {"text": "她迈着轻快的步行走出了教室。", "explanation": "这里应该用〈步伐〉。“迈”的对象是步伐，“步行”是走路这一动作，不能作为迈出的步子。"}, {"text": "小鱼在河里快乐地步行。", "explanation": "这里应该用〈游〉。“步行”指人用脚走路，鱼在水里不能步行，应说“游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确。“爷爷喜欢步行，不喜欢坐车”中，“步行”与“坐车”形成对照。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”必须带交通工具作宾语，不能单独作谓语，“喜欢乘坐”不完整。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：“迷路”是走错路，不是出行方式，“爷爷喜欢迷路”读不通。"}, {"text": "晕车", "is_correct": false, "explanation": "语义：“晕车”指乘车时身体不适，不能作为喜欢的行为，与语境不符。"}], "explanations": {"步行": "正确。“爷爷喜欢步行，不喜欢坐车”中，“步行”与“坐车”形成对照。", "乘坐": "配价：“乘坐”必须带交通工具作宾语，不能单独作谓语，“喜欢乘坐”不完整。", "迷路": "语义：“迷路”是走错路，不是出行方式，“爷爷喜欢迷路”读不通。", "晕车": "语义：“晕车”指乘车时身体不适，不能作为喜欢的行为，与语境不符。"}, "sentence_index": 6, "correct_answer": "步行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操作要按照步行逐项进行。", "explanation": "这里应该用〈步骤〉。“按照”后接步骤、程序，“步行”是走路的动作，不能指操作的顺序。"}, {"text": "队伍步行一致地前进。", "explanation": "这里应该用〈步调〉。“步调一致”指行动节奏相同，“步行”不能与“一致”搭配。"}, {"text": "这支部队主要由步行组成。", "explanation": "这里应该用〈步兵〉。“步兵”指徒步作战的兵种，“步行”是动作，不能作为组成部队的人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天步行了去学校。", "corrected_sentence": "他昨天步行去了学校。", "error_description": "体标位置错误：“了”应放在第二个动词“去”之后，写作“步行去了学校”；“步行了去”是错误的语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我步行过过这条路。", "corrected_sentence": "我步行过这条路。", "error_description": "体标重复：“过”只用一个，写作“步行过这条路”；“步行过过”中多出一个“过”，不是正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
