INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所包括的边界和界限。", "primary_collocate": null, "pronunciation": "fàn wéi", "ipa": "fan⁵¹ weɪ³⁵", "syllable_count": 2, "sentences": [{"text": "这次考试的范围是第一课到第五课。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这个范围内找答案。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试范围不大。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作范围很广。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事超出了我能做的范围。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个范围里不能停车。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把问题的范围说清楚。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的送货范围只有附近三条街。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨的范围越来越大。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在小范围里试一试。", "target_word": "范围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "范围内", "label": "复合"}, {"form": "大范围", "label": "复合"}, {"form": "小范围", "label": "复合"}], "register": "中性", "sense_fingerprint": "范围|名词|事物所包括的边界和界限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 小店 (Zipf 3.41), 送货 (Zipf 3.4), 三条 (Zipf 3.95)']::text[], 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "范围", "is_correct": true, "explanation": "“范围”指考试所包括的内容界限，这里说明考试范围是第一课到第五课。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻或时长，不能用来界定“第一课到第五课”。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指分数或结果，与“第一课到第五课”这样的内容界限说不通。"}, {"text": "幅度", "is_correct": false, "explanation": "搭配：“幅度”用于变化的大小，不说“考试的幅度”。"}], "explanations": {"范围": "“范围”指考试所包括的内容界限，这里说明考试范围是第一课到第五课。", "时间": "语义：“时间”指时刻或时长，不能用来界定“第一课到第五课”。", "成绩": "语义：“成绩”指分数或结果，与“第一课到第五课”这样的内容界限说不通。", "幅度": "搭配：“幅度”用于变化的大小，不说“考试的幅度”。"}, "sentence_index": 0, "correct_answer": "范围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病情范围很重。", "explanation": "这里应该用〈程度〉。“范围”指事物的界限，形容病情轻重要用“程度”。"}, {"text": "这家公司的范围有三千人。", "explanation": "这里应该用〈规模〉。“范围”指界限，说公司的大小或员工人数要用“规模”。"}, {"text": "这次考试的范围有三个小时。", "explanation": "这里应该用〈时间〉。“范围”指内容的界限，考试持续多久要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "范围", "is_correct": true, "explanation": "“范围”指问题所涉及的界限，这里是请对方把问题的界限说清楚。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：问题没有颜色，无法把“颜色”说清楚。"}, {"text": "重量", "is_correct": false, "explanation": "语义：问题本身没有重量，不能说“把问题的重量说清楚”。"}, {"text": "疆域", "is_correct": false, "explanation": "语域：“疆域”是正式的地理用语，不用于抽象的问题。"}], "explanations": {"范围": "“范围”指问题所涉及的界限，这里是请对方把问题的界限说清楚。", "颜色": "语义：问题没有颜色，无法把“颜色”说清楚。", "重量": "语义：问题本身没有重量，不能说“把问题的重量说清楚”。", "疆域": "语域：“疆域”是正式的地理用语，不用于抽象的问题。"}, "sentence_index": 6, "correct_answer": "范围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家和学校的范围很远。", "explanation": "这里应该用〈距离〉。“范围”指界限或区域，两地之间的远近要用“距离”。"}, {"text": "这片海的范围很深。", "explanation": "这里应该用〈深度〉。“范围”指界限，说水有多深要用“深度”。"}, {"text": "他对工作的范围很认真。", "explanation": "这里应该用〈态度〉。“范围”指界限，形容人做事认真要用“态度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把活动的一张范围扩大到了全校。", "corrected_sentence": "我们把活动的范围扩大到了全校。", "error_description": "“范围”前多加了量词“一张”。“张”用于纸、桌子等平面的东西，抽象的“范围”前不加这类量词，应为“活动的范围”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们先在一条小范围里做了实验。", "corrected_sentence": "他们先在一个小范围里做了实验。", "error_description": "量词“条”用于长条形的东西，不能用于“范围”。“范围”前应用“个”，应为“一个小范围”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与「集聚」相反，指使分开、散开。"}, {"text": "研究", "is_correct": false, "explanation": "研究：指深入探讨问题，与人或事物的聚合、分开都无关。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指使损坏的东西恢复正常，与「集聚」的意思无关。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃：指不再坚持，与「集聚」的意思无关。"}], "correct_answer": "分散", "explanations": {"分散": "分散：与「集聚」相反，指使分开、散开。", "研究": "研究：指深入探讨问题，与人或事物的聚合、分开都无关。", "修理": "修理：指使损坏的东西恢复正常，与「集聚」的意思无关。", "放弃": "放弃：指不再坚持，与「集聚」的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90581c6a-ce31-40a2-98df-7055e2fff56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
