INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅客们集聚了在车站等车。", "corrected_sentence": "旅客们集聚在车站等车。", "error_description": "“了”放错了位置：“集聚”后直接接“在车站”，“了”不能插在“集聚”和地点之间，正确说法是「旅客们集聚在车站等车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90581c6a-ce31-40a2-98df-7055e2fff56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
