INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己家里用的车，不是公家的车。", "primary_collocate": null, "pronunciation": "sī jiā chē", "ipa": "sɨ˥ tɕja˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "他们家去年买了私家车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆私家车是我舅舅的。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把私家车借给了朋友。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日爸爸开着私家车带我们去海边。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口停着很多私家车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的私家车坏了，要去修。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公家的车不能当私家车用。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想存钱买一辆私家车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的私家车停在楼下。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公交车比开私家车便宜吗？", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "私家车主", "label": "复合"}, {"form": "私家車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己家用的车，不属于公家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3430cc5-80a4-4de2-a1d0-e0c20ca887f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警车", "is_correct": false, "explanation": "搭配：“警车”属公安机关，不能说他们家买了警车。"}, {"text": "私家车", "is_correct": true, "explanation": "正确：“他们家”买的是自家使用的车，与句中语境相符。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是公共运营车辆，不会由一般家庭买来自用。"}, {"text": "消防车", "is_correct": false, "explanation": "语义：消防车属消防部门装备，与“他们家”不符。"}], "explanations": {"警车": "搭配：“警车”属公安机关，不能说他们家买了警车。", "私家车": "正确：“他们家”买的是自家使用的车，与句中语境相符。", "公交车": "语义：公交车是公共运营车辆，不会由一般家庭买来自用。", "消防车": "语义：消防车属消防部门装备，与“他们家”不符。"}, "sentence_index": 0, "correct_answer": "私家车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆私家车是单位用来接待客人的。", "explanation": "这里应该用〈公车〉。私家车是自家使用的车，单位接待用的公家车要说公车。"}, {"text": "环卫工人开着私家车清运垃圾。", "explanation": "这里应该用〈垃圾车〉。私家车是自家使用的车，不用来清运垃圾；清运垃圾的车要说垃圾车。"}, {"text": "私家车赶到火场后迅速灭火。", "explanation": "这里应该用〈消防车〉。私家车是自家使用的车，不承担灭火救援；灭火要用消防车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公车", "is_correct": false, "explanation": "语义：“公家的车”本身就是公车，“不能当公车用”前后自相矛盾。"}, {"text": "私家车", "is_correct": true, "explanation": "正确：“私家车”与“公家的车”相对，“不能当私家车用”符合句意。"}, {"text": "私人司机", "is_correct": false, "explanation": "配价：“当……用”后接的是物品，不能接人。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车不能当车库用，这一说法不合常理，句意说不通。"}], "explanations": {"公车": "语义：“公家的车”本身就是公车，“不能当公车用”前后自相矛盾。", "私家车": "正确：“私家车”与“公家的车”相对，“不能当私家车用”符合句意。", "私人司机": "配价：“当……用”后接的是物品，不能接人。", "车库": "语义：车不能当车库用，这一说法不合常理，句意说不通。"}, "sentence_index": 6, "correct_answer": "私家车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私家车在固定线路上每天运营。", "explanation": "这里应该用〈公交车〉。私家车不营业，不能按固定线路运营；定线运营的车要说公交车。"}, {"text": "私家车在小区里来回巡逻。", "explanation": "这里应该用〈警车〉。私家车是个人自用的车，不用于巡逻执法；执法巡逻的车要说警车。"}, {"text": "私家车每天往返运送钢材。", "explanation": "这里应该用〈货车〉。私家车只供自家使用，不用来运送货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅前年换了一条私家车。", "corrected_sentence": "我舅舅前年换了一辆私家车。", "error_description": "量词错误：“私家车”是车辆，应用量词“辆”；“条”用于细长的东西，不能说“一条私家车”。正确说法是“一辆私家车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的私家车们昨天终于修好了。", "corrected_sentence": "我的私家车昨天终于修好了。", "error_description": "词缀错误：“们”只能加在指人的名词后表示复数，“私家车”后不能加“们”；应删去“们”，说“我的私家车昨天终于修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c44248f-0a33-486e-8e27-e1d8b61e6db6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
