INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体在立体空间中的形状以及各部分的排列方式。", "primary_collocate": null, "pronunciation": "kōng jiān jié gòu", "ipa": "kʰʊŋ˥ tɕjɛn˥ tɕjɛ˧˥ kɤʊ˥˩", "syllable_count": 4, "sentences": [{"text": "水分子有特别的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用小球做出了分子的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药物的空间结构决定了它如何与细胞结合。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种分子的空间结构呈三角形，很稳定。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用积木搭出了复杂的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型清楚地展示了晶体的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种酶的空间结构一旦改变，就失去了作用。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究蛋白质的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的空间结构非常稳定，不容易变形。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看着模型，说说它的空间结构。", "target_word": "空间结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "空間結構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物体在空间中呈现的样子与彼此的排列方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空间结构", "is_correct": true, "explanation": "正确：空间结构指分子中原子的立体排列方式，水分子的空间结构是这一意思的正常用法。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情属于有感情的人，水分子没有心情，不能说“有特别的心情”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格指人的个性特点，分子不具备性格，不能说“有特别的性格”。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：家伙是口语里对人或东西的随意称呼，与科学描述的语体不合，也讲不通。"}], "explanations": {"空间结构": "正确：空间结构指分子中原子的立体排列方式，水分子的空间结构是这一意思的正常用法。", "心情": "语义：心情属于有感情的人，水分子没有心情，不能说“有特别的心情”。", "性格": "语义：性格指人的个性特点，分子不具备性格，不能说“有特别的性格”。", "家伙": "语域：家伙是口语里对人或东西的随意称呼，与科学描述的语体不合，也讲不通。"}, "sentence_index": 0, "correct_answer": "空间结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的空间结构很好吃。", "explanation": "这里应该用〈味道〉。空间结构指物体的形状和排列，不能用“好吃”来形容；菜好吃要说“味道”。"}, {"text": "这个团队的空间结构很合理。", "explanation": "这里应该用〈组织结构〉。团队里人员的分工安排是组织结构，不是物体在空间中的形状与排列。"}, {"text": "这首歌的空间结构很好听。", "explanation": "这里应该用〈旋律〉。歌曲没有立体的形状和排列，不能说空间结构好听；应说“旋律很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空间结构", "is_correct": true, "explanation": "正确：酶的空间结构决定其功能，结构改变后失去作用，这是空间结构的标准用法。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪属于有感受能力的生物，酶不会有情绪，句中讲的是结构改变后失去作用。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性情，酶不具备脾气，不能说“这种酶的脾气一旦改变”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：玩意儿是口语里对东西的随意说法，与这句科学叙述的语体不合。"}], "explanations": {"空间结构": "正确：酶的空间结构决定其功能，结构改变后失去作用，这是空间结构的标准用法。", "情绪": "语义：情绪属于有感受能力的生物，酶不会有情绪，句中讲的是结构改变后失去作用。", "脾气": "语义：脾气是人的性情，酶不具备脾气，不能说“这种酶的脾气一旦改变”。", "玩意儿": "语域：玩意儿是口语里对东西的随意说法，与这句科学叙述的语体不合。"}, "sentence_index": 6, "correct_answer": "空间结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个模型的空间结构是五立方厘米。", "explanation": "这里应该用〈体积〉。体积指物体所占空间的大小，以立方厘米计量；空间结构指布局与形状，不能这样计量。"}, {"text": "这块金属的空间结构是三百克。", "explanation": "这里应该用〈质量〉。质量以克计量，表示物体所含物质的多少；空间结构不能用质量来衡量。"}, {"text": "这条河的空间结构是三公里。", "explanation": "这里应该用〈长度〉。长度以公里计量，表示距离；空间结构不能用长度来衡量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子有一条很稳定的空间结构。", "corrected_sentence": "这个分子有一种很稳定的空间结构。", "error_description": "量词错误：空间结构应搭配“种”，“条”用于细长的东西。正确说法是“一种空间结构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种蛋白质有一把很复杂的空间结构。", "corrected_sentence": "这种蛋白质有一种很复杂的空间结构。", "error_description": "量词错误：空间结构应搭配“种”，“把”用于有柄的物件，不能用来计量抽象的空间结构。正确说法是“一种空间结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "柔性", "is_correct": true, "explanation": "柔性是刚性在材料义上的反义词，指柔软、易变形的性质，与“刚性”形成对立。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色与“刚性”没有反义关系，不是描述材料力学性质的词。"}, {"text": "体积", "is_correct": false, "explanation": "体积与“刚性”没有反义关系，二者不在同一语义维度。"}, {"text": "长度", "is_correct": false, "explanation": "长度与“刚性”没有反义关系，不能与之构成对立。"}], "correct_answer": "柔性", "explanations": {"柔性": "柔性是刚性在材料义上的反义词，指柔软、易变形的性质，与“刚性”形成对立。", "颜色": "颜色与“刚性”没有反义关系，不是描述材料力学性质的词。", "体积": "体积与“刚性”没有反义关系，二者不在同一语义维度。", "长度": "长度与“刚性”没有反义关系，不能与之构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "柔性", "is_correct": true, "explanation": "柔性是刚性在材料义上的反义词，指柔软、易变形的性质，与“刚性”形成对立。"}, {"text": "高度", "is_correct": false, "explanation": "高度与“刚性”没有反义关系，不是描述材料力学性质的词。"}, {"text": "味道", "is_correct": false, "explanation": "味道与“刚性”没有反义关系，二者不在同一语义范围内。"}, {"text": "重量", "is_correct": false, "explanation": "重量与“刚性”没有反义关系，不能与之构成对立。"}], "correct_answer": "柔性", "explanations": {"柔性": "柔性是刚性在材料义上的反义词，指柔软、易变形的性质，与“刚性”形成对立。", "高度": "高度与“刚性”没有反义关系，不是描述材料力学性质的词。", "味道": "味道与“刚性”没有反义关系，二者不在同一语义范围内。", "重量": "重量与“刚性”没有反义关系，不能与之构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "材料像石头一样硬，受力后不容易弯曲或变形的性质。", "primary_collocate": null, "pronunciation": "gāng xìng", "ipa": "kɑŋ˥˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种钢的刚性很强，不容易弯。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头的刚性不如铁。", "target_word": "刚性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "玻璃有刚性，但是一摔就碎。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做桌子要用刚性好的材料。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根棒子刚性太大，弯不了。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头的刚性很高，所以不会变形。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车的架子需要有足够的刚性。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥的刚性不够，风大时会动。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料绳没有刚性，一拉就弯。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他选了一把刚性很好的尺子。", "target_word": "刚性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚性材料", "label": "复合"}], "register": "中性", "sense_fingerprint": "材料像石头一样硬，受力后不易弯曲或变形的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚性", "is_correct": true, "explanation": "刚性指材料受力后不易变形，与“很强，不容易弯”的描述一致。"}, {"text": "色泽", "is_correct": false, "explanation": "语义：色泽指颜色与光泽，与“不容易弯”的力学性质无关。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“很强”一般修饰力度或程度，“温度很强”不是常见说法。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格通常说高或低，“价格很强”不搭配。"}], "explanations": {"刚性": "刚性指材料受力后不易变形，与“很强，不容易弯”的描述一致。", "色泽": "语义：色泽指颜色与光泽，与“不容易弯”的力学性质无关。", "温度": "搭配：“很强”一般修饰力度或程度，“温度很强”不是常见说法。", "价格": "搭配：价格通常说高或低，“价格很强”不搭配。"}, "sentence_index": 0, "correct_answer": "刚性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种金属的刚性很好，很难被拉断。", "explanation": "这里应该用〈韧性〉。很难被拉断说的是韧性，刚性指受力不易变形。"}, {"text": "这种材料的刚性很好，拉开后会恢复原状。", "explanation": "这里应该用〈弹性〉。拉开后恢复原状说的是弹性，刚性指不易变形，二者不同。"}, {"text": "这种泥土的刚性很强，可以捏成各种形状。", "explanation": "这里应该用〈可塑性〉。能捏成各种形状说明易变形，刚性指不易变形，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚性", "is_correct": true, "explanation": "刚性指结构抵抗变形的能力，车架需要足够的这种能力，句意通顺。"}, {"text": "速度", "is_correct": false, "explanation": "语义：车架是结构件，不能说“足够的速度”，与车架的力学要求无关。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：车架需要的是结构强度，“亮度”与车架的力学要求无关。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“足够的”后接的应是性能名词，“声音”与“车的架子需要”搭配不当。"}], "explanations": {"刚性": "刚性指结构抵抗变形的能力，车架需要足够的这种能力，句意通顺。", "速度": "语义：车架是结构件，不能说“足够的速度”，与车架的力学要求无关。", "亮度": "语义：车架需要的是结构强度，“亮度”与车架的力学要求无关。", "声音": "搭配：“足够的”后接的应是性能名词，“声音”与“车的架子需要”搭配不当。"}, "sentence_index": 6, "correct_answer": "刚性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块海绵的刚性很高，一按就陷下去。", "explanation": "这里应该用〈弹性〉。一按就陷下去说明材料软、有弹性，刚性指不易变形，与之相反。"}, {"text": "这根铜丝的刚性很好，能拉得很细。", "explanation": "这里应该用〈延展性〉。能拉得很细说的是延展性，刚性指抵抗变形的能力。"}, {"text": "这种材料有刚性，可以弯折而不断。", "explanation": "这里应该用〈柔性〉。「可以弯折而不断」说明材料柔软易弯，刚性指不易变形，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种钢有一只很好的刚性，不容易弯。", "corrected_sentence": "这种钢有一种很好的刚性，不容易弯。", "error_description": "错误：量词「只」，应为「种」。“刚性”是抽象性质，应用量词「种」，「只」用于动物或成对器物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根竹竿的刚性得很好，不会弯。", "corrected_sentence": "这根竹竿的刚性很好，不会弯。", "error_description": "错误：「刚性」是名词，后面不能直接带「得」补语。应删去「得」，说「竹竿的刚性很好」，让「刚性」作主语，「很好」作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
