INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西压小，让它的体积变小。", "primary_collocate": null, "pronunciation": "yā suō", "ipa": "ja˥˥ swo˥˥", "syllable_count": 2, "sentences": [{"text": "他把厚厚的羽绒服压缩成一个小包。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机软件可以压缩大照片。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文件太大，请先压缩再发给我。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把冬天的衣服压缩后放进柜子里。", "target_word": "压缩", "complexity_tier": "T3", "furigana": "mā ma bǎ dōng tiān de yī fu yā suō hòu fàng jìn guì zi lǐ", "sentence_source": "generated"}, {"text": "睡袋压缩以后，只有一个水瓶那么大。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帐篷压缩好，放进背包。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种海绵压缩以后，很快就能变回原样。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想压缩视频，手机里才有地方。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家前，我们压缩了所有的纸箱。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压缩后的文件小多了，发送很快。", "target_word": "压缩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压缩了", "label": "体标"}, {"form": "压缩过", "label": "体标"}, {"form": "压缩包", "label": "复合"}, {"form": "壓縮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把物品或文件压小，使体积变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压缩", "is_correct": true, "explanation": "正确：“压缩”指使物体体积变小，与“厚厚的羽绒服”变成“小包”的结果相符。"}, {"text": "展开", "is_correct": false, "explanation": "语义：“展开”使物体铺开变大，与“小包”的结果相反。"}, {"text": "膨胀", "is_correct": false, "explanation": "配价：“膨胀”是不及物动词，不能用“把”带“羽绒服”作受事宾语。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”表示体积或范围变大，与“压缩成小包”相反。"}], "explanations": {"压缩": "正确：“压缩”指使物体体积变小，与“厚厚的羽绒服”变成“小包”的结果相符。", "展开": "语义：“展开”使物体铺开变大，与“小包”的结果相反。", "膨胀": "配价：“膨胀”是不及物动词，不能用“把”带“羽绒服”作受事宾语。", "扩大": "语义：“扩大”表示体积或范围变大，与“压缩成小包”相反。"}, "sentence_index": 0, "correct_answer": "压缩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用抹布压缩桌子。", "explanation": "这里应该用〈擦〉。压缩是使物体体积变小，擦桌子不会让桌子变小。"}, {"text": "他把石头压缩在纸上。", "explanation": "这里应该用〈压住〉。压缩要使物体体积变小，把石头压住只是用力按着，石头本身不会变小。"}, {"text": "他用剪刀压缩纸。", "explanation": "这里应该用〈剪〉。剪纸是把纸切开，不是使纸的体积变小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压缩", "is_correct": true, "explanation": "正确：“压缩”使海绵体积变小，与“以后很快能变回原样”的语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕破的海绵无法自行变回原样，与句意矛盾。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：粉碎后的海绵已成碎片，不可能再变回原样。"}, {"text": "剪碎", "is_correct": false, "explanation": "语义：剪碎的海绵已经变成碎块，不可能再变回原样。"}], "explanations": {"压缩": "正确：“压缩”使海绵体积变小，与“以后很快能变回原样”的语境相符。", "撕": "语义：撕破的海绵无法自行变回原样，与句意矛盾。", "粉碎": "语义：粉碎后的海绵已成碎片，不可能再变回原样。", "剪碎": "语义：剪碎的海绵已经变成碎块，不可能再变回原样。"}, "sentence_index": 6, "correct_answer": "压缩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用肥皂压缩手。", "explanation": "这里应该用〈洗〉。压缩用于使物体体积变小，洗手不会让手变小。"}, {"text": "妈妈压缩着孩子。", "explanation": "这里应该用〈抱〉。压缩只用于物体，不用于人；抱孩子应说〈抱〉。"}, {"text": "他压缩了一下门。", "explanation": "这里应该用〈推〉。压缩是使物体体积变小，推门只是施力，门本身不会变小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件棉衣可以压缩很小。", "corrected_sentence": "这件棉衣可以压缩得很小。", "error_description": "错误形式：压缩很小；正确形式：压缩得很小。“压缩”后接程度补语要用“得”（或用“到”，如“压缩到很小”），不能直接接“很小”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没把枕头压缩进了袋子里。", "corrected_sentence": "我没把枕头压缩进袋子里。", "error_description": "「没」字句中动词后不能再用「了」，应说「没把枕头压缩进袋子里」，不能说「没把枕头压缩进了袋子里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
