INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规划是提前想好的、对以后要做的事的整体安排。", "primary_collocate": null, "pronunciation": "guī huà", "ipa": "kweɪ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "你对以后的工作有什么规划？", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有一个五年的学习规划。", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里做了新的公园规划。", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的人生规划很清楚。", "target_word": "规划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有规划，做事容易乱。", "target_word": "规划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是老师给我们的学习规划，大家要照着做。", "target_word": "规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为明年的新学期做了长远的规划。", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作以前，他先做了一份详细的规划。", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的规划是先存钱，再去国外读书。", "target_word": "规划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸对家里的花园有个小规划，打算种花。", "target_word": "规划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份规划", "label": "量词"}, {"form": "规划师", "label": "复合"}, {"form": "規劃", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先对要做的事做出的整体安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规划", "is_correct": true, "explanation": "正确：「规划」指对工作的长远安排，与「以后的工作」相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体的重量，与工作安排无关。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「房子」是建筑物，不能用来指对工作的安排。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：「对工作有什么比赛」不成立，「比赛」不用于说工作的安排。"}], "explanations": {"规划": "正确：「规划」指对工作的长远安排，与「以后的工作」相合。", "体重": "语义：「体重」指身体的重量，与工作安排无关。", "房子": "语义：「房子」是建筑物，不能用来指对工作的安排。", "比赛": "搭配：「对工作有什么比赛」不成立，「比赛」不用于说工作的安排。"}, "sentence_index": 0, "correct_answer": "规划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一朵规划，要慢慢完成。", "explanation": "这里应该用〈项〉。「规划」是抽象的安排，不说「一朵」，应说「一项」或「一份」。"}, {"text": "学校有严格的规划，学生不能迟到。", "explanation": "这里应该用〈规定〉。「规划」是事先想好的安排，不指必须遵守的条文。"}, {"text": "这件衣服的规划很漂亮，大家都夸它。", "explanation": "这里应该用〈设计〉。「规划」指事先安排要做的事，衣服的样式要说「设计」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规划", "is_correct": true, "explanation": "正确：「做了长远的规划」指为新学期事先做好整体安排。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不能「做」，也没有「长远」的说法。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体重量，与学校的新学期安排无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人能「做」出来的，句子说不通。"}], "explanations": {"规划": "正确：「做了长远的规划」指为新学期事先做好整体安排。", "颜色": "语义：「颜色」不能「做」，也没有「长远」的说法。", "体重": "语义：「体重」指身体重量，与学校的新学期安排无关。", "天气": "语义：天气不是人能「做」出来的，句子说不通。"}, "sentence_index": 6, "correct_answer": "规划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的规划很好吃，大家都夸。", "explanation": "这里应该用〈味道〉。「规划」指事先安排，菜的口感要说「味道」。"}, {"text": "今天的规划很冷，我们都穿上了外套。", "explanation": "这里应该用〈天气〉。冷暖说的是天气，「规划」指事先的安排，不能用来形容冷暖。"}, {"text": "父母为我的未来做了一把规划。", "explanation": "这里应该用〈项〉。「规划」是抽象名词，量词应为「项」，不能说「一把规划」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为退休后的生活做了一块详细的规划。", "corrected_sentence": "他为退休后的生活做了一项详细的规划。", "error_description": "错误形式：「一块规划」。正确形式：「一项规划」。「规划」是抽象名词，量词应为「项」，「块」用于块状的东西，不能用于规划。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母为我做了一座长远的规划。", "corrected_sentence": "父母为我做了一项长远的规划。", "error_description": "错误形式：「一座规划」。正确形式：「一项规划」。「座」用于大的建筑或山，不能用于抽象的规划，应说「项」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
