INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水会走路，也能让东西动。", "primary_collocate": null, "pronunciation": "liú", "ipa": "ljoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "水往低处流。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水带着树叶慢慢流走了。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水流进了小河里。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水带着小船往下流。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水龙头没关，水一直在流。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水杯倒了，牛奶流到地上。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上的雨水都流进了下水道。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小溪里的水清清地流着。", "target_word": "流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪化了，水从山上流下来。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水流得很快，把小木棍带走了。", "target_word": "流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流了", "label": "完成体"}, {"form": "流着", "label": "持续体"}, {"form": "流过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "水向前移动，并带着东西一起动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流", "is_correct": true, "explanation": "流 liú（第二声），意思是水或东西向前移动。"}, {"text": "柳", "is_correct": false, "explanation": "liú（第二声）与 liǔ（第三声）声调不同，柳 意思是柳树。"}, {"text": "六", "is_correct": false, "explanation": "声调不同：liù（第四声）意思是数字“六”。"}, {"text": "溜", "is_correct": false, "explanation": "声调不同：liū（第一声）意思是溜走、滑动。"}, {"text": "牛", "is_correct": false, "explanation": "声母不同：niú 以 n 开头，与 liú 的 l 不同，意思是牛。"}], "explanations": {"流": "流 liú（第二声），意思是水或东西向前移动。", "柳": "liú（第二声）与 liǔ（第三声）声调不同，柳 意思是柳树。", "六": "声调不同：liù（第四声）意思是数字“六”。", "溜": "声调不同：liū（第一声）意思是溜走、滑动。", "牛": "声母不同：niú 以 n 开头，与 liú 的 l 不同，意思是牛。"}, "sentence_index": null, "correct_answer": "流"}, "level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "水往低处流，指水顺着地势向下移动，符合句意。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”指向上移动，与“往低处”的方向相反。"}, {"text": "冒", "is_correct": false, "explanation": "语义：“冒”指液体或气体向上涌出，与“往低处”矛盾。"}, {"text": "爬", "is_correct": false, "explanation": "搭配：“爬”指人或动物用手脚移动，不用来形容水。"}], "explanations": {"流": "水往低处流，指水顺着地势向下移动，符合句意。", "升": "语义：“升”指向上移动，与“往低处”的方向相反。", "冒": "语义：“冒”指液体或气体向上涌出，与“往低处”矛盾。", "爬": "搭配：“爬”指人或动物用手脚移动，不用来形容水。"}, "sentence_index": 0, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子从门缝里流出去了。", "explanation": "这里应该用〈溜〉。流多指液体、气体等连续移动，人悄悄从缝隙里出去要用溜。"}, {"text": "一块石头从山上流了下来。", "explanation": "这里应该用〈滚〉。石头等固体快速翻下来要用滚，流只用于液体或成股的东西。"}, {"text": "秋天到了，树叶从枝头流下来。", "explanation": "这里应该用〈落〉。树叶离开枝头往下降要用落，流指液体或成股东西的连续移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23486, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流", "is_correct": true, "explanation": "流 liú（第二声），意思是水或东西向前移动。"}, {"text": "楼", "is_correct": false, "explanation": "韵母不同：lóu 的韵母是 ou，liú 的韵母是 iu，声调相同，意思是楼房。"}, {"text": "遛", "is_correct": false, "explanation": "声调不同：liù（第四声），意思是慢慢走、散步，如“遛狗”。"}, {"text": "绺", "is_correct": false, "explanation": "声调不同：liǔ（第三声），是量词，如“一绺头发”。"}], "explanations": {"流": "流 liú（第二声），意思是水或东西向前移动。", "楼": "韵母不同：lóu 的韵母是 ou，liú 的韵母是 iu，声调相同，意思是楼房。", "遛": "声调不同：liù（第四声），意思是慢慢走、散步，如“遛狗”。", "绺": "声调不同：liǔ（第三声），是量词，如“一绺头发”。"}, "sentence_index": null, "correct_answer": "流"}, "level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "雨水流进下水道，指雨水移动进入下水道，符合句意。"}, {"text": "停", "is_correct": false, "explanation": "语义：“停”指停止不动，与雨水顺着下水道移动的意思不符。"}, {"text": "堆", "is_correct": false, "explanation": "语义：“堆”指堆积成堆，雨水不会堆进下水道。"}, {"text": "飞", "is_correct": false, "explanation": "搭配：“飞”用于鸟或物体在空中移动，不说雨水飞进下水道。"}], "explanations": {"流": "雨水流进下水道，指雨水移动进入下水道，符合句意。", "停": "语义：“停”指停止不动，与雨水顺着下水道移动的意思不符。", "堆": "语义：“堆”指堆积成堆，雨水不会堆进下水道。", "飞": "搭配：“飞”用于鸟或物体在空中移动，不说雨水飞进下水道。"}, "sentence_index": 6, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛一直流到深夜。", "explanation": "这里应该用〈持续〉。流指液体、人群或成股东西的移动，时间的延续要用持续。"}, {"text": "这个消息流给了记者。", "explanation": "这里应该用〈透露〉。流指液体或成股东西的移动，把内幕告诉别人要用透露。"}, {"text": "他把这幅画流给了博物馆。", "explanation": "这里应该用〈捐〉。流指液体或成股东西的移动，无偿把物品赠给机构要用捐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水顺着屋檐往下了流。", "corrected_sentence": "雨水顺着屋檐往下流。", "error_description": "“了”插在“往下”和“流”之间，位置错误。此句的“流”后不加“了”，应删去“了”，写作“雨水顺着屋檐往下流。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "溪水从山谷里流上来。", "corrected_sentence": "溪水从山谷里流下来。", "error_description": "方向补语应为“下来”，水顺着山谷向低处流；错误写成“上来”，与水往低处流的方向相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
