INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得有一个固定的样子。", "primary_collocate": null, "pronunciation": "dìng xíng", "ipa": "tiŋ˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "泥土放进火里烧一烧，才会定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头发吹干以后，就能定形了。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用发胶让头发定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块软泥要放一天才能定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕放进冰箱一会儿就定形了。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅先把铁烧红，再打一打让它定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石膏干了以后，杯子才算定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做陶瓷时，泥要先定形再上色。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料很快就能定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子用热水蒸一蒸，就会定形。", "target_word": "定形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定形了", "label": "体标"}, {"form": "定形过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使东西成为固定的形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定形", "is_correct": true, "explanation": "泥土烧过以后才能固定形状，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”用于冰雪、金属等，泥土经火烧不会融化成液体。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指低温凝固，与“放进火里烧”的情境相反。"}, {"text": "降温", "is_correct": false, "explanation": "语义：“降温”指温度下降，与“放进火里烧”的过程矛盾。"}], "explanations": {"定形": "泥土烧过以后才能固定形状，符合句意。", "融化": "搭配：“融化”用于冰雪、金属等，泥土经火烧不会融化成液体。", "冻结": "语义：“冻结”指低温凝固，与“放进火里烧”的情境相反。", "降温": "语义：“降温”指温度下降，与“放进火里烧”的过程矛盾。"}, "sentence_index": 0, "correct_answer": "定形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把桌子定形在地上。", "explanation": "这里应该用〈固定〉。定形指物体的形状变得固定，把东西固定在某处要用固定。"}, {"text": "血液定形了，伤口很快就好了。", "explanation": "这里应该用〈凝固〉。血液由液体变为固体要用凝固，定形指形状固定，不用于血液。"}, {"text": "这个国家的物价终于定形了。", "explanation": "这里应该用〈稳定〉。定形只用于物体的形状，物价的变化趋势要用稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定形", "is_correct": true, "explanation": "石膏干了以后形状才算固定，符合句意。"}, {"text": "软化", "is_correct": false, "explanation": "语义：“软化”指变软，与“石膏干了”后变硬的结果相反。"}, {"text": "溶解", "is_correct": false, "explanation": "语义：“溶解”指固体化入液体，石膏干后不会溶解，句意不通。"}, {"text": "膨胀", "is_correct": false, "explanation": "搭配：“膨胀”多用于体积增大的物质，不说杯子才算膨胀。"}], "explanations": {"定形": "石膏干了以后形状才算固定，符合句意。", "软化": "语义：“软化”指变软，与“石膏干了”后变硬的结果相反。", "溶解": "语义：“溶解”指固体化入液体，石膏干后不会溶解，句意不通。", "膨胀": "搭配：“膨胀”多用于体积增大的物质，不说杯子才算膨胀。"}, "sentence_index": 6, "correct_answer": "定形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议定形了下周的日程。", "explanation": "这里应该用〈确定〉。定形只用于物体的形状，日程的安排要用确定。"}, {"text": "学校定形了上课的时间。", "explanation": "这里应该用〈规定〉。定形只指形状固定，学校对时间作出的安排要用规定。"}, {"text": "他定形了去北京的机票。", "explanation": "这里应该用〈订〉。定形指使形状固定，预订机票要用订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个陶杯烧好以后就很定形了。", "corrected_sentence": "这个陶杯烧好以后就定形了。", "error_description": "副词“很”一般修饰形容词或心理动词，不能直接修饰“定形”这类表示变化结果的动词，应删去“很”，写作“就定形了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石膏还没定形了，不能拿走。", "corrected_sentence": "这块石膏还没定形，不能拿走。", "error_description": "“还没”表示动作尚未发生，句末一般不加“了”，应写作“还没定形”；错误写成“还没定形了”，“了”与“还没”的未然语境不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
