INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "承载力就是能承受多少东西的力量。", "primary_collocate": null, "pronunciation": "chéng zài lì", "ipa": "ʈʂʰɤŋ³⁵ tsaɪ⁵¹ li⁵¹", "syllable_count": 3, "sentences": [{"text": "这张桌子的承载力很小，别放太重的东西。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旧天桥的承载力有多大？", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新桥的承载力是五十吨。", "target_word": "承载力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货车的承载力不够，一次拉不完。", "target_word": "承载力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这面墙的承载力不够，不能挂大画。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先测了楼板的承载力。", "target_word": "承载力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子的承载力是一百公斤。", "target_word": "承载力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰太薄了，承载力不够，人不能上去。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的承载力下降了，要小心。", "target_word": "承载力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子的承载力很高，可以吊起汽车。", "target_word": "承载力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西能承受多重的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "承载力", "is_correct": true, "explanation": "正确。“承载力”指物体能承受的重量上限，与“很小”和“别放太重的东西”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“很小”来描述大小，“这张桌子的颜色很小”句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”只用于人，桌子没有脾气，不能说“这张桌子的脾气很小”。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指人受教育的经历，不能用于描述桌子。"}], "explanations": {"承载力": "正确。“承载力”指物体能承受的重量上限，与“很小”和“别放太重的东西”的语境相符。", "颜色": "搭配：“颜色”不能用“很小”来描述大小，“这张桌子的颜色很小”句意不通。", "脾气": "语义：“脾气”只用于人，桌子没有脾气，不能说“这张桌子的脾气很小”。", "学历": "语义：“学历”指人受教育的经历，不能用于描述桌子。"}, "sentence_index": 0, "correct_answer": "承载力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气跑了五公里，承载力很强，没有停下。", "explanation": "这里应该用〈耐力〉。“承载力”指物体能承受的重量，人的持久力要用“耐力”。"}, {"text": "这个水杯的承载力很大，能装两升水。", "explanation": "这里应该用〈容量〉。“承载力”指承受重量，装液体的容积要用“容量”。"}, {"text": "他的数学承载力很强，考试总是第一。", "explanation": "这里应该用〈能力〉。“承载力”多指物体能承受的重量，不用于学习等方面的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承载力", "is_correct": true, "explanation": "正确。“承载力”指椅子能承受的重量，与“一百公斤”相符。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：“硬度”指材料抵抗压入的能力，不是能承受的重量，不能说“硬度是一百公斤”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”用于描述人的体型，椅子没有身材。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用重量单位“公斤”来表示。"}], "explanations": {"承载力": "正确。“承载力”指椅子能承受的重量，与“一百公斤”相符。", "硬度": "语义：“硬度”指材料抵抗压入的能力，不是能承受的重量，不能说“硬度是一百公斤”。", "身材": "体貌：“身材”用于描述人的体型，椅子没有身材。", "价格": "语义：“价格”指钱数，不能用重量单位“公斤”来表示。"}, "sentence_index": 6, "correct_answer": "承载力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱书的承载力是二十公斤。", "explanation": "这里应该用〈重量〉。“承载力”指物体能承受的最大重量，一箱书自身的重量要用“重量”。"}, {"text": "妹妹一年长高了，承载力增加了三公斤。", "explanation": "这里应该用〈体重〉。“承载力”指物体能承受的重量，人的体重增加要用“体重”。"}, {"text": "这笔学费是家里很大的承载力。", "explanation": "这里应该用〈负担〉。“承载力”指物体能承受多少重量，比喻经济压力时要说“负担”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥的承载力是五十只。", "corrected_sentence": "这座桥的承载力是五十吨。", "error_description": "“承载力”是重量指标，数值要用重量单位「吨」。「只」是动物量词，不能用于重量。错误句「五十只」应改为「五十吨」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老桥的承载力下降的。", "corrected_sentence": "这座老桥的承载力下降了。", "error_description": "错误：“下降的”。此处表示变化已经完成，应用动态助词“了”，不能用结构助词“的”。应说「承载力下降了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "反义。收缩指血管等器官体积变小，与扩张相对。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系。思考是心理活动，与血管的体积变化没有相对关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系。游泳是体育活动，与扩张不构成相对的概念。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系。散步是行走方式，与扩张不构成相对的概念。"}], "correct_answer": "收缩", "explanations": {"收缩": "反义。收缩指血管等器官体积变小，与扩张相对。", "思考": "无反义关系。思考是心理活动，与血管的体积变化没有相对关系。", "游泳": "无反义关系。游泳是体育活动，与扩张不构成相对的概念。", "散步": "无反义关系。散步是行走方式，与扩张不构成相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "反义。收缩指血管等器官体积变小，与扩张相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系。睡觉是生理活动，与血管的体积变化没有相对关系。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系。写作是创作行为，与扩张不构成相对的概念。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系。跳舞是身体动作，与扩张不构成相对的概念。"}], "correct_answer": "收缩", "explanations": {"收缩": "反义。收缩指血管等器官体积变小，与扩张相对。", "睡觉": "无反义关系。睡觉是生理活动，与血管的体积变化没有相对关系。", "写作": "无反义关系。写作是创作行为，与扩张不构成相对的概念。", "跳舞": "无反义关系。跳舞是身体动作，与扩张不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体器官、血管、瞳孔等的体积变大、张开。", "primary_collocate": null, "pronunciation": "kuò zhāng", "ipa": "kʰuɔ˥˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "吸气的时候，肺会扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很热，血管会扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在黑暗中，人的瞳孔会扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了酒以后，他的血管明显扩张了。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用药让他狭窄的血管扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏扩张时，血液流进心房。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人受到惊吓时，瞳孔会突然扩张。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后，胸腔扩张，呼吸变得更深。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胃扩张过，医生让他少吃点。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血管扩张后，脸会变得红红的。", "target_word": "扩张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩张了", "label": "体标：了"}, {"form": "扩张着", "label": "体标：着"}, {"form": "扩张过", "label": "体标：过"}, {"form": "擴張", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体器官、血管、瞳孔等体积变大、张开（如血管扩张、瞳孔扩张）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩张", "is_correct": true, "explanation": "正确。吸气时肺的体积变大，“肺会扩张”符合生理过程。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指水变成冰，肺不会结冰，与吸气无关。"}, {"text": "眨眼", "is_correct": false, "explanation": "搭配：“眨眼”的主语是眼睛，肺不能眨眼。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主体是人或发声器官，肺不能作为唱歌的主语。"}], "explanations": {"扩张": "正确。吸气时肺的体积变大，“肺会扩张”符合生理过程。", "结冰": "语义：“结冰”指水变成冰，肺不会结冰，与吸气无关。", "眨眼": "搭配：“眨眼”的主语是眼睛，肺不能眨眼。", "唱歌": "搭配：“唱歌”的主体是人或发声器官，肺不能作为唱歌的主语。"}, "sentence_index": 0, "correct_answer": "扩张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情去年明显扩张了。", "explanation": "这里应该用〈好转〉。心情的变化要说“好转”或“变坏”；“扩张”只用于器官或组织体积变大。"}, {"text": "这次手术后，他的心脏负担扩张了。", "explanation": "这里应该用〈增加〉。负担加重要说“增加”，“扩张”只用于器官或组织体积变大。"}, {"text": "他的压力扩张得很厉害。", "explanation": "这里应该用〈增大〉。压力的加重要说“增大”；“扩张”只说器官或组织体积变大，不用于压力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩张", "is_correct": true, "explanation": "正确。受惊吓时瞳孔会张大，“瞳孔会突然扩张”符合生理反应。"}, {"text": "闭合", "is_correct": false, "explanation": "搭配：“闭合”多用于眼皮或伤口，不能用来描述瞳孔的变化。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”的主体是植物，瞳孔不能发芽。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体变液体，与瞳孔在惊吓时的生理变化无关。"}], "explanations": {"扩张": "正确。受惊吓时瞳孔会张大，“瞳孔会突然扩张”符合生理反应。", "闭合": "搭配：“闭合”多用于眼皮或伤口，不能用来描述瞳孔的变化。", "发芽": "搭配：“发芽”的主体是植物，瞳孔不能发芽。", "融化": "语义：“融化”指固体变液体，与瞳孔在惊吓时的生理变化无关。"}, "sentence_index": 6, "correct_answer": "扩张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体重一年内扩张了十斤。", "explanation": "这里应该用〈增加〉。体重的增长要说“增加”，“扩张”只说器官或组织体积变大。"}, {"text": "他的身高扩张了十厘米。", "explanation": "这里应该用〈增长〉。身高的增加要说“增长”；“扩张”只说器官或组织的体积变大，不用于身高。"}, {"text": "他的成绩扩张了不少。", "explanation": "这里应该用〈提高〉。成绩的上升要说“提高”；“扩张”只说器官或组织体积变大，不能用于成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吸气的时候，肺很扩张。", "corrected_sentence": "吸气的时候，肺会明显扩张。", "error_description": "错误：“肺很扩张”。“扩张”是动词，不能直接受“很”修饰，应在“会”后用“明显”等状语修饰，说“会明显扩张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动后，胸腔扩张的很大。", "corrected_sentence": "运动后，胸腔扩张得很大。", "error_description": "错误：“扩张的很大”。表示程度的补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
