INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23512, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带领，就是走在前面，让别人跟着你走。", "primary_collocate": null, "pronunciation": "shuài", "ipa": "ʂwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "校长率代表团去日本访问。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长率队走在最前面。", "target_word": "率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他率几个学生参加了比赛。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师率全班同学去公园玩。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理率团队完成了这个项目。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王将军率军进了城。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长率政府代表团来到学校参观。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经率队拿过冠军。", "target_word": "率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游率游客走进了山洞。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村长率大家修好了那条路。", "target_word": "率", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "率领", "label": "复合"}, {"form": "率队", "label": "复合"}], "register": "书面", "sense_fingerprint": "率：走在前面带领队伍、团体等，让别人跟随", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23512, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "率", "is_correct": true, "explanation": "正确：率（shuài）指带领、走在前面。"}, {"text": "晒", "is_correct": false, "explanation": "「shài」与 shuài 只差介音 u，意思是晒太阳。"}, {"text": "甩", "is_correct": false, "explanation": "「shuǎi」与 shuài 声调不同（第三声），意思是甩开、扔。"}, {"text": "衰", "is_correct": false, "explanation": "「shuāi」与 shuài 声调不同（第一声），意思是衰弱。"}], "explanations": {"率": "正确：率（shuài）指带领、走在前面。", "晒": "「shài」与 shuài 只差介音 u，意思是晒太阳。", "甩": "「shuǎi」与 shuài 声调不同（第三声），意思是甩开、扔。", "衰": "「shuāi」与 shuài 声调不同（第一声），意思是衰弱。"}, "sentence_index": null, "correct_answer": "率"}, "level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语应是场所或展品，不能带“代表团”作宾语。"}, {"text": "包括", "is_correct": false, "explanation": "配价：“包括”后面接的是整体中的组成部分，不能接“去日本访问”这样的动词结构。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”搭配的是机器、物品，不能用于代表团。"}, {"text": "率", "is_correct": true, "explanation": "正确：率代表团即带领代表团，符合句意。"}], "explanations": {"参观": "配价：“参观”的宾语应是场所或展品，不能带“代表团”作宾语。", "包括": "配价：“包括”后面接的是整体中的组成部分，不能接“去日本访问”这样的动词结构。", "修理": "搭配：“修理”搭配的是机器、物品，不能用于代表团。", "率": "正确：率代表团即带领代表团，符合句意。"}, "sentence_index": 0, "correct_answer": "率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他率着妹妹的手去公园。", "explanation": "这里应该用〈拉〉。率是带领人员或队伍的动词，不能用于拉手这样的身体动作，应当说拉着妹妹的手。"}, {"text": "老师率那辆大巴去公园玩。", "explanation": "这里应该用〈乘坐〉。率的对象是人员或队伍，大巴是交通工具，不能被率领，表示坐车去要用乘坐。"}, {"text": "他每月都去财务室率工资。", "explanation": "这里应该用〈领〉。率表示带领，不能与工资搭配，领工资指取得薪水，要用领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23512, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "率", "is_correct": true, "explanation": "正确：率（shuài）指带领、走在前面。"}, {"text": "刷", "is_correct": false, "explanation": "「shuā」与 shuài 仅韵尾不同（ua／uai），意思是刷洗。"}, {"text": "摔", "is_correct": false, "explanation": "「shuāi」与 shuài 声调不同（第一声），意思是摔倒。"}, {"text": "涮", "is_correct": false, "explanation": "「shuàn」与 shuài 同为第四声，仅韵尾不同（n／i），意思是涮洗。"}], "explanations": {"率": "正确：率（shuài）指带领、走在前面。", "刷": "「shuā」与 shuài 仅韵尾不同（ua／uai），意思是刷洗。", "摔": "「shuāi」与 shuài 声调不同（第一声），意思是摔倒。", "涮": "「shuàn」与 shuài 同为第四声，仅韵尾不同（n／i），意思是涮洗。"}, "sentence_index": null, "correct_answer": "率"}, "level_3": {"options": [{"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”的对象是内容、知识，不能带“代表团”作宾语。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能用于代表团。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、物品，不能用于代表团。"}, {"text": "率", "is_correct": true, "explanation": "正确：率政府代表团即带领代表团，符合句意。"}], "explanations": {"讲解": "搭配：“讲解”的对象是内容、知识，不能带“代表团”作宾语。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能用于代表团。", "修理": "搭配：“修理”的对象是机器、物品，不能用于代表团。", "率": "正确：率政府代表团即带领代表团，符合句意。"}, "sentence_index": 6, "correct_answer": "率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他率了一把伞出门，以防下雨。", "explanation": "这里应该用〈带〉。率是带领人或队伍的动词，不能用于随身携带的物品，带伞出门要用带。"}, {"text": "他率着一本书走进教室。", "explanation": "这里应该用〈拿〉。率的宾语是人员或队伍，书是物品，不能被率领，手里拿着书要用拿。"}, {"text": "他率着菜篮子回家。", "explanation": "这里应该用〈提〉。率只能用于带领人员或队伍，菜篮子是物品，提着东西回家要用提。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "导演率一只剧组走进了摄影棚。", "corrected_sentence": "导演率一个剧组走进了摄影棚。", "error_description": "错误形式：一只剧组；正确形式：一个剧组。“剧组”是集体，应用通用量词“个”，“只”用于动物或单个物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练率得队员们走进了场地。", "corrected_sentence": "教练率队员们走进了场地。", "error_description": "错误形式：率得队员们；正确形式：率队员们。“率”直接带宾语（被带领的人），动词后的“得”只能引出补语，不能引出宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
