INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命题是一句可以判断对或错、需要证明的话。", "primary_collocate": null, "pronunciation": "mìng tí", "ipa": "miŋ˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这个命题是对的，我们可以证明它。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“所有的鸟都会飞”是一个错误的命题。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们证明这个命题。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提出了一个新命题。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个命题听起来对，其实是错的。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学课上，我们学习怎么证明命题。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个命题不是对，就是错。", "target_word": "命题", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个命题很简单，大家都能懂。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想证明这个命题是错的。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要说明命题是对的，需要有理由。", "target_word": "命题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "可以判断对错、需要证明的一句话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命题", "is_correct": true, "explanation": "命题是可以判断对错、需要证明的话，“这个命题是对的”说得通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是可以判断对错的话，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能判断对错，也不能被证明。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以证明对错的陈述，“证明它”说不通。"}], "explanations": {"命题": "命题是可以判断对错、需要证明的话，“这个命题是对的”说得通。", "桌子": "语义：桌子是家具，不是可以判断对错的话，句子说不通。", "天气": "语义：天气是自然现象，不能判断对错，也不能被证明。", "颜色": "语义：颜色不是可以证明对错的陈述，“证明它”说不通。"}, "sentence_index": 0, "correct_answer": "命题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个菜的命题很好。", "explanation": "这里应该用〈味道〉。命题是可以判断对错的话，菜的好坏要说“味道”。"}, {"text": "他吃了一个命题。", "explanation": "这里应该用〈苹果〉。命题是一句可判断对错的话，不能吃，能吃的应该是“苹果”。"}, {"text": "他在厨房里洗了一个命题。", "explanation": "这里应该用〈碗〉。命题是一句可判断对错的话，不能拿来洗；要洗的应该是“碗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命题", "is_correct": true, "explanation": "命题是可以判断对错的话，“一个命题不是对，就是错”说的正是它。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物，不能判断对错，句子说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“对”和“错”一般用于判断陈述，不能用来说钢琴。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是地方，不是可以判断对错的话。"}], "explanations": {"命题": "命题是可以判断对错的话，“一个命题不是对，就是错”说的正是它。", "花朵": "语义：花朵是植物，不能判断对错，句子说不通。", "钢琴": "搭配：“对”和“错”一般用于判断陈述，不能用来说钢琴。", "房间": "语义：房间是地方，不是可以判断对错的话。"}, "sentence_index": 6, "correct_answer": "命题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送给我一个命题作为生日礼物。", "explanation": "这里应该用〈礼物〉。命题是一句可判断对错的话，不能拿来送人。"}, {"text": "他唱了一个好听的命题。", "explanation": "这里应该用〈歌〉。命题是可以判断对错的话，不能用来唱，唱的应该是“歌”。"}, {"text": "他骑走了一个命题，没有告诉别人。", "explanation": "这里应该用〈自行车〉。命题是一句可判断对错的话，不能骑；能骑走的应该是“自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师请我们解释这只命题。", "corrected_sentence": "老师请我们解释这个命题。", "error_description": "错误量词是“只”，正确量词是“个”。“只”用于动物，命题要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们还没证明这条命题。", "corrected_sentence": "我们还没证明这个命题。", "error_description": "量词错了：“命题”一般用“个”，说“这个命题”；“条”多用于细长的东西或新闻、规定等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静态", "is_correct": true, "explanation": "反义：“静态”指静止不动的，与“动态”（会动的）相对。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”描述光线或颜色，与“动态”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”描述质地，与“动态”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：“陡峭”描述地势，与“动态”没有反义关系。"}], "correct_answer": "静态", "explanations": {"静态": "反义：“静态”指静止不动的，与“动态”（会动的）相对。", "明亮": "无关：“明亮”描述光线或颜色，与“动态”没有反义关系。", "柔软": "无关：“柔软”描述质地，与“动态”没有反义关系。", "陡峭": "无关：“陡峭”描述地势，与“动态”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静态", "is_correct": true, "explanation": "反义：“静态”指静止不动的，与“动态”相对。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：“粗糙”描述表面质地，与“动态”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：“潮湿”描述含水多的状态，与“动态”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”描述清楚的程度，与“动态”没有反义关系。"}], "correct_answer": "静态", "explanations": {"静态": "反义：“静态”指静止不动的，与“动态”相对。", "粗糙": "无关：“粗糙”描述表面质地，与“动态”没有反义关系。", "潮湿": "无关：“潮湿”描述含水多的状态，与“动态”没有反义关系。", "清晰": "无关：“清晰”描述清楚的程度，与“动态”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西在动，不是停着的。", "primary_collocate": null, "pronunciation": "dòng tài", "ipa": "tʊŋ˥˩ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这张图片是动态的。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢动态的壁纸。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个屏幕上有动态的画面。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动态图片比静态图片更好玩。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机桌面是动态的。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是动态的，鱼会在水里游。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看动态的漫画。", "target_word": "动态", "complexity_tier": "T3", "furigana": "háizimen xǐhuan kàn dòngtài de mànhuà.", "sentence_source": "generated"}, {"text": "动态的画面让电影更好看。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的图标是动态的。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一张动态的地图。", "target_word": "动态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动态的", "label": "的字结构"}, {"form": "動態", "label": "繁体"}], "register": "中性", "sense_fingerprint": "图像、画面等会动的，不是静止的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动态", "is_correct": true, "explanation": "正确：“动态”形容画面会动，可以用来描述图片。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，图片没有味道，不能说“甜的图片”。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，与“图片”搭配不当。"}, {"text": "臭", "is_correct": false, "explanation": "语义：“臭”指气味难闻，与图片的特点不符。"}], "explanations": {"动态": "正确：“动态”形容画面会动，可以用来描述图片。", "甜": "语义：“甜”描述味道，图片没有味道，不能说“甜的图片”。", "咸": "搭配：“咸”形容味道，与“图片”搭配不当。", "臭": "语义：“臭”指气味难闻，与图片的特点不符。"}, "sentence_index": 0, "correct_answer": "动态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头是动态的，它一直静静地躺在河边。", "explanation": "这里应该用〈静止〉。“动态”指东西在动，石头一直躺在河边不动，要说“静止”。"}, {"text": "这张桌子是动态的，放在那里好几年都没动过。", "explanation": "这里应该用〈固定〉。“动态”指东西在动，桌子好几年都没动过，要说“固定”。"}, {"text": "墙上的那幅字是动态的，挂了好几年。", "explanation": "这里应该用〈静态〉。“动态”指东西在动，字挂在墙上不动，要说“静态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动态", "is_correct": true, "explanation": "正确：“动态”形容画面会动，可以修饰“漫画”。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”描述质地，漫画的内容不是质地，不能说“硬的漫画”。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”一般用于说物体潮湿，不能用来说漫画。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”描述温度，漫画不能是烫的，语义不合。"}], "explanations": {"动态": "正确：“动态”形容画面会动，可以修饰“漫画”。", "硬": "语义：“硬”描述质地，漫画的内容不是质地，不能说“硬的漫画”。", "湿": "搭配：“湿”一般用于说物体潮湿，不能用来说漫画。", "烫": "语义：“烫”描述温度，漫画不能是烫的，语义不合。"}, "sentence_index": 6, "correct_answer": "动态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的老钟是动态的，指针停在十二点，好几年都没动过。", "explanation": "这里应该用〈静止〉。“动态”指东西在动，指针一直不动，要说“静止”。"}, {"text": "我家的老沙发是动态的，在客厅里放了二十年。", "explanation": "这里应该用〈固定〉。“动态”指东西在动，沙发一直放着不动，要说“固定”。"}, {"text": "那个花瓶是动态的，一直摆在柜子上。", "explanation": "这里应该用〈静态〉。“动态”指东西在动，花瓶摆着不动，要说“静态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个海报是动态。", "corrected_sentence": "这个海报是动态的。", "error_description": "“是……的”结构中，形容词“动态”后要带“的”，应说“是动态的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "动态地画面让游戏更好玩。", "corrected_sentence": "动态的画面让游戏更好玩。", "error_description": "“动态”是形容词，修饰名词“画面”时要用“的”，不能用表示方式的“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
