INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "减少排放，就是少放出脏东西。", "primary_collocate": null, "pronunciation": "jiǎn pái", "ipa": "tɕjɛn˨˩˦ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "工厂减排以后，天空变蓝了。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家用电少一点，也是在减排。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了减排，城里的公交车换成了电车。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们学校开了一节关于减排的课。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "减排能让空气变干净。", "target_word": "减排", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们想一想怎么减排。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂去年开始减排了。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多走路，少开车，就能帮助减排。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起减排，河水也会更清。", "target_word": "减排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的小工厂必须减排，不然就要关门。", "target_word": "减排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减排了", "label": "体标"}, {"form": "减排过", "label": "体标"}, {"form": "节能减排", "label": "复合"}], "register": "中性", "sense_fingerprint": "少排出废气、脏水等有害东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减排", "is_correct": true, "explanation": "正确。“工厂减排以后”指工厂减少排放，之后天空变蓝，前后相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：工厂不会睡觉，“工厂睡觉以后，天空变蓝了”不成立。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：工厂不能结婚，句子无法与“天空变蓝了”建立合理关联。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“工厂”一般不与“散步”搭配，句子说不通。"}], "explanations": {"减排": "正确。“工厂减排以后”指工厂减少排放，之后天空变蓝，前后相合。", "睡觉": "语义：工厂不会睡觉，“工厂睡觉以后，天空变蓝了”不成立。", "结婚": "语义：工厂不能结婚，句子无法与“天空变蓝了”建立合理关联。", "散步": "搭配：“工厂”一般不与“散步”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "减排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的失业率减排了。", "explanation": "这里应该用〈降低〉。减排只用于排放物，失业率要用降低。"}, {"text": "他们学校减排了一笔钱。", "explanation": "这里应该用〈节约〉。减排的对象是排放物，钱要用节约。"}, {"text": "他的负担减排了许多。", "explanation": "这里应该用〈减轻〉。减排只用于排放物，负担要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减排", "is_correct": true, "explanation": "正确。“这家工厂去年开始减排了”指工厂去年开始减少排放，句意通顺。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：工厂不会毕业，“这家工厂去年开始毕业了”句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“工厂”不会“唱歌”，“这家工厂去年开始唱歌了”句意不通。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“工厂”一般不说“辞职”，与“去年开始”搭配不当。"}], "explanations": {"减排": "正确。“这家工厂去年开始减排了”指工厂去年开始减少排放，句意通顺。", "毕业": "语义：工厂不会毕业，“这家工厂去年开始毕业了”句意不通。", "唱歌": "搭配：“工厂”不会“唱歌”，“这家工厂去年开始唱歌了”句意不通。", "辞职": "搭配：“工厂”一般不说“辞职”，与“去年开始”搭配不当。"}, "sentence_index": 6, "correct_answer": "减排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把路程减排了两公里。", "explanation": "这里应该用〈缩短〉。减排只用于废气、二氧化碳等排放物，路程要用缩短。"}, {"text": "政府减排了这家企业的税。", "explanation": "这里应该用〈减免〉。减排的对象是排放物，税要用减免。"}, {"text": "编辑减排了书稿的三章。", "explanation": "这里应该用〈删减〉。减排不能用于书稿的章节，删去章节要用删减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里的小工厂今年减排了了不少。", "corrected_sentence": "城里的小工厂今年减排了不少。", "error_description": "“了”在这里只用一个。“减排了不少”中的“了”已表示完成，多写一个“了”是重复的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里的小工厂前年减排过三成过的废气。", "corrected_sentence": "城里的小工厂前年减排过三成的废气。", "error_description": "“过”只用一次，紧跟动词。“减排过三成的废气”中的“过”已表示完成，在“三成”后又多加一个“过”，位置和数量都错了，应删去后面这个“过”，说“减排过三成的废气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
