INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西坏了，可以再做成新的。", "primary_collocate": null, "pronunciation": "zài shēng", "ipa": "tsaɪ̯˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "坏了的旧家具可以再生，做成新桌子。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧瓶子再生以后，变成了杯子。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧毛衣再生以后，变成了新的毛线。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "破了的轮胎再生后，还能用。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂回收的旧电池经过再生，做成了新电池。", "target_word": "再生", "complexity_tier": "T3", "furigana": "gōngchǎng huíshōu de jiù diànchí jīngguò zàishēng, zuòchéng le xīn diànchí。", "sentence_source": "generated"}, {"text": "坏掉的纸箱再生以后，就能变成新的盒子。", "target_word": "再生", "complexity_tier": "T3", "furigana": "huàidiào de zhǐxiāng zàishēng yǐhòu, jiù néng biànchéng xīn de hézi。", "sentence_source": "generated"}, {"text": "这些旧布料可以再生，不用扔。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧铁可以再生，不要随便扔掉。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的坏东西，大多数都能再生，不必扔掉。", "target_word": "再生", "complexity_tier": "T3", "furigana": "jiālǐ de huài dōngxi, dàduōshù dōu néng zàishēng, búbì rēngdiào。", "sentence_source": "generated"}, {"text": "旧报纸再生以后，能做成笔记本。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生纸", "label": "复合"}, {"form": "再生胶", "label": "复合"}], "register": "中性", "sense_fingerprint": "坏了或旧了的东西重新加工成新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指坏了或旧了的东西重新加工成新东西。"}, {"text": "再争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。"}, {"text": "再深", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。"}, {"text": "再胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指坏了或旧了的东西重新加工成新东西。", "再争": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。", "再深": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。", "再胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：旧家具经加工可以重新制成新东西，符合“再生”的意思。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃是扔掉，与“做成新桌子”的结果矛盾。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是彻底毁掉，之后无法再做成桌子。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废指作废、不能再用，与“再做成新桌子”的结果矛盾。"}], "explanations": {"再生": "正确：旧家具经加工可以重新制成新东西，符合“再生”的意思。", "丢弃": "语义：丢弃是扔掉，与“做成新桌子”的结果矛盾。", "烧毁": "语义：烧毁是彻底毁掉，之后无法再做成桌子。", "报废": "语义：报废指作废、不能再用，与“再做成新桌子”的结果矛盾。"}, "sentence_index": 0, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在再生这位病人。", "explanation": "这里应该用〈治疗〉。再生指旧东西加工成新的，对病人要“治疗”，不能说“再生”。"}, {"text": "这辆自行车坏了，再生一下就能骑。", "explanation": "这里应该用〈修理〉。再生指把旧材料加工成新产品，坏了的自行车要“修理”。"}, {"text": "环卫工人每天再生小区的街道。", "explanation": "这里应该用〈清扫〉。再生指旧东西加工成新的，小区街道要“清扫”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23524, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指坏了或旧了的东西重新加工成新东西。"}, {"text": "再扔", "is_correct": false, "explanation": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。"}, {"text": "再伸", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。"}, {"text": "再称", "is_correct": false, "explanation": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指坏了或旧了的东西重新加工成新东西。", "再扔": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。", "再伸": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。", "再称": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：旧布料加工后能重新利用，与“不用扔”的意思一致。"}, {"text": "遗弃", "is_correct": false, "explanation": "语义：“遗弃”是扔下不管，与“不用扔”的句意相反。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与“不用扔”的意思相反。"}, {"text": "烧制", "is_correct": false, "explanation": "搭配：烧制多用于陶瓷、砖瓦，不能用于布料。"}], "explanations": {"再生": "正确：旧布料加工后能重新利用，与“不用扔”的意思一致。", "遗弃": "语义：“遗弃”是扔下不管，与“不用扔”的句意相反。", "销毁": "语义：销毁是彻底毁掉，与“不用扔”的意思相反。", "烧制": "搭配：烧制多用于陶瓷、砖瓦，不能用于布料。"}, "sentence_index": 6, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用水泥再生了墙上的裂缝。", "explanation": "这里应该用〈修补〉。再生指旧东西加工成新的，墙上的裂缝只是补好，要说“修补”，不能说“再生”。"}, {"text": "衣服脏了，再生一下就干净了。", "explanation": "这里应该用〈清洗〉。再生指旧材料加工成新产品，脏衣服要“清洗”，不能说“再生”。"}, {"text": "这套老房子已经再生了，看起来像新的一样。", "explanation": "这里应该用〈翻新〉。再生指把旧材料加工成新产品，房子整修变新要说“翻新”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧木板可以再生书架。", "corrected_sentence": "这些旧木板可以再生成新的书架。", "error_description": "“再生”后漏掉了结果补语“成”。表示加工成某种新物品，要说“再生成”，直接接“书架”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧布料再生了过一次，又做成了新衣服。", "corrected_sentence": "这些旧布料再生过一次，又做成了新衣服。", "error_description": "“再生”后同时用了“了”和“过”。表示经历过一次，只用“过”，应去掉“了”，说“再生过一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
