INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "污染物是让空气、水或土地变脏的东西。", "primary_collocate": null, "pronunciation": "wū rǎn wù", "ipa": "u˥ ʐan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "工厂排出的污染物让河水变黑了。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车排出的污染物会让空气变脏。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市要减少空气中的污染物。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在检查湖水里有没有污染物。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾烧着的时候，会放出很多污染物。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染物进入土地以后，农作物也会受影响。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂把污染物处理好以后才排放。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，空气里的污染物会少一些。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的鱼死了，原因是水里有污染物。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用机器收集海水里的污染物。", "target_word": "污染物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "大气污染物", "label": "复合"}], "register": "中性", "sense_fingerprint": "让空气、水、土地变脏的有害物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染物", "is_correct": true, "explanation": "污染物是排出后会让河水变脏的有害物质，符合「工厂排出的」和「让河水变黑」的句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是工厂排出的东西，也不会让河水变黑。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是排出的物质，句子说的是工厂的排放造成的后果。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：「排出」要接废弃物质，不能接时间名词「春天」。"}], "explanations": {"污染物": "污染物是排出后会让河水变脏的有害物质，符合「工厂排出的」和「让河水变黑」的句意。", "蛋糕": "语义：蛋糕不是工厂排出的东西，也不会让河水变黑。", "课本": "语义：课本不是排出的物质，句子说的是工厂的排放造成的后果。", "春天": "搭配：「排出」要接废弃物质，不能接时间名词「春天」。"}, "sentence_index": 0, "correct_answer": "污染物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房用污染物炒了一盘青菜。", "explanation": "这里应该用〈油〉。油可以用来炒菜，污染物是有害物质，不能拿来烹饪。"}, {"text": "门口的那辆污染物已经很旧了。", "explanation": "这里把污染物当成了车辆来计量。污染物是有害物质，计量它要用〈种〉，不能用车辆的量词。"}, {"text": "这个垃圾桶里有一只污染物。", "explanation": "这里把污染物当成了动物来计量。污染物是物质，计量它要用〈种〉，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染物", "is_correct": true, "explanation": "污染物是需要处理后才能排放的废弃有害物质，符合句意。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：排放的只能是废弃物质，盘子不能被「处理好以后才排放」。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「排放」通常接废气、污水等，不接「作业」。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不能被「排放」，这句话的意思荒谬。"}], "explanations": {"污染物": "污染物是需要处理后才能排放的废弃有害物质，符合句意。", "盘子": "语义：排放的只能是废弃物质，盘子不能被「处理好以后才排放」。", "作业": "搭配：「排放」通常接废气、污水等，不接「作业」。", "孩子": "语义：孩子不能被「排放」，这句话的意思荒谬。"}, "sentence_index": 6, "correct_answer": "污染物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把这些污染物晒在院子里，准备过冬。", "explanation": "这里应该用〈粮食〉。粮食可以晒干储存，污染物是有害物质，不能拿来晾晒过冬。"}, {"text": "博物馆里陈列着一件珍贵的污染物，值得好好保存。", "explanation": "这里应该用〈文物〉。文物有历史和艺术价值，值得保存；污染物指有害物质，不能用来珍藏。"}, {"text": "这座化工厂是城市里主要的污染物。", "explanation": "这里应该用〈污染源〉。污染物是有害的物质，工厂是产生污染的来源，不能说工厂本身是污染物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把地上的污染物们清理掉了。", "corrected_sentence": "工人把地上的污染物清理掉了。", "error_description": "错误在于「污染物」后多加了复数词尾「们」。「们」一般只用于指人，不能用于「污染物」这类物质名词，应去掉「们」，说「地上的污染物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前见过这只污染物。", "corrected_sentence": "我们以前见过这种污染物。", "error_description": "「污染物」的量词应用「种」，「只」多用于动物或成对物件中的一个，不能用于污染物，应说「这种污染物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
