INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里让车和人走的路。", "primary_collocate": null, "pronunciation": "chéng shì dào lù", "ipa": "ʈʂʰɤŋ˧˥ ʂɻ̩˥˩ taʊ˥˩ lu˥˩", "syllable_count": 4, "sentences": [{"text": "城市道路是让车和人走的路。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，城市道路两边的灯都亮了。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条城市道路很宽，有六条车道。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天沿着城市道路走路去上班。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路上的车太多，公交车开得很慢。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班时间，城市道路上都是回家的人和车。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子走过城市道路时，要看红绿灯。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在夜里维修城市道路。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环卫工人把城市道路打扫得很干净。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市道路中间有斑马线，行人可以从那里过去。", "target_word": "城市道路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "城市里让车和人走的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市道路", "is_correct": true, "explanation": "正确：城市道路指城市里让车和人通行的路，与定义完全吻合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是供车和人通行的路，句意不通。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野不是供车辆和行人通行的道路。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能与“让车和人走的路”搭配，车和人无法在天空中通行。"}], "explanations": {"城市道路": "正确：城市道路指城市里让车和人通行的路，与定义完全吻合。", "海洋": "语义：海洋不是供车和人通行的路，句意不通。", "田野": "语义：田野不是供车辆和行人通行的道路。", "天空": "搭配：“天空”不能与“让车和人走的路”搭配，车和人无法在天空中通行。"}, "sentence_index": 0, "correct_answer": "城市道路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在城市道路上种庄稼。", "explanation": "这里应该用〈农田〉。庄稼要种在田地里，城市道路是供车和人走的路，不能用来种庄稼。"}, {"text": "他沿着城市道路走上七楼。", "explanation": "这里应该用〈楼梯〉。“走上七楼”的路径应是楼梯，城市道路不能用来上楼。"}, {"text": "这是他人生中一条很长的城市道路。", "explanation": "这里应该用〈历程〉。“人生的道路”指经历的过程，“城市道路”只指城市里让车和人走的路，不能这样比喻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市道路", "is_correct": true, "explanation": "正确：城市道路上有红绿灯，孩子经过时需要看，句意相合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间里没有红绿灯，“要看红绿灯”与房间不相合。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场一般没有红绿灯，与“要看红绿灯”不符。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里一般没有红绿灯，“走过森林时要看红绿灯”与常识不符。"}], "explanations": {"城市道路": "正确：城市道路上有红绿灯，孩子经过时需要看，句意相合。", "房间": "语义：房间里没有红绿灯，“要看红绿灯”与房间不相合。", "操场": "语义：操场一般没有红绿灯，与“要看红绿灯”不符。", "森林": "语义：森林里一般没有红绿灯，“走过森林时要看红绿灯”与常识不符。"}, "sentence_index": 6, "correct_answer": "城市道路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在城市道路里游了一百米。", "explanation": "这里应该用〈泳道〉。泳道是游泳池中划分的水道，城市道路不能用来游泳。"}, {"text": "货船在城市道路上行驶。", "explanation": "这里应该用〈航道〉。货船行驶在水上的航道，城市道路不是水上通道。"}, {"text": "飞机在城市道路上起飞。", "explanation": "这里应该用〈跑道〉。飞机要在跑道上起飞，城市道路是供车和人走的路，不能用来起飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近新修了一座城市道路。", "corrected_sentence": "我家附近新修了一条城市道路。", "error_description": "量词错误：“座”多用于山、桥、楼等大型固定建筑，道路应用量词“条”，应为“一条城市道路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都从这条的城市道路去学校。", "corrected_sentence": "我每天都从这条城市道路去学校。", "error_description": "助词错误：“这条”与名词之间不能加“的”，应去掉“的”，为“这条城市道路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
