INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用掉一些东西或时间。", "primary_collocate": null, "pronunciation": "zhàn yòng", "ipa": "ʈʂan˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个游戏占用很多时间。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做作业占用了我的周末。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片占用了不少内存。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的事占用她大部分时间。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天开车要占用我一个小时。", "target_word": "占用", "complexity_tier": "T3", "furigana": "měi tiān kāi chē yào zhàn yòng wǒ yí gè xiǎo shí。", "sentence_source": "generated"}, {"text": "这个软件占用了很多存储空间。", "target_word": "占用", "complexity_tier": "T3", "furigana": "zhè ge ruǎn jiàn zhàn yòng le hěn duō cún chǔ kōng jiān。", "sentence_source": "generated"}, {"text": "电话占用了我午饭的时间。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告占用了他三个晚上。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段视频占用了手机很大的空间。", "target_word": "占用", "complexity_tier": "T3", "furigana": "zhè duàn shì pín zhàn yòng le shǒu jī hěn dà de kōng jiān。", "sentence_source": "generated"}, {"text": "聊天占用了我们半小时。", "target_word": "占用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占用了", "label": "体标（了）"}, {"form": "占用着", "label": "体标（着）"}, {"form": "占用过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "某件事耗去时间、内存、电量等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占用", "is_correct": true, "explanation": "占用：表示游戏耗去大量时间，与“很多时间”搭配。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜”要求有意识的人作主语，“这个游戏”是物，不能珍惜时间。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”要搭配作品、风景等，不能说欣赏时间。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”要搭配物品、文件等，不能收藏时间。"}], "explanations": {"占用": "占用：表示游戏耗去大量时间，与“很多时间”搭配。", "珍惜": "语义：“珍惜”要求有意识的人作主语，“这个游戏”是物，不能珍惜时间。", "欣赏": "搭配：“欣赏”要搭配作品、风景等，不能说欣赏时间。", "收藏": "搭配：“收藏”要搭配物品、文件等，不能收藏时间。"}, "sentence_index": 0, "correct_answer": "占用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上占用一杯牛奶。", "explanation": "这里应该用〈喝〉。喝牛奶要用喝；占用指某件事耗去时间、空间等资源，不能用于饮食。"}, {"text": "他占用了一块蛋糕。", "explanation": "这里应该用〈吃〉。占用指耗用时间、空间等资源，吃蛋糕不能用占用。"}, {"text": "她占用了我的名字。", "explanation": "占用的对象应是时间、空间等可被耗用的资源，名字不能被占用，这种情况应说“冒用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占用", "is_correct": true, "explanation": "占用：表示电话耗去了我的午饭时间，与“时间”搭配。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”要求有感受的主语，“电话”不能享受午饭的时间。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”搭配房间、物品等，不能装饰时间。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”搭配画面、人物等，不能拍摄时间。"}], "explanations": {"占用": "占用：表示电话耗去了我的午饭时间，与“时间”搭配。", "享受": "语义：“享受”要求有感受的主语，“电话”不能享受午饭的时间。", "装饰": "搭配：“装饰”搭配房间、物品等，不能装饰时间。", "拍摄": "搭配：“拍摄”搭配画面、人物等，不能拍摄时间。"}, "sentence_index": 6, "correct_answer": "占用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支部队占用了那座山头的笑声。", "explanation": "笑声不是可被耗用的时间或空间，“占用”在此说不通。"}, {"text": "我们占用了这次比赛的冠军。", "explanation": "冠军是称号，不能被占用；占用的对象是时间、空间等资源，这里应说“夺得冠军”。"}, {"text": "我们占用了这顿美味。", "explanation": "这里应该用〈享用〉。占用指耗用时间、空间，享用指愉快地品尝美好的东西，美味不能被占用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏正在占用了我一个小时。", "corrected_sentence": "这个游戏占用了我一个小时。", "error_description": "体标冲突：“正在”表示动作进行中，与“了”表示完成不能同时用于“占用”。应说“这个游戏正在占用我一个小时”或“这个游戏占用了我一个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次检查占用在我一个上午。", "corrected_sentence": "这次检查占用了我一个上午。", "error_description": "误加介词：“占用”是及物动词，后面直接接宾语，不能加“在”。应说“占用了我一个上午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
