INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猫、狗、花、树这样活着的东西就是生物。", "primary_collocate": null, "pronunciation": "shēng wù", "ipa": "ʂɤŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "猫、狗、花、树都是生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头不是生物，它不会长大。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里有很多我们不认识的生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小生物只在夜里出来。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物需要水和空气才能活着。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮上没有水，也没有生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的生物很多，有鸟、鱼和花草。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光对所有生物都很重要。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些生物小得用眼睛看不见。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在山里发现了一种新的生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "微生物", "label": "复合"}, {"form": "生物学", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物：有生命、活着的东西，如动物和植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d347d6-cd46-4fd0-a1a8-e1f8b84db37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“生物”指有生命的东西，如动物、植物。"}, {"text": "圣物", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣的物品。"}, {"text": "生育", "is_correct": false, "explanation": "韵母不同：wù 为 u，yù 为 ü（w、y 只是零声母的拼写形式）；“生育”意思是生孩子、繁殖。"}, {"text": "失误", "is_correct": false, "explanation": "shī 与 shēng 韵母不同，意思是做错事、出差错。"}], "explanations": {"生物": "正确：“生物”指有生命的东西，如动物、植物。", "圣物": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣的物品。", "生育": "韵母不同：wù 为 u，yù 为 ü（w、y 只是零声母的拼写形式）；“生育”意思是生孩子、繁殖。", "失误": "shī 与 shēng 韵母不同，意思是做错事、出差错。"}, "sentence_index": null, "correct_answer": "生物"}, "level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“猫、狗、花、树都是生物”中，“生物”指有生命的东西，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：猫、狗、花、树都是有生命的东西，不是垃圾，句子意思不通。"}, {"text": "工具", "is_correct": false, "explanation": "语义：猫、狗、花、树不是工具，不能说“都是工具”。"}, {"text": "家具", "is_correct": false, "explanation": "语义：猫、狗、花、树不是家具，不能说“都是家具”。"}], "explanations": {"生物": "正确：“猫、狗、花、树都是生物”中，“生物”指有生命的东西，符合句意。", "垃圾": "语义：猫、狗、花、树都是有生命的东西，不是垃圾，句子意思不通。", "工具": "语义：猫、狗、花、树不是工具，不能说“都是工具”。", "家具": "语义：猫、狗、花、树不是家具，不能说“都是家具”。"}, "sentence_index": 0, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生物很健康，经常去跑步。", "explanation": "这里应该用〈身体〉。“生物”指有生命的东西，不指人的身体；说身体健康要用身体。"}, {"text": "他为了朋友，愿意付出自己的生物。", "explanation": "这里应该用〈生命〉。“生物”指有生命的东西，不指生命本身；“付出生命”是固定说法。"}, {"text": "张老师是一个非常负责的生物。", "explanation": "这里应该用〈人〉。“生物”指动物、植物等有生命的东西，形容一个人的品质要用“人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“这里的生物很多，有鸟、鱼和花草”中，“生物”指有生命的东西，符合句意。"}, {"text": "家具", "is_correct": false, "explanation": "语义：句子列举的是鸟、鱼和花草，与家具无关，“家具”不能这样并列。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是有生命的东西，不能和鸟、鱼、花草并列，句子不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是鸟、鱼、花草一类，与句中列举的内容不符。"}], "explanations": {"生物": "正确：“这里的生物很多，有鸟、鱼和花草”中，“生物”指有生命的东西，符合句意。", "家具": "语义：句子列举的是鸟、鱼和花草，与家具无关，“家具”不能这样并列。", "天气": "语义：天气不是有生命的东西，不能和鸟、鱼、花草并列，句子不通。", "乐器": "语义：乐器不是鸟、鱼、花草一类，与句中列举的内容不符。"}, "sentence_index": 6, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生物很开放，喜欢交朋友。", "explanation": "这里应该用〈思想〉。“生物”指有生命的东西，不指人的观念；形容思想开放要用思想。"}, {"text": "今天的生物很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“生物”指有生命的东西，不指天气情况；形容天气好要用天气。"}, {"text": "这道菜的生物很好，我吃了三碗。", "explanation": "这里应该用〈味道〉。“生物”指有生命的东西，不指食物的味道；形容味道好要用味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘里有一块很小的生物。", "corrected_sentence": "池塘里有一种很小的生物。", "error_description": "量词错误：“生物”应该用量词“种”（或“个”），“块”用于块状的东西，不能用来数生物。应为「池塘里有一种很小的生物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深海里生活着一些发光地生物。", "corrected_sentence": "深海里生活着一些发光的生物。", "error_description": "结构助词错误：修饰名词“生物”要用“的”，“地”用于修饰动词。应为「发光的生物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
