INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们可以去那里散步、玩耍的地方。", "primary_collocate": null, "pronunciation": "gōng yuán", "ipa": "kʊŋ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "周末我们一家去公园散步。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多孩子在玩。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家旁边有一个大公园。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们早上在公园里打太极拳。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的湖边开满了花。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在公园的长椅上聊天。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步到公园再回家。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，公园里的树都绿了。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，公园里一个人也没有。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想去公园放风筝。", "target_word": "公园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "供人散步玩耍的公共园地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公园", "is_correct": true, "explanation": "正确：“公园”是供人散步的地方，与“周末我们一家去……散步”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“散步”一般在户外，厨房不是散步的地方。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是散步的场所。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书阅读的地方，不适合散步。"}], "explanations": {"公园": "正确：“公园”是供人散步的地方，与“周末我们一家去……散步”相符。", "厨房": "搭配：“散步”一般在户外，厨房不是散步的地方。", "教室": "语义：教室是上课的地方，不是散步的场所。", "图书馆": "语义：图书馆是借书阅读的地方，不适合散步。"}, "sentence_index": 0, "correct_answer": "公园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把公园放进了书包里。", "explanation": "语义：“公园”是一个很大的场所，不能放进书包，能放进书包的是书、本子等东西。"}, {"text": "我家门口有一只公园。", "explanation": "量词：“公园”应用“座”，“只”用于动物。"}, {"text": "我昨天去了一所公园。", "explanation": "量词：这里应该用〈座〉。“所”用于学校、医院等，“公园”用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公园", "is_correct": true, "explanation": "正确：“跑步到公园再回家”中的“公园”是可以到达的地点，符合语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是可以“跑步到”的地点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能作跑步的目的地。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“到”后应接地点，“电脑”不能作跑步的目的地。"}], "explanations": {"公园": "正确：“跑步到公园再回家”中的“公园”是可以到达的地点，符合语境。", "书": "语义：书不是可以“跑步到”的地点。", "天空": "语义：天空不能作跑步的目的地。", "电脑": "搭配：“到”后应接地点，“电脑”不能作跑步的目的地。"}, "sentence_index": 6, "correct_answer": "公园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们院子里有一张公园。", "explanation": "量词：这里应该用〈座〉。“张”用于纸、桌子等平面的东西，不用于公园。"}, {"text": "这辆公园很大。", "explanation": "量词：“公园”应用“座”，“辆”用于车。"}, {"text": "我家院子里有一个小公园，种着我妈妈的花。", "explanation": "这里应该用〈花园〉。“公园”是大家都可以去的公共地方，自己家院子里种花的地方叫“花园”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一条公园里野餐。", "corrected_sentence": "我们在公园里野餐。", "error_description": "量词错误：“公园”前不能用量词“条”，“条”用于细长的东西。应说“我们在公园里野餐”，或用“座”（一座公园）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末他们去一只公园跑步。", "corrected_sentence": "周末他们去一座公园跑步。", "error_description": "量词错误：“公园”应用量词“座”，“只”用于动物，不能修饰“公园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加剧", "is_correct": true, "explanation": "“加剧”指使不好的情况更加严重，与“缓解”是反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音唱曲子，与“缓解”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是慢慢走路放松身体的动作，与“缓解”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“缓解”没有反义关系。"}], "correct_answer": "加剧", "explanations": {"加剧": "“加剧”指使不好的情况更加严重，与“缓解”是反义关系。", "唱歌": "“唱歌”指用声音唱曲子，与“缓解”没有反义关系。", "散步": "“散步”是慢慢走路放松身体的动作，与“缓解”没有反义关系。", "旅行": "“旅行”指到外地游览，与“缓解”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加剧", "is_correct": true, "explanation": "“加剧”指使不好的情况更加严重，与“缓解”是反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中运动，与“缓解”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”指用笔作画，与“缓解”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "“跳舞”指随音乐做动作，与“缓解”没有反义关系。"}], "correct_answer": "加剧", "explanations": {"加剧": "“加剧”指使不好的情况更加严重，与“缓解”是反义关系。", "游泳": "“游泳”指在水中运动，与“缓解”没有反义关系。", "画画": "“画画”指用笔作画，与“缓解”没有反义关系。", "跳舞": "“跳舞”指随音乐做动作，与“缓解”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让不好的感觉或情况变轻或消失。", "primary_collocate": null, "pronunciation": "huǎn jiě", "ipa": "xwan²¹⁴ tɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "喝点热水可以缓解喉咙疼。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能缓解头疼。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐可以缓解紧张。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息一会儿，累的感觉就缓解了。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场雨缓解了夏天的炎热。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他散步来缓解工作的压力。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按一按肩膀，可以缓解疼痛。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路开通后，城市的堵车缓解了很多。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话缓解了我的不安。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水能缓解感冒带来的难受。", "target_word": "缓解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缓解了", "label": "体标"}, {"form": "缓解过", "label": "体标"}, {"form": "缓解着", "label": "体标"}], "register": "中性", "sense_fingerprint": "缓解|动词|使不好的感觉或情况变轻、变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓解", "is_correct": true, "explanation": "“缓解”指让不好的感觉变轻，这里说热水能让喉咙疼变轻。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“喝点热水可以”是推荐的做法，“加重”喉咙疼与此矛盾。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：热水不能让人“发烧喉咙疼”，这句话说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，后面不能直接带“喉咙疼”作宾语。"}], "explanations": {"缓解": "“缓解”指让不好的感觉变轻，这里说热水能让喉咙疼变轻。", "加重": "语义：“喝点热水可以”是推荐的做法，“加重”喉咙疼与此矛盾。", "发烧": "语义：热水不能让人“发烧喉咙疼”，这句话说不通。", "咳嗽": "配价：“咳嗽”是不及物动词，后面不能直接带“喉咙疼”作宾语。"}, "sentence_index": 0, "correct_answer": "缓解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这次比赛中缓解了很多经验。", "explanation": "这里应该用〈积累〉。“缓解”指不好的感觉或情况变轻，经验的增多要用“积累”。"}, {"text": "这道难题我缓解了。", "explanation": "这里应该用〈解决〉。“缓解”只用于不好的感觉或情况变轻，题目要用“解决”。"}, {"text": "会议缓解了一个小时才开始。", "explanation": "这里应该用〈推迟〉。“缓解”指不好的感觉或情况变轻，时间的延后要用“推迟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓解", "is_correct": true, "explanation": "“缓解”指让不好的感觉变轻，这里说按肩膀能让疼痛变轻。"}, {"text": "制造", "is_correct": false, "explanation": "语义：按肩膀是保健动作，不会“制造”疼痛，与“可以”的语境矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "语义：作为推荐的做法，“可以增加疼痛”与语境矛盾。"}, {"text": "扩散", "is_correct": false, "explanation": "搭配：“扩散”是不及物动词，不能带“疼痛”作宾语。"}], "explanations": {"缓解": "“缓解”指让不好的感觉变轻，这里说按肩膀能让疼痛变轻。", "制造": "语义：按肩膀是保健动作，不会“制造”疼痛，与“可以”的语境矛盾。", "增加": "语义：作为推荐的做法，“可以增加疼痛”与语境矛盾。", "扩散": "搭配：“扩散”是不及物动词，不能带“疼痛”作宾语。"}, "sentence_index": 6, "correct_answer": "缓解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书我已经缓解完了。", "explanation": "这里应该用〈读完〉。“缓解”只用于感觉或情况变轻，读书要用“读完”。"}, {"text": "他的工资缓解了不少。", "explanation": "这里应该用〈增加〉。“缓解”指不好的情况变轻，工资增加要用“增加”。"}, {"text": "我们的队伍缓解了很多。", "explanation": "这里应该用〈壮大〉。“缓解”指不好的情况变轻，队伍扩大要用“壮大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法能缓解了疲劳。", "corrected_sentence": "这个方法能缓解疲劳。", "error_description": "“能”表示有这种作用，是一般性的说法；动词后的“了”表示已完成的变化，二者不合，应去掉“了”，改为“能缓解疲劳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院增加医生后，看病排队的情况缓解了过很多。", "corrected_sentence": "医院增加医生后，看病排队的情况缓解了很多。", "error_description": "“了”与“过”不能同时用在同一个动词后面；这里表示已经发生的变化，只用“了”，应为“缓解了很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
