INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里比旁边乡下更热的地方。", "primary_collocate": null, "pronunciation": "rè dǎo", "ipa": "ʐɤ⁵¹ tɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "市中心是一个热岛，晚上也很热。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上红色的地方就是热岛。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个热岛比郊区热五度。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在城市热岛的中心。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热岛里的老人夏天不爱出门。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园在热岛里，是最凉快的地方。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热岛旁边的乡下晚上很凉快。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的热岛越来越大了。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图上有三个热岛。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在热岛里找不到凉快的地方。", "target_word": "热岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热岛效应", "label": "复合"}, {"form": "城市热岛", "label": "复合"}], "register": "中性", "sense_fingerprint": "城里比乡下更热的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热岛", "is_correct": true, "explanation": "热岛：城里比乡下更热的地方，此处指市中心这样的地方。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度不是地方，“市中心是一个湿度”说不通。"}, {"text": "风速", "is_correct": false, "explanation": "语义：风速不是地方，不能作“市中心”的同位语。"}, {"text": "热量", "is_correct": false, "explanation": "搭配：“热量”是数量概念，与“一个”这类量词搭配不当，不能指地方。"}], "explanations": {"热岛": "热岛：城里比乡下更热的地方，此处指市中心这样的地方。", "湿度": "语义：湿度不是地方，“市中心是一个湿度”说不通。", "风速": "语义：风速不是地方，不能作“市中心”的同位语。", "热量": "搭配：“热量”是数量概念，与“一个”这类量词搭配不当，不能指地方。"}, "sentence_index": 0, "correct_answer": "热岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们坐船去热岛度假。", "explanation": "此处把“热岛”误解为岛屿。热岛指城里比乡下更热的地方，不是海中的岛。"}, {"text": "这里的热岛很高。", "explanation": "这里应该用〈温度〉。热岛是地方，不能用“高”描述；说气温高应用“温度”。"}, {"text": "我家附近有一只热岛。", "explanation": "量词错误。热岛指一片地区，应说“一片热岛”，“只”不能用于地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热岛", "is_correct": true, "explanation": "热岛：城里比乡下更热的地方，可以作“旁边”的处所。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是处所，“时间旁边的乡下”说不通。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影不是处所，不能作“旁边”的参照。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“旁边”要求处所名词，“友谊”不能与之搭配。"}], "explanations": {"热岛": "热岛：城里比乡下更热的地方，可以作“旁边”的处所。", "时间": "语义：时间不是处所，“时间旁边的乡下”说不通。", "电影": "语义：电影不是处所，不能作“旁边”的参照。", "友谊": "搭配：“旁边”要求处所名词，“友谊”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "热岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天我们常去热岛玩，那里很凉快。", "explanation": "这里应该用〈海边〉。热岛指城里比乡下更热的地方，不能是凉快的游玩处。"}, {"text": "他用热岛煮了一碗面。", "explanation": "这里应该用〈炉子〉。热岛指城里比乡下更热的地方，是一个区域，不是可以用来煮东西的器具。"}, {"text": "他把热岛拿回家当礼物。", "explanation": "热岛是城里的一个地区，不是可以拿回家的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城市里有很多热岛们，需要降温。", "corrected_sentence": "城市里有很多热岛，需要降温。", "error_description": "词缀错误：“们”只加在指人的名词后，“热岛”是地方名词，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上我们热岛里散步。", "corrected_sentence": "晚上我们在热岛里散步。", "error_description": "介词缺失：“热岛里”表示地点，前面需要“在”，应说“在热岛里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
