INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23556, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西里的一种叫碳的东西变少。", "primary_collocate": null, "pronunciation": "tuō tàn", "ipa": "tʰuɔ˧˥ tʰan˥˩", "syllable_count": 2, "sentences": [{"text": "炼钢时要给铁水脱碳，才能得到好钢。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "liàn gāng shí yào gěi tiě shuǐ tuō tàn cái néng dé dào hǎo gāng", "sentence_source": "generated"}, {"text": "工厂想用新机器给钢脱碳。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种炉子能让生铁更快脱碳。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "zhè zhǒng lú zi néng ràng shēng tiě gèng kuài tuō tàn", "sentence_source": "generated"}, {"text": "生铁经过脱碳，就变成了钢。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "shēng tiě jīng guò tuō tàn jiù biàn chéng le gāng", "sentence_source": "generated"}, {"text": "炼钢厂把铁水送进转炉里脱碳。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "liàn gāng chǎng bǎ tiě shuǐ sòng jìn zhuǎn lú lǐ tuō tàn", "sentence_source": "generated"}, {"text": "钢要先脱碳，才能变得更软。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批钢材的脱碳已经完成了一半。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "zhè pī gāng cái de tuō tàn yǐ jīng wán chéng le yí bàn", "sentence_source": "generated"}, {"text": "钢坯在加热炉里脱碳，表面会变软。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "gāng pī zài jiā rè lú lǐ tuō tàn biǎo miàn huì biàn ruǎn", "sentence_source": "generated"}, {"text": "工人用热气给铁水脱碳。", "target_word": "脱碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批钢坯脱碳以后，硬度明显降低。", "target_word": "脱碳", "complexity_tier": "T3", "furigana": "zhè pī gāng pī tuō tàn yǐ hòu yìng dù míng xiǎn jiàng dī", "sentence_source": "generated"}], "morphological_forms": [{"form": "脫碳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "脱碳·动词·让东西里的碳变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱碳", "is_correct": true, "explanation": "正确：指降低钢铁中碳含量的加工过程，与「给铁水」和「得到好钢」的语境相符。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：铁水不能被饮用，句子讲的是炼钢的加工处理。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：「喂养」要求有生命的对象（动物或幼儿），铁水不能作它的宾语。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：「浇灌」多用于植物和土地，不说「给铁水浇灌」。"}], "explanations": {"脱碳": "正确：指降低钢铁中碳含量的加工过程，与「给铁水」和「得到好钢」的语境相符。", "饮用": "语义：铁水不能被饮用，句子讲的是炼钢的加工处理。", "喂养": "配价：「喂养」要求有生命的对象（动物或幼儿），铁水不能作它的宾语。", "浇灌": "搭配：「浇灌」多用于植物和土地，不说「给铁水浇灌」。"}, "sentence_index": 0, "correct_answer": "脱碳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂把低碳钢放进炉里脱碳，表面就变硬了。", "explanation": "这里应该用〈渗碳〉。渗碳是往钢件表面加碳使其变硬，脱碳是减少钢中的碳，会让钢变软，二者方向相反。"}, {"text": "工人用热气脱碳铁水中的碳。", "explanation": "这里应该用〈去除〉。脱碳的宾语是被处理的对象（如「给铁水脱碳」），不能再接「中的碳」这种被去除的成分。"}, {"text": "这批湿木材要先脱碳，才能刷漆。", "explanation": "这里应该用〈脱水〉。脱碳是去除钢铁等物质中的碳，湿木材要去掉的是水分，应说〈脱水〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱碳", "is_correct": true, "explanation": "正确：此处是名词化用法，指钢材降低碳含量的加工过程，与「完成了一半」搭配。"}, {"text": "恋爱", "is_correct": false, "explanation": "语义：钢材不能「恋爱」，句子讲的是加工进度。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：钢材不会「旅行」，这里需要的是加工过程。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：「完成了一半」后面要接过程或任务，「硬度」不是可以被完成的事。"}], "explanations": {"脱碳": "正确：此处是名词化用法，指钢材降低碳含量的加工过程，与「完成了一半」搭配。", "恋爱": "语义：钢材不能「恋爱」，句子讲的是加工进度。", "旅行": "语义：钢材不会「旅行」，这里需要的是加工过程。", "硬度": "搭配：「完成了一半」后面要接过程或任务，「硬度」不是可以被完成的事。"}, "sentence_index": 6, "correct_answer": "脱碳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用砂纸给钢坯表面脱碳。", "explanation": "这里应该用〈打磨〉。脱碳要靠加热或气体反应去除钢铁中的碳，砂纸只能打磨表面。"}, {"text": "这批钢坯脱碳后，碳含量明显增加。", "explanation": "这里应该用〈渗碳〉。脱碳是减少钢中的碳，句中“碳含量明显增加”与之相反，应说〈渗碳〉。"}, {"text": "这件湿衣服要先脱碳，才能穿。", "explanation": "这里应该用〈晾干〉。脱碳是去除钢铁中的碳，湿衣服要去掉的是水分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在炉子里钢坯脱碳。", "corrected_sentence": "工人在炉子里给钢坯脱碳。", "error_description": "介词缺失：「脱碳」需要用「给」引出被处理的对象，应说「给钢坯脱碳」，不能省略「给」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批钢坯需要先脱碳了，才能进行后续加工。", "corrected_sentence": "这批钢坯需要先脱碳，才能进行后续加工。", "error_description": "「了」误用：「需要……才能」表示还未发生的动作，动词后不能加「了」，应说「需要先脱碳」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
