INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做出新的有用的东西。", "primary_collocate": null, "pronunciation": "jì shù chuàng xīn", "ipa": "tɕi˥˩ ʂu˥˩ ʈʂʰuɑŋ˥˩ ɕin˥", "syllable_count": 4, "sentences": [{"text": "这家公司很重视技术创新。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术创新让我们的生活更方便。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想发展经济，就要靠技术创新。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术创新需要很多时间和钱。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新手机是技术创新的结果。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校鼓励年轻人进行技术创新。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有技术创新，工厂就没有未来。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师一直从事技术创新。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术创新带来了很多新工作。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家每年都在技术创新上花很多钱。", "target_word": "技术创新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，指用新的技术做出新的有用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术创新", "is_correct": true, "explanation": "「重视」可以接“技术创新”这样的抽象对象，句意通顺。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：“蚊子”是昆虫，公司不会把它作为“重视”的对象，句子说不通。"}, {"text": "睡觉了", "is_correct": false, "explanation": "语法：「重视」后面要接名词性的对象，“重视睡觉了”不成句。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「重视」一般接“问题、质量、教育”等抽象事物，不能接“脚步”。"}], "explanations": {"技术创新": "「重视」可以接“技术创新”这样的抽象对象，句意通顺。", "蚊子": "语义：“蚊子”是昆虫，公司不会把它作为“重视”的对象，句子说不通。", "睡觉了": "语法：「重视」后面要接名词性的对象，“重视睡觉了”不成句。", "脚步": "搭配：「重视」一般接“问题、质量、教育”等抽象事物，不能接“脚步”。"}, "sentence_index": 0, "correct_answer": "技术创新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的技术创新。", "explanation": "这里应该用〈发明家〉。技术创新指做出新东西的活动或过程，不能用来指人。"}, {"text": "这是一颗重要的技术创新。", "explanation": "这里应该用〈项〉。「颗」用于小而圆的东西，技术创新是抽象的成果，应搭配量词〈项〉。"}, {"text": "他把技术创新搬到了楼上。", "explanation": "这里应该用〈设备〉。技术创新是抽象的活动，不能被搬运，搬运的应是〈设备〉这类具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术创新", "is_correct": true, "explanation": "「没有技术创新」作主语，与“工厂就没有未来”的因果关系相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”与工厂的未来没有因果关系，“没有童年，工厂就没有未来”说不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：“诗歌”不能决定工厂的发展前途，这里的因果推断不成立。"}, {"text": "老公", "is_correct": false, "explanation": "语义：“老公”与工厂的未来没有因果关系，“没有老公，工厂就没有未来”说不通。"}], "explanations": {"技术创新": "「没有技术创新」作主语，与“工厂就没有未来”的因果关系相符。", "童年": "语义：“童年”与工厂的未来没有因果关系，“没有童年，工厂就没有未来”说不通。", "诗歌": "语义：“诗歌”不能决定工厂的发展前途，这里的因果推断不成立。", "老公": "语义：“老公”与工厂的未来没有因果关系，“没有老公，工厂就没有未来”说不通。"}, "sentence_index": 6, "correct_answer": "技术创新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都吃技术创新。", "explanation": "这里应该用〈早餐〉。技术创新指做出新的有用东西的活动或成果，不是食物，不能用来吃。"}, {"text": "他一口气喝光了技术创新。", "explanation": "这里应该用〈汤〉。技术创新是抽象的成果，不能被喝，喝的应是〈汤〉这类液体食物。"}, {"text": "这次旅行是我最难忘的技术创新。", "explanation": "这里应该用〈体验〉。技术创新指科技领域的革新，不能用来指旅行的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们完成了一只技术创新。", "corrected_sentence": "他们完成了一项技术创新。", "error_description": "量词错误。「技术创新」是抽象名词，应搭配量词「项」；「只」用于动物或单个的具体物品，不能用于“技术创新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们行进了技术创新。", "corrected_sentence": "我们进行了技术创新。", "error_description": "动词颠倒。「进行」是与「技术创新」搭配的动词，不能说「行进」。「我们行进了技术创新」错误，应为「我们进行了技术创新」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
