INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23560, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让机器或车子动起来。", "primary_collocate": null, "pronunciation": "qū dòng", "ipa": "tɕʰy˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器由电动机驱动。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流驱动着大水车不停地转动。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆小车用电池驱动，不用汽油。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机驱动汽车向前跑。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风力驱动风车慢慢转了起来。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小电机驱动着风扇不停地转。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老船是用蒸汽驱动的。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小马达驱动整台机器运转。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玩具车靠弹簧驱动。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的发动机驱动了这辆大卡车。", "target_word": "驱动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驱动了", "label": "完成体"}, {"form": "驱动着", "label": "进行体"}, {"form": "驱动过", "label": "经历体"}, {"form": "驱动器", "label": "复合词"}, {"form": "驱动力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用动力使机器、车辆运转或前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱动", "is_correct": true, "explanation": "正确。驱动表示用动力使机器运转，与“由电动机”的语境相符。"}, {"text": "切", "is_correct": false, "explanation": "配价：“切”需要带切的对象，这里缺少宾语，句子不成立。"}, {"text": "涂", "is_correct": false, "explanation": "语义：“涂”是把颜料等抹在表面，电动机不能用来涂东西。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”是用鼻子感知气味，电动机不能去闻。"}], "explanations": {"驱动": "正确。驱动表示用动力使机器运转，与“由电动机”的语境相符。", "切": "配价：“切”需要带切的对象，这里缺少宾语，句子不成立。", "涂": "语义：“涂”是把颜料等抹在表面，电动机不能用来涂东西。", "闻": "语义：“闻”是用鼻子感知气味，电动机不能去闻。"}, "sentence_index": 0, "correct_answer": "驱动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民挥着鞭子，把牛群驱动回了家。", "explanation": "这里应该用〈驱赶〉。驱动指使机器或车辆运转，赶牛群回家要用“驱赶”。"}, {"text": "警察用水枪驱动了人群。", "explanation": "这里应该用〈驱散〉。驱动不用于人群，这里的意思是把人群赶散。"}, {"text": "他把小猫驱动走了。", "explanation": "这里应该用〈赶〉。驱动指使机器运转，不能用来说赶走小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱动", "is_correct": true, "explanation": "正确。“用蒸汽”后接动词，驱动表示用蒸汽的动力使船运转。"}, {"text": "写", "is_correct": false, "explanation": "语义：“用蒸汽写的”事理不通，蒸汽不能写字。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“用蒸汽唱的”事理不通，蒸汽不能唱歌。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”需要带穿的对象，这里缺少宾语，句子不成立。"}], "explanations": {"驱动": "正确。“用蒸汽”后接动词，驱动表示用蒸汽的动力使船运转。", "写": "语义：“用蒸汽写的”事理不通，蒸汽不能写字。", "唱": "语义：“用蒸汽唱的”事理不通，蒸汽不能唱歌。", "穿": "配价：“穿”需要带穿的对象，这里缺少宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "驱动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她驱动了手臂。", "explanation": "这里应该用〈挥动〉。驱动只用于让机器、车辆运转，不能说“驱动手臂”。"}, {"text": "他驱动手中的铃。", "explanation": "这里应该用〈摇动〉。驱动指使机器运转，摇铃要用“摇动”。"}, {"text": "她驱动了窗户。", "explanation": "这里应该用〈打开〉。驱动不能用来说开窗，开窗要用“打开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器靠大电池驱动起去。", "corrected_sentence": "这台机器靠大电池驱动起来。", "error_description": "趋向补语错误：“起来”表示动作开始并向上发展，应说“驱动起来”，不能说“驱动起去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台老机器把煤气驱动。", "corrected_sentence": "这台老机器靠煤气驱动。", "error_description": "介词误用：表示凭借要用“靠”，“把”字句不能引出“煤气”这样的动力来源。应说“靠煤气驱动”，不能说“把煤气驱动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
