INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "让空气、水和土地变得干净。", "primary_collocate": null, "pronunciation": "huán jìng zhì lǐ", "ipa": "xwan³⁵ tɕiŋ⁵¹ ʈʂʅ⁵¹ li²¹⁴", "syllable_count": 4, "sentences": [{"text": "这座城市正在加强环境治理。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境治理让河水重新变清了。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用三年时间完成了环境治理。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂附近的环境治理很难。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境治理后，空气好多了。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里请专家来做环境治理。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府开展环境治理，保护土地和水。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的环境治理已经开始了。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出钱参加环境治理。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民都支持环境治理。", "target_word": "环境治理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球环境治理", "label": "复合"}, {"form": "环境治理工作", "label": "复合"}], "register": "书面", "sense_fingerprint": "使空气水土地变干净的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境治理", "is_correct": true, "explanation": "“加强”可以接“治理”这类抽象工作，“环境治理”指治理行动，与“正在加强”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被“加强”，句子说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“加强”一般不跟“工资”搭配，应说“提高工资”。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是可以被“加强”的工作或措施。"}], "explanations": {"环境治理": "“加强”可以接“治理”这类抽象工作，“环境治理”指治理行动，与“正在加强”搭配自然。", "天气": "语义：天气是自然现象，不能被“加强”，句子说不通。", "工资": "搭配：“加强”一般不跟“工资”搭配，应说“提高工资”。", "早餐": "语义：早餐是一顿饭，不是可以被“加强”的工作或措施。"}, "sentence_index": 0, "correct_answer": "环境治理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班级纪律的环境治理很有成效。", "explanation": "这里误把〈环境治理〉用于班级纪律，应该用〈整顿〉。“环境治理”针对空气、水和土地，不能用于纪律等社会管理对象。"}, {"text": "那位环境治理很努力地工作。", "explanation": "这里应该用〈治理者〉。“环境治理”指治理行动，不指做事的人。"}, {"text": "这条河的环境治理吃掉了三碗饭。", "explanation": "这里误把〈环境治理〉当成了能吃饭的主体。“吃”只能接食物，而“环境治理”指对空气、水和土地的治理行动，不能作吃的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境治理", "is_correct": true, "explanation": "“开展”可以接“环境治理”这类工作，与后文“保护土地和水”的目的相呼应。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿的物品，不能被“开展”，句子不通。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“开展”不跟“玩笑”搭配，应说“开玩笑”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不是可以被“开展”的工作，也与“保护土地和水”的语境不符。"}], "explanations": {"环境治理": "“开展”可以接“环境治理”这类工作，与后文“保护土地和水”的目的相呼应。", "鞋子": "语义：鞋子是穿的物品，不能被“开展”，句子不通。", "玩笑": "搭配：“开展”不跟“玩笑”搭配，应说“开玩笑”。", "饭菜": "语义：饭菜不是可以被“开展”的工作，也与“保护土地和水”的语境不符。"}, "sentence_index": 6, "correct_answer": "环境治理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个病人的环境治理很顺利。", "explanation": "这里应该用〈治疗〉。“环境治理”针对空气、水和土地，不能用于人的病情。"}, {"text": "妈妈把环境治理炒了一下。", "explanation": "这里误把〈环境治理〉当成了可以烹调的食材。“炒”只能用于食物，而“环境治理”指对空气、水和土地的治理工作，不能被炒。"}, {"text": "我们约在环境治理见面吧。", "explanation": "“约在……见面”要求地点名词，如“公园”。“环境治理”是行动，不能作见面的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们完成了一座环境治理工程。", "corrected_sentence": "我们完成了一项环境治理工程。", "error_description": "错误：“一座环境治理工程”，正确：“一项环境治理工程”。治理工程是一项工作，量词用“项”；“座”多用于山、桥、楼等建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在环境治理。", "corrected_sentence": "工人们正在进行环境治理。", "error_description": "“环境治理”作为动作名词，前面一般要加“进行”或“开展”，应说“正在进行环境治理”，不能直接说“正在环境治理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
