INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "部门是一个大团体里的小组，比如公司里的一个小组。", "primary_collocate": null, "pronunciation": "bù mén", "ipa": "pu˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "我们部门每周一早上开会。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新成立了一个设计部门。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从客服部门调到了市场部门。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门的工作很忙，常常加班。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友在公司的技术部门上班。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我们部门准备一份报告。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们部门有一位新同事，姓王。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部门的人坐在同一间办公室里。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司研发部门的小组长。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张表交给人事部门。", "target_word": "部门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "部門", "label": "繁体"}, {"form": "部门经理", "label": "复合"}], "register": "中性", "sense_fingerprint": "大团体里的小组，如公司里的一个小组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '869a6818-447d-4435-b360-0323be8c2be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部门", "is_correct": true, "explanation": "正确：“我们部门”指所在的小组，能开会，符合语境。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会开会，“我们河流”与句意不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能作为开会的团体。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是团体，不会开会。"}], "explanations": {"部门": "正确：“我们部门”指所在的小组，能开会，符合语境。", "河流": "语义：河流不会开会，“我们河流”与句意不符。", "花园": "语义：花园是场所，不能作为开会的团体。", "石头": "语义：石头不是团体，不会开会。"}, "sentence_index": 0, "correct_answer": "部门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的这个部门很有意思。", "explanation": "这里应该用〈部分〉。书的某一段要用“部分”，部门指机构中的小组，不能指书的一部分。"}, {"text": "这台机器的这个部门坏了。", "explanation": "这里应该用〈部件〉。机器的零件坏了要说“部件”，部门指人员小组，不能指零件。"}, {"text": "我们公司新设了一位部门。", "explanation": "这里应该用〈个〉。部门要用“个”计量，“位”用于人，不能用来计量部门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部门", "is_correct": true, "explanation": "正确：“我们部门”指所在的小组，可以有新同事，符合语境。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会有同事，“有一位新同事”需要人群作主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能拥有同事，与句意不符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“有……同事”要求团体作主语，“楼梯”是场所，不搭配。"}], "explanations": {"部门": "正确：“我们部门”指所在的小组，可以有新同事，符合语境。", "闹钟": "语义：闹钟不会有同事，“有一位新同事”需要人群作主语。", "窗户": "语义：窗户不能拥有同事，与句意不符。", "楼梯": "搭配：“有……同事”要求团体作主语，“楼梯”是场所，不搭配。"}, "sentence_index": 6, "correct_answer": "部门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "心脏是人体的重要部门，要好好保护。", "explanation": "这里应该用〈部位〉。身体的某一处要用“部位”，部门指人员的小组，不能指身体的器官。"}, {"text": "这次搬家的部门很周密。", "explanation": "这里应该用〈部署〉。搬家的安排要用“部署”，部门指小组，不能指安排。"}, {"text": "公司新添了一把部门。", "explanation": "这里应该用〈个〉。部门要用“个”计量，“把”用于有柄的器具，不能用来计量部门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司里有一座技术部门。", "corrected_sentence": "公司里有一个技术部门。", "error_description": "量词错误：“技术部门”应用“个”计量，“座”用于房屋、山等大型物体，不能用来计量部门。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友在这台部门工作。", "corrected_sentence": "我的朋友在这个部门工作。", "error_description": "量词错误：“部门”应用“个”计量，“台”用于机器等设备，不能用来计量部门。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0916f1a2-4269-47b8-aa72-5fc4a9a9257b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
