INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坐车的人。", "primary_collocate": null, "pronunciation": "chéng kè", "ipa": "ʈʂʰɤŋ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "车上的乘客一个接一个下去了。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公交车一次能坐五十名乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客买票以后才能进站。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机帮老年乘客拿行李。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的乘客都在看海。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场广播请乘客去三号门登机。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这趟高铁上的第一位乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客太多，车门关不上。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客向司机说了声谢谢。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的末班车只有两位乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位乘客", "label": "量词"}, {"form": "一名乘客", "label": "量词"}], "register": "中性", "sense_fingerprint": "坐车的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：坐车的人，这里指车上下车的人。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机不会一个接一个从车上下去，与句子不合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星挂在天上，不会从车上一个接一个下去。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己下车，与“下去”的意思不合。"}], "explanations": {"乘客": "正确：坐车的人，这里指车上下车的人。", "飞机": "语义：飞机不会一个接一个从车上下去，与句子不合。", "星星": "语义：星星挂在天上，不会从车上一个接一个下去。", "石头": "语义：石头不会自己下车，与“下去”的意思不合。"}, "sentence_index": 0, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧场里的乘客很多，大家都在等演出开始。", "explanation": "这里应该用〈观众〉。乘客指乘车的人，看演出的人应说〈观众〉。"}, {"text": "教室里的乘客都在认真听讲。", "explanation": "这里应该用〈学生〉。乘客指乘车的人，上课听讲的人应说〈学生〉。"}, {"text": "我们家来了一位乘客，陪我们聊天。", "explanation": "这里应该用〈客人〉。乘客指乘坐交通工具的人，来家里做客的人应说〈客人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：坐车的人，这里指第一个上这趟车的人。"}, {"text": "幽灵", "is_correct": false, "explanation": "语义：幽灵不是坐车的人，“第一位幽灵”的说法与句意不合。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是东西，不是人，不能用“位”来数，也不能是“第一位”。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是纸片，不是人，不能用“位”来数。"}], "explanations": {"乘客": "正确：坐车的人，这里指第一个上这趟车的人。", "幽灵": "语义：幽灵不是坐车的人，“第一位幽灵”的说法与句意不合。", "椅子": "语义：椅子是东西，不是人，不能用“位”来数，也不能是“第一位”。", "车票": "语义：车票是纸片，不是人，不能用“位”来数。"}, "sentence_index": 6, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古城每天有很多乘客。", "explanation": "这里应该用〈游客〉。乘客指乘坐交通工具的人，来景点观光的人应说〈游客〉。"}, {"text": "医院里的乘客排着队等候看病。", "explanation": "这里应该用〈病人〉。乘客指乘车的人，等候看病的人应说〈病人〉。"}, {"text": "社区里来了一位乘客，找我们商量事情。", "explanation": "这里应该用〈访客〉。乘客指乘车的人，到社区来找人的应说〈访客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车上有三只乘客。", "corrected_sentence": "车上有三名乘客。", "error_description": "“乘客”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。应说“三名乘客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机让一位乘客们先上车。", "corrected_sentence": "司机让一位乘客先上车。", "error_description": "“们”表示复数，不能与数量词“一位”连用；有了数量词，“乘客”就已经计量清楚。应说“一位乘客”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旁观", "is_correct": true, "explanation": "反义：“旁观”指站在一旁看，不加入其中，与“参与”相对。"}, {"text": "制造", "is_correct": false, "explanation": "无关：“制造”指做出东西，与“参与”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指深入探究，与“参与”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指买下东西，与“参与”没有反义关系。"}], "correct_answer": "旁观", "explanations": {"旁观": "反义：“旁观”指站在一旁看，不加入其中，与“参与”相对。", "制造": "无关：“制造”指做出东西，与“参与”没有反义关系。", "研究": "无关：“研究”指深入探究，与“参与”没有反义关系。", "购买": "无关：“购买”指买下东西，与“参与”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旁观", "is_correct": true, "explanation": "反义：“旁观”指站在一旁看，不加入其中，与“参与”相对。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清除污物，与“参与”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指把东西从一处移到另一处，与“参与”没有反义关系。"}, {"text": "推销", "is_correct": false, "explanation": "无关：“推销”指把商品卖给别人，与“参与”没有反义关系。"}], "correct_answer": "旁观", "explanations": {"旁观": "反义：“旁观”指站在一旁看，不加入其中，与“参与”相对。", "打扫": "无关：“打扫”指清除污物，与“参与”没有反义关系。", "搬运": "无关：“搬运”指把东西从一处移到另一处，与“参与”没有反义关系。", "推销": "无关：“推销”指把商品卖给别人，与“参与”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情和大家一起。", "primary_collocate": null, "pronunciation": "cān yù", "ipa": "tsʰan˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "我想参与这次活动。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学都参与了讨论。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有参与过比赛。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励大家积极参与。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意参与我们的计划吗？", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都参与了这次打扫。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈也想参与学校的活动。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我没有参与。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎大家参与我们的游戏。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在参与一个新项目。", "target_word": "参与", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参与了", "label": "体标"}, {"form": "参与过", "label": "体标"}, {"form": "参与者", "label": "复合"}, {"form": "參與", "label": "繁体"}], "register": "中性", "sense_fingerprint": "加入活动、讨论、工作等，和大家一起做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "参与", "is_correct": true, "explanation": "正确答案。“参与”读 cān yù，指加入活动或事务，和大家一起做。"}, {"text": "残余", "is_correct": false, "explanation": "声调不同：yú（第二声）与 yù（第四声），“残余”指剩下的部分。"}, {"text": "参议", "is_correct": false, "explanation": "韵母不同：yì 与 yù，“参议”指参与商议、参议员。"}, {"text": "参阅", "is_correct": false, "explanation": "声调相同（均为第四声），韵母不同：yuè 的韵母是 üe，比 yù 的 ü 多一个 e，“参阅”指查看参考资料。"}], "explanations": {"参与": "正确答案。“参与”读 cān yù，指加入活动或事务，和大家一起做。", "残余": "声调不同：yú（第二声）与 yù（第四声），“残余”指剩下的部分。", "参议": "韵母不同：yì 与 yù，“参议”指参与商议、参议员。", "参阅": "声调相同（均为第四声），韵母不同：yuè 的韵母是 üe，比 yù 的 ü 多一个 e，“参阅”指查看参考资料。"}, "sentence_index": null, "correct_answer": "参与"}, "level_3": {"options": [{"text": "参与", "is_correct": true, "explanation": "正确：“参与”指加入这次活动，与“我想……这次活动”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：活动不能被吃，“吃”的对象应是食物。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是具体的东西，活动不能被咬。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”一般用于食物，与“活动”搭配不当。"}], "explanations": {"参与": "正确：“参与”指加入这次活动，与“我想……这次活动”相符。", "吃": "语义：活动不能被吃，“吃”的对象应是食物。", "咬": "语义：“咬”的对象是具体的东西，活动不能被咬。", "嚼": "搭配：“嚼”一般用于食物，与“活动”搭配不当。"}, "sentence_index": 0, "correct_answer": "参与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参与了一块饼干，很快就吃完了。", "explanation": "这里应该用〈吃〉。“参与”指加入活动或事务，不能用于食物。"}, {"text": "周末我们去科技馆参与恐龙化石。", "explanation": "这里应该用〈参观〉。参观指去看看某地或展品，“参与”需要一项活动作宾语，不能用于展品。"}, {"text": "科学家在实验室里参与细菌。", "explanation": "这里应该用〈观察〉。观察是仔细看，“参与”指加入某项事务，不能用于细菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参与", "is_correct": true, "explanation": "正确：“参与”指加入学校的活动，与“爸爸妈妈也想……”相符。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”针对破损的东西，活动不能被修补。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指整个咽下，活动不能被吞。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”多用于建筑、设施，与“活动”搭配不当。"}], "explanations": {"参与": "正确：“参与”指加入学校的活动，与“爸爸妈妈也想……”相符。", "修补": "语义：“修补”针对破损的东西，活动不能被修补。", "吞": "语义：“吞”指整个咽下，活动不能被吞。", "拆除": "搭配：“拆除”多用于建筑、设施，与“活动”搭配不当。"}, "sentence_index": 6, "correct_answer": "参与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在家里参与了昨晚的足球比赛。", "explanation": "这里应该用〈观看〉。“参与”指亲自加入做事，在家看比赛要用“观看”。"}, {"text": "大家都围在台下参与那场精彩的表演。", "explanation": "这里应该用〈欣赏〉。台下的人是观看表演，“参与”指亲自加入表演或活动，要用“欣赏”。"}, {"text": "他在鞋店里参与了一双鞋。", "explanation": "这里应该用〈购买〉。“参与”指加入活动或事务，买东西要用“购买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前参与着很多志愿活动。", "corrected_sentence": "我以前参与过很多志愿活动。", "error_description": "“着”表示持续的状态，与“以前”的经历相矛盾；表示曾经有过的经历应用“过”，应说“参与过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这个项目的参与。", "corrected_sentence": "他是这个项目的参与者。", "error_description": "“参与”是动词，指人时要加后缀“者”，应说“参与者”，单独的“参与”不能指人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
