INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走向某个地方或目标。", "primary_collocate": null, "pronunciation": "mài xiàng", "ipa": "maɪ̯˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家正在迈向新的未来。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国经济稳步迈向高质量发展。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，他迈向了新的生活。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一步一步迈向终点。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有坚持努力，我们才能迈向成功。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城正迈向现代化。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多年努力，球队终于迈向了世界赛场。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人勇敢地迈向自己的梦想。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走出校门，迈向了社会。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会正迈向更加开放的时代。", "target_word": "迈向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迈向了", "label": "完成体"}, {"form": "正在迈向", "label": "进行体"}], "register": "书面", "sense_fingerprint": "迈步走向目标、未来或新阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迈向", "is_correct": true, "explanation": "正确。“正在迈向”后接抽象目标，表示朝新的未来前进。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，不能说喝“新的未来”。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象是可以悬挂的物品，不能挂“未来”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等具体物体，不能擦“未来”。"}], "explanations": {"迈向": "正确。“正在迈向”后接抽象目标，表示朝新的未来前进。", "喝": "语义：“喝”的对象是饮料，不能说喝“新的未来”。", "挂": "搭配：“挂”的对象是可以悬挂的物品，不能挂“未来”。", "擦": "搭配：“擦”的对象是桌面、玻璃等具体物体，不能擦“未来”。"}, "sentence_index": 0, "correct_answer": "迈向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车迈向了城市的中心。", "explanation": "这里应该用〈驶向〉。迈向指人或群体有意识地朝目标前进，车辆应说“驶向”。"}, {"text": "这条河迈向了大海。", "explanation": "这里应该用〈流向〉。河水是流动的，不能像人一样迈步，应说“流向大海”。"}, {"text": "这条小路迈向了山顶。", "explanation": "这里应该用〈通向〉。迈向指人有意识地朝目标前进，小路不能迈步，应说“通向山顶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迈向", "is_correct": true, "explanation": "正确。“终于迈向了世界赛场”表示球队朝更高的目标前进。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是食物或具体物体，不能咬“世界赛场”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是清洁表面，与球队多年努力的语境不合，不能说擦“世界赛场”。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”的对象是火、灯，不能说熄灭“世界赛场”。"}], "explanations": {"迈向": "正确。“终于迈向了世界赛场”表示球队朝更高的目标前进。", "咬": "语义：“咬”的对象是食物或具体物体，不能咬“世界赛场”。", "擦": "语义：“擦”是清洁表面，与球队多年努力的语境不合，不能说擦“世界赛场”。", "熄灭": "搭配：“熄灭”的对象是火、灯，不能说熄灭“世界赛场”。"}, "sentence_index": 6, "correct_answer": "迈向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔钱迈向了我的口袋。", "explanation": "这里应该用〈流进〉。迈向指人有意识地朝目标前进，钱不能自己迈步，应说“流进口袋”。"}, {"text": "这块石头迈向了水池。", "explanation": "这里应该用〈落进〉。迈向指人有意识地朝目标前进，石头不能自己迈步，应说“落进水池”。"}, {"text": "这片树叶迈向了溪水。", "explanation": "这里应该用〈飘向〉。迈向指人有意识地朝目标前进，树叶不能自己迈步，应说“飘向溪水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正迈向了新的时代。", "corrected_sentence": "我们正迈向新的时代。", "error_description": "体标冲突：“正”表示动作进行，与完成体“了”不能同用。应说“正迈向新的时代”，不能说“正迈向了新的时代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻人正把一步步迈向成功。", "corrected_sentence": "年轻人正一步步迈向成功。", "error_description": "把字句误用：“迈向”不能用“把”字句，“一步步”也不能作“把”的宾语。应说“年轻人正一步步迈向成功”，不能说“年轻人正把一步步迈向成功”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
