INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "预算就是提前想好要花多少钱。", "primary_collocate": null, "pronunciation": "yù suàn", "ipa": "y˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "我给这个月的生活费做了预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的生日礼物，我的预算是一百元。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买手机的预算只有两千块。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有预算，我就会乱花钱。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去北京玩，预算够不够？", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，买新车要先定好预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的菜很贵，超出了我的预算。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末聚餐的预算，每人五十元。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的预算不多，只能买便宜的鞋。", "target_word": "预算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你家装修的预算是多少？", "target_word": "预算", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔预算", "label": "量词"}, {"form": "预算表", "label": "复合"}, {"form": "預算", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人购物、旅行、生活时事先想好的花钱数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预算", "is_correct": true, "explanation": "“做了预算”指事先定好花钱的数目，与“生活费”搭配自然。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“做”说的是制作或安排，不能用于“天空”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，与生活费的安排无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述人的体型，不能被“做”，句子不通。"}], "explanations": {"预算": "“做了预算”指事先定好花钱的数目，与“生活费”搭配自然。", "天空": "搭配：“做”说的是制作或安排，不能用于“天空”。", "河流": "语义：河流是自然景物，与生活费的安排无关。", "身高": "体貌：身高描述人的体型，不能被“做”，句子不通。"}, "sentence_index": 0, "correct_answer": "预算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从银行取出了预算。", "explanation": "这里应该用〈存款〉。预算是计划，不能从银行取出；取出的是存款。"}, {"text": "明天的天气预算是晴天。", "explanation": "这里应该用〈预报〉。预算是事先想好要花多少钱，不能用来说天气。"}, {"text": "他从冰箱里预算出了一瓶牛奶。", "explanation": "这里应该用〈拿〉。预算是估计花费，不能用来拿东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预算", "is_correct": true, "explanation": "“超出了我的预算”指花费超过事先定好的钱数，符合语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，和花钱没有关系。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不能“超出”一个人的花钱打算。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“超出”后面不能接人的名字。"}], "explanations": {"预算": "“超出了我的预算”指花费超过事先定好的钱数，符合语境。", "体温": "语义：体温指身体的温度，和花钱没有关系。", "花园": "语义：花园是一个地方，不能“超出”一个人的花钱打算。", "名字": "搭配：“超出”后面不能接人的名字。"}, "sentence_index": 6, "correct_answer": "预算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经交了房租预算。", "explanation": "这里应该用〈费用〉。“交”的是钱，预算是计划，不能交。"}, {"text": "我已经结清了这笔预算。", "explanation": "这里应该用〈开支〉。预算是计划，不能“结清”；结清的是开支。"}, {"text": "他对这次考试的预算很高。", "explanation": "这里应该用〈预期〉。预算是事先想好要花多少钱，不能用来形容对考试结果的期待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先给这个月的花销定一条预算。", "corrected_sentence": "我先给这个月的花销定一笔预算。", "error_description": "量词错误：“预算”应搭配量词“笔”，说“一笔预算”。“条”用于细长的东西，如河流、裤子，不能用来数预算。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给家里吃了一份预算。", "corrected_sentence": "我给家里做了一份预算。", "error_description": "动词误用：“吃”只能搭配食物，不能用来说预算；应说“做了一份预算”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
