INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来打开锁或保护秘密的一串数字、字母或符号。", "primary_collocate": null, "pronunciation": "mì mǎ", "ipa": "mi˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个行李箱的密码是三个数字。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不住保险箱的密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁的密码只有家人知道。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输入密码，打开了小柜子。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把箱子的密码改成你的生日吧。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给手机设了一个新密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密码太长了，我用本子记下来。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的日记本有密码，我打不开。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板只把保险柜的密码告诉了我。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开门前要先输入密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "密码箱", "label": "复合"}, {"form": "密碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打开锁或保护秘密的一串数字字母符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4275a2c9-4bff-40c5-ac87-bdb8abddd072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：行李箱的密码是一串数字，「密码」与「是三个数字」搭配自然。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是金属器具，不能由数字组成，句子意思说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「是三个数字」描述的是可数的符号，颜色不能用数字来描述。"}, {"text": "轮子", "is_correct": false, "explanation": "语义：轮子是箱子的部件，不能是「三个数字」，句意不通。"}], "explanations": {"密码": "正确：行李箱的密码是一串数字，「密码」与「是三个数字」搭配自然。", "钥匙": "语义：钥匙是金属器具，不能由数字组成，句子意思说不通。", "颜色": "搭配：「是三个数字」描述的是可数的符号，颜色不能用数字来描述。", "轮子": "语义：轮子是箱子的部件，不能是「三个数字」，句意不通。"}, "sentence_index": 0, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把密码煮熟了，给我们当早饭。", "explanation": "这里应该用〈饺子〉。〈煮熟〉的对象是食物，密码是一串数字或字母，不能煮。"}, {"text": "出门前要先吃掉密码。", "explanation": "这里应该用〈输入〉。〈吃掉〉的宾语必须是食物，密码不能吃，应说〈输入〉。"}, {"text": "这个密码很圆。", "explanation": "密码没有形状，〈圆〉只用于具体物体的形状，描述密码应说〈长〉或〈复杂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：「太长了」描述的是密码的长度，用本子记下来也说明它是一串需要抄写的字符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能用「太长」来形容，也不需要用本子记下来。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：「太长了」用于可以计量长度的事物，阳光不能用长短来形容。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有长短，也不需要用本子记下来，句意不通。"}], "explanations": {"密码": "正确：「太长了」描述的是密码的长度，用本子记下来也说明它是一串需要抄写的字符。", "咖啡": "语义：咖啡是饮料，不能用「太长」来形容，也不需要用本子记下来。", "阳光": "搭配：「太长了」用于可以计量长度的事物，阳光不能用长短来形容。", "天空": "语义：天空没有长短，也不需要用本子记下来，句意不通。"}, "sentence_index": 6, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用密码敲门，敲了三次。", "explanation": "密码不是敲门的工具，〈敲〉要用手或门环。"}, {"text": "开门前要先把密码插进去。", "explanation": "这里应该用〈输入〉。〈插进去〉用于钥匙等有形物，密码不能插入。"}, {"text": "他每天早上喝一口密码。", "explanation": "这里应该用〈牛奶〉。〈喝〉的宾语必须是可以饮用的东西，密码不能喝，应换成〈牛奶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了两把保险箱的密码。", "corrected_sentence": "我找到了两组保险箱的密码。", "error_description": "量词错误：「把」用于有柄的器具，密码应说「组」或「个」。正确句为「我找到了两组保险箱的密码。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把保险柜了密码改成了生日。", "corrected_sentence": "他把保险柜的密码改成了生日。", "error_description": "助词错误：修饰名词「密码」应用结构助词「的」，不能用「了」。正确句为「他把保险柜的密码改成了生日。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '960307d4-24f9-4acb-a09d-8179ea218fd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
