INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人和电脑连在一起，可以看东西、聊天。", "primary_collocate": null, "pronunciation": "hù lián wǎng", "ipa": "xu˥˩ ljɛn˧˥ waŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "现在我们在互联网上买东西很方便。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网让世界变得越来越小。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不会用互联网。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网上有很多有用的信息。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子刚刚通了互联网。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不应该一直在互联网上玩游戏。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了互联网，我们可以和国外的朋友聊天。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网的速度今天特别慢。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在互联网上查资料。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是在互联网上认识这个朋友的。", "target_word": "互联网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移动互联网", "label": "复合词"}, {"form": "互联网公司", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把全世界的电脑连起来的网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸", "is_correct": false, "explanation": "语义：纸不能用来买东西，“在纸上买东西”说不通。"}, {"text": "互联网", "is_correct": true, "explanation": "人们可以在互联网上买东西，“现在我们在互联网上买东西很方便”符合语境。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：典籍是古代书籍，书面古雅，与口语化的“现在我们……”不协调。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的写字板，不能用来买东西。"}], "explanations": {"纸": "语义：纸不能用来买东西，“在纸上买东西”说不通。", "互联网": "人们可以在互联网上买东西，“现在我们在互联网上买东西很方便”符合语境。", "典籍": "语域：典籍是古代书籍，书面古雅，与口语化的“现在我们……”不协调。", "黑板": "语义：黑板是教室里的写字板，不能用来买东西。"}, "sentence_index": 0, "correct_answer": "互联网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台互联网。", "explanation": "这里把互联网当成了〈设备〉来计量。互联网是抽象的网络，不是机器或电器。"}, {"text": "学校安装了一辆互联网。", "explanation": "这里把互联网当成了〈车辆〉来计量。互联网是网络，不是车，不能这样计量。"}, {"text": "图书馆里有一座互联网。", "explanation": "这里把互联网当成了〈建筑〉来计量。互联网是抽象的网络，不是山或楼这样的大型固定物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车", "is_correct": false, "explanation": "语义：火车不能用来和朋友聊天，“有了火车”说不通。"}, {"text": "互联网", "is_correct": true, "explanation": "互联网可以用来和国外的朋友聊天，“有了互联网”符合语境。"}, {"text": "竹简", "is_correct": false, "explanation": "语域：竹简是古代的书写材料，与现代聊天的语境不协调。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来聊天，与“聊天”搭配不通。"}], "explanations": {"火车": "语义：火车不能用来和朋友聊天，“有了火车”说不通。", "互联网": "互联网可以用来和国外的朋友聊天，“有了互联网”符合语境。", "竹简": "语域：竹简是古代的书写材料，与现代聊天的语境不协调。", "石头": "语义：石头不能用来聊天，与“聊天”搭配不通。"}, "sentence_index": 6, "correct_answer": "互联网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做的菜里有互联网。", "explanation": "这里把互联网当成了〈食材〉。互联网是抽象的网络，不能当作食材放进菜里。"}, {"text": "他把互联网装进了书包。", "explanation": "这里把互联网当成了〈路由器〉这类可以装进包里的实物。互联网是抽象的网络，不是实物，不能装进书包。"}, {"text": "我每天坐互联网去上班。", "explanation": "这里把互联网当成了〈地铁〉这类交通工具。互联网是网络，不能乘坐，不能说“坐互联网”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家刚开通了一台互联网。", "corrected_sentence": "我家刚开通了互联网。", "error_description": "量词错误：互联网是抽象的网络，前面不能加“台”，应说“开通了互联网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天就用了上互联网。", "corrected_sentence": "他昨天就用上了互联网。", "error_description": "“了”位置错误：动补结构“用上”之后才加“了”，应说“用上了互联网”，不能说“用了上互联网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏私", "is_correct": true, "explanation": "正确：指不公正、偏袒某一方，与“公正”构成反义。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“公正”没有反义关系，指动作或反应慢。"}, {"text": "沉重", "is_correct": false, "explanation": "与“公正”没有反义关系，指分量大或心情压抑。"}, {"text": "温暖", "is_correct": false, "explanation": "与“公正”没有反义关系，指有温度或让人感到亲切。"}], "correct_answer": "偏私", "explanations": {"偏私": "正确：指不公正、偏袒某一方，与“公正”构成反义。", "迟缓": "与“公正”没有反义关系，指动作或反应慢。", "沉重": "与“公正”没有反义关系，指分量大或心情压抑。", "温暖": "与“公正”没有反义关系，指有温度或让人感到亲切。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏私", "is_correct": true, "explanation": "正确：指不公正、偏袒某一方，与“公正”构成反义。"}, {"text": "柔和", "is_correct": false, "explanation": "与“公正”没有反义关系，指性质温和、不刺激。"}, {"text": "热闹", "is_correct": false, "explanation": "与“公正”没有反义关系，指人多、声音大、气氛活跃。"}, {"text": "繁忙", "is_correct": false, "explanation": "与“公正”没有反义关系，指事情多、忙碌。"}], "correct_answer": "偏私", "explanations": {"偏私": "正确：指不公正、偏袒某一方，与“公正”构成反义。", "柔和": "与“公正”没有反义关系，指性质温和、不刺激。", "热闹": "与“公正”没有反义关系，指人多、声音大、气氛活跃。", "繁忙": "与“公正”没有反义关系，指事情多、忙碌。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对每个人都一样，不偏向谁。", "primary_collocate": null, "pronunciation": "gōng zhèng", "ipa": "kʊŋ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈分苹果很公正，每人一个。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判公正，两队都服气。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个公正的人，不会帮自己的朋友。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对新人和老人一样公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你公正地说说，谁做得对？", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的规则很公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长公正地给大家排座位。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一个公正的人来判断。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是照顾自己的弟弟，谈不上公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这位老师最公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不公正", "label": "复合"}, {"form": "公正性", "label": "复合"}], "register": "书面", "sense_fingerprint": "对每个人都一样，不偏向任何一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83fd6bf9-3bac-4e2e-a8b7-ad5e5b0c673f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：对每个人都一样，不偏向谁。"}, {"text": "工整", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。"}, {"text": "更正", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。"}, {"text": "公众", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母不同（-ong 与 -eng），意思是社会上大多数人。"}], "explanations": {"公正": "正确：对每个人都一样，不偏向谁。", "工整": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。", "更正": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。", "公众": "zhòng 与 zhèng 韵母不同（-ong 与 -eng），意思是社会上大多数人。"}, "sentence_index": null, "correct_answer": "公正"}, "level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：对每个人一视同仁，与“每人一个”的平均分配相符。"}, {"text": "偏心", "is_correct": false, "explanation": "语义：“偏心”指偏向一方，与“每人一个”的平均分配矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形，不能用来描述分苹果的做法。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来修饰“分苹果”。"}], "explanations": {"公正": "正确：对每个人一视同仁，与“每人一个”的平均分配相符。", "偏心": "语义：“偏心”指偏向一方，与“每人一个”的平均分配矛盾。", "高大": "体貌：“高大”形容体形，不能用来描述分苹果的做法。", "响亮": "搭配：“响亮”形容声音，不能用来修饰“分苹果”。"}, "sentence_index": 0, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题解释得很公正。", "explanation": "这里应该用〈清楚〉。公正用于人、裁决和制度，讲解明白要说〈清楚〉。"}, {"text": "房间打扫得很公正。", "explanation": "这里应该用〈干净〉。公正不用来形容清洁程度，要说〈干净〉。"}, {"text": "他学习很公正，成绩很好。", "explanation": "这里应该用〈刻苦〉。公正指对人一视同仁，学习的努力程度要说〈刻苦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：形容“排”的方式，指一视同仁地安排。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”形容说话或读写顺畅，不用来修饰“排座位”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”是情绪，不能用来形容班长安排座位的方式。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来修饰“排座位”。"}], "explanations": {"公正": "正确：形容“排”的方式，指一视同仁地安排。", "流利": "搭配：“流利”形容说话或读写顺畅，不用来修饰“排座位”。", "悲伤": "语义：“悲伤”是情绪，不能用来形容班长安排座位的方式。", "清脆": "搭配：“清脆”形容声音，不能用来修饰“排座位”。"}, "sentence_index": 6, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很公正，窗户很大。", "explanation": "这里应该用〈明亮〉。公正用于人、裁决和制度，形容光线要说〈明亮〉。"}, {"text": "这个蛋糕很公正，大家都爱吃。", "explanation": "这里应该用〈甜〉。公正不用来形容味道，形容蛋糕的味道要说〈甜〉。"}, {"text": "湖边的小镇很公正。", "explanation": "这里应该用〈宁静〉。公正不用来形容地方的环境，形容小镇的安静要说〈宁静〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师公正的批改了作业。", "corrected_sentence": "老师公正地批改了作业。", "error_description": "“公正”在句中修饰动词“批改”，作状语应用“地”，不用“的”：应说“公正地批改”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法公正，大家都很失望。", "corrected_sentence": "这种做法不公正，大家都很失望。", "error_description": "语义矛盾：“公正”是肯定评价，与后句“大家都很失望”不符，应在“公正”前加“不”，说“不公正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0087a302-9e61-4b40-bf3e-cdd7e8f5a6fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
