INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "玩的时候做的事情，比如玩玩具或者和朋友一起玩。", "primary_collocate": null, "pronunciation": "yóu xì", "ipa": "joʊ˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们在院子里玩游戏。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏很有意思，我们一起玩吧。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每天只能玩一个小时游戏。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捉迷藏是我小时候最喜欢的游戏。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在教室里做了一个有趣的游戏。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏需要四个人一起玩。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏结束后，大家都很开心。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不让我晚上玩手机游戏。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了游戏的规则。", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢玩什么游戏？", "target_word": "游戏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "游戏机", "label": "复合"}, {"form": "遊戲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "玩的时候做的事，如玩玩具、和朋友一起玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "邮寄", "is_correct": false, "explanation": "与“游戏”只有声母不同：xì 改为 jì（x 与 j 不同），意思是通过邮局把东西寄出去。"}, {"text": "游戏", "is_correct": true, "explanation": "正确：“游戏”指玩的时候做的事情，如玩玩具、和朋友一起玩。"}, {"text": "游记", "is_correct": false, "explanation": "与“游戏”只有声母不同：xì 改为 jì，意思是记述游览见闻的文章。"}, {"text": "油气", "is_correct": false, "explanation": "与“游戏”只有声母不同：xì 改为 qì（x 与 q 不同），意思是石油和天然气。"}, {"text": "有戏", "is_correct": false, "explanation": "与“游戏”只有声调不同：第一个音节 yóu（第二声）改为 yǒu（第三声），意思是有希望、有可能成功。"}], "explanations": {"邮寄": "与“游戏”只有声母不同：xì 改为 jì（x 与 j 不同），意思是通过邮局把东西寄出去。", "游戏": "正确：“游戏”指玩的时候做的事情，如玩玩具、和朋友一起玩。", "游记": "与“游戏”只有声母不同：xì 改为 jì，意思是记述游览见闻的文章。", "油气": "与“游戏”只有声母不同：xì 改为 qì（x 与 q 不同），意思是石油和天然气。", "有戏": "与“游戏”只有声调不同：第一个音节 yóu（第二声）改为 yǒu（第三声），意思是有希望、有可能成功。"}, "sentence_index": null, "correct_answer": "游戏"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“玩”后面不能接“作业”，要说“做作业”。"}, {"text": "游戏", "is_correct": true, "explanation": "正确：“玩游戏”是孩子们在院子里做的事。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是写出来的文字，不是可以拿来玩的东西，句子说不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是可以拿来玩的东西。"}], "explanations": {"作业": "搭配：“玩”后面不能接“作业”，要说“做作业”。", "游戏": "正确：“玩游戏”是孩子们在院子里做的事。", "作文": "语义：作文是写出来的文字，不是可以拿来玩的东西，句子说不通。", "数学": "语义：数学是一门学科，不是可以拿来玩的东西。"}, "sentence_index": 0, "correct_answer": "游戏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一只游戏。", "explanation": "这里应该用〈个〉。“只”是用于动物等的量词，游戏不能用“只”来数，应说“一个游戏”或“一场游戏”。"}, {"text": "我把游戏放进书包里，背到了学校。", "explanation": "这里应该用〈玩具〉。“游戏”指玩的时候做的事，不是能放进书包的东西。"}, {"text": "我最喜欢的游戏是一只会叫的小熊。", "explanation": "这里应该用〈玩具〉。“游戏”指玩的时候做的事，不能指可以拿在手里玩的东西；“一只会叫的小熊”是玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "语义：水是液体，不是一次活动，不能“结束”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“结束后”不能接“年龄”这样的词，年龄不会结束。"}, {"text": "游戏", "is_correct": true, "explanation": "正确：“游戏结束后”指一次玩耍活动完成之后，大家都很开心。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以结束的活动，句子说不通。"}], "explanations": {"水": "语义：水是液体，不是一次活动，不能“结束”。", "年龄": "搭配：“结束后”不能接“年龄”这样的词，年龄不会结束。", "游戏": "正确：“游戏结束后”指一次玩耍活动完成之后，大家都很开心。", "颜色": "语义：颜色不是可以结束的活动，句子说不通。"}, "sentence_index": 6, "correct_answer": "游戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一根游戏。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，游戏不用“根”来数。"}, {"text": "我们班今天玩了一条游戏。", "explanation": "这里应该用〈场〉。“条”用于细长或成条的东西，游戏不用“条”来数。"}, {"text": "他把一本游戏借给了朋友。", "explanation": "这里应该用〈个〉。“本”用于书籍和本子，游戏不用“本”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班刚玩了一只新游戏。", "corrected_sentence": "我们班刚玩了一个新游戏。", "error_description": "量词错了：“游戏”应该用“个”，说“一个新游戏”；“只”用于动物等，不能用来数游戏。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只游戏我们玩了一个小时。", "corrected_sentence": "这场游戏我们玩了一个小时。", "error_description": "量词错了：“游戏”应该用“场”，说“这场游戏”；“只”用于动物等，不能用来数游戏。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
