INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要看到或拿到东西。", "primary_collocate": null, "pronunciation": "zhǎo", "ipa": "ʈʂaʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "我在包里找钥匙。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书架上找一本书。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在冰箱里找吃的。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在床下找他的玩具。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在桌子上找粉笔。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地图上找我们的学校。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地上找硬币。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了半天，才看到我的书。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在抽屉里找剪刀。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在网上找一张好看的照片。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了", "label": "完成体"}, {"form": "找过", "label": "经历体"}, {"form": "找找", "label": "重叠"}, {"form": "找到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "在某处翻看，想看到或拿到东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23602, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示在某处翻看、想要拿到东西。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。"}, {"text": "照", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。"}], "explanations": {"找": "正确答案：找（zhǎo），表示在某处翻看、想要拿到东西。", "草": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。", "照": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。", "招": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。", "炒": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "买", "is_correct": false, "explanation": "配价：“买”需要购买场所和卖方，“在包里买钥匙”说不通。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示在包里翻看、寻找钥匙。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”不能用于在包里翻找东西，与句义不合。"}, {"text": "挂", "is_correct": false, "explanation": "语义：挂钥匙是把钥匙挂在钩子上，与“在包里”翻找的语境不合。"}], "explanations": {"买": "配价：“买”需要购买场所和卖方，“在包里买钥匙”说不通。", "找": "正确答案：找，表示在包里翻看、寻找钥匙。", "煮": "语义：“煮”不能用于在包里翻找东西，与句义不合。", "挂": "语义：挂钥匙是把钥匙挂在钩子上，与“在包里”翻找的语境不合。"}, "sentence_index": 0, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她找了一个拥抱。", "explanation": "这里应该用〈送〉。找是寻找，不表示给人拥抱，应说“送一个拥抱”。"}, {"text": "他找了一身汗。", "explanation": "这里应该用〈出〉。找是寻找，不能表示冒出汗水，应说“出了一身汗”。"}, {"text": "妈妈正在用布找桌子。", "explanation": "这里应该用〈擦〉。找是寻找，不表示擦拭桌面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23602, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示在某处翻看、想要拿到东西。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。"}, {"text": "罩", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。"}, {"text": "枣", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是枣子。"}], "explanations": {"找": "正确答案：找（zhǎo），表示在某处翻看、想要拿到东西。", "早": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。", "罩": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。", "招": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。", "枣": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是枣子。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：烧硬币与“蹲在地上找硬币”的语境不合。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示蹲在地上寻找硬币。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”指咽下，与“蹲在地上找硬币”的语境冲突。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，硬币不能喝。"}], "explanations": {"烧": "语义：烧硬币与“蹲在地上找硬币”的语境不合。", "找": "正确答案：找，表示蹲在地上寻找硬币。", "吞": "搭配：“吞”指咽下，与“蹲在地上找硬币”的语境冲突。", "喝": "搭配：“喝”的对象是饮品，硬币不能喝。"}, "sentence_index": 6, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了很好的作用。", "explanation": "这里应该用〈发挥〉。找是寻找，不能与“作用”搭配表示起到效果，应说“发挥作用”。"}, {"text": "他找了老师的批评。", "explanation": "这里应该用〈接受〉。找表示寻找，不能与“批评”搭配表示承受，承受批评要用接受。"}, {"text": "他找了一个愿望。", "explanation": "这里应该用〈许〉。找是寻找，不表示提出愿望，应说“许一个愿望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他柜子里找那个盒子。", "corrected_sentence": "他在柜子里找那个盒子。", "error_description": "错误在“柜子里”前缺少介词“在”。表示在某处寻找时，地点要用“在……里”引出，应说“在柜子里找”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找了半天，终于找了到钥匙。", "corrected_sentence": "我找了半天，终于找到了钥匙。", "error_description": "错误在“找了到”。结果补语“到”必须紧跟动词，应为“找到”，再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
