INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示可以做得到。", "primary_collocate": null, "pronunciation": "zú yǐ", "ipa": "tsu˧˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "这点钱足以买一张车票。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的经验足以带好这个新团队。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个小时足以走到学校。", "target_word": "足以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些证据足以说明他没有说谎。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的努力足以让所有人佩服。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间足以住下五个人。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一点点雨水不足以解决问题。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的粮食足以吃到明年春天。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩足以考上好大学。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片足以证明他来过这里。", "target_word": "足以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不足以", "label": "否定形式"}], "register": "书面", "sense_fingerprint": "数量、条件、能力等已经够用，可以做到某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6cfd6c5-0201-4335-98b8-7045c06a3902') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化的过程，与“买一张车票”这种一次性行为矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”表示突然发生，不能修饰“这点钱买车票”这样平稳的行为。"}, {"text": "足以", "is_correct": true, "explanation": "足以：表示数量、条件够用，这点钱可以买一张车票，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“买一张车票”的单次行为矛盾。"}], "explanations": {"渐渐": "语义：“渐渐”表示逐步变化的过程，与“买一张车票”这种一次性行为矛盾。", "猛然": "搭配：“猛然”表示突然发生，不能修饰“这点钱买车票”这样平稳的行为。", "足以": "足以：表示数量、条件够用，这点钱可以买一张车票，符合句意。", "一直": "语义：“一直”表示持续不断，与“买一张车票”的单次行为矛盾。"}, "sentence_index": 0, "correct_answer": "足以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你足以走了。", "explanation": "这里应该用〈可以〉。足以表示能力或条件够不够，表示允许离开要用“可以”，“足以走了”会被理解成“你有能力走”。"}, {"text": "这本书足以不错。", "explanation": "这里应该用〈很〉。足以表示条件够不够，后面不能直接接形容词；表示程度要用“很”。"}, {"text": "你足以早点休息。", "explanation": "这里应该用〈应该〉。足以表示条件够不够，表示建议要用“应该”，不能说“足以早点休息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰有意志的施事者，雨水不能“亲自”解决问题。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，雨水没有意图，与句意不合。"}, {"text": "足以", "is_correct": true, "explanation": "足以：表示条件够不够，雨水不足以解决问题，符合句意。"}, {"text": "竭力", "is_correct": false, "explanation": "语义：“竭力”表示尽全力，雨水不能竭力行事，与句意不合。"}], "explanations": {"亲自": "搭配：“亲自”修饰有意志的施事者，雨水不能“亲自”解决问题。", "故意": "语义：“故意”表示有意为之，雨水没有意图，与句意不合。", "足以": "足以：表示条件够不够，雨水不足以解决问题，符合句意。", "竭力": "语义：“竭力”表示尽全力，雨水不能竭力行事，与句意不合。"}, "sentence_index": 6, "correct_answer": "足以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他足以来过这里。", "explanation": "这里应该用〈可能〉。足以表示条件够用，推测“来过这里”要用“可能”。"}, {"text": "天冷了，你足以多穿点衣服。", "explanation": "这里应该用〈应该〉。足以表示条件够不够，表示建议要用“应该”，不能说“足以多穿点衣服”。"}, {"text": "他足以不太舒服。", "explanation": "这里应该用〈好像〉。足以表示条件够不够，表示推测“他不太舒服”要用“好像”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些零钱很足以买一瓶水。", "corrected_sentence": "这些零钱足以买一瓶水。", "error_description": "副词错误：“足以”本身是副词，不能再被“很”修饰；应去掉“很”，说“这些零钱足以买一瓶水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么小的火没足以烧毁整座房子。", "corrected_sentence": "这么小的火不足以烧毁整座房子。", "error_description": "错误：否定“足以”要用否定副词“不”，说“不足以”，不能用“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实世界", "is_correct": true, "explanation": "反义：“现实世界”指真实存在的世界，与“虚拟世界”相对。"}, {"text": "田野", "is_correct": false, "explanation": "无关：“田野”指种植庄稼的开阔地，与“虚拟世界”没有反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "无关：“森林”指大片的树木，与“虚拟世界”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”指流动的水体，与“虚拟世界”没有反义关系。"}], "correct_answer": "现实世界", "explanations": {"现实世界": "反义：“现实世界”指真实存在的世界，与“虚拟世界”相对。", "田野": "无关：“田野”指种植庄稼的开阔地，与“虚拟世界”没有反义关系。", "森林": "无关：“森林”指大片的树木，与“虚拟世界”没有反义关系。", "河流": "无关：“河流”指流动的水体，与“虚拟世界”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实世界", "is_correct": true, "explanation": "反义：“现实世界”指真实存在的世界，与“虚拟世界”相对。"}, {"text": "大海", "is_correct": false, "explanation": "无关：“大海”指广阔的海水，与“虚拟世界”没有反义关系。"}, {"text": "高山", "is_correct": false, "explanation": "无关：“高山”指高耸的山体，与“虚拟世界”没有反义关系。"}, {"text": "城市", "is_correct": false, "explanation": "无关：“城市”指人口集中的居住区，与“虚拟世界”没有反义关系。"}], "correct_answer": "现实世界", "explanations": {"现实世界": "反义：“现实世界”指真实存在的世界，与“虚拟世界”相对。", "大海": "无关：“大海”指广阔的海水，与“虚拟世界”没有反义关系。", "高山": "无关：“高山”指高耸的山体，与“虚拟世界”没有反义关系。", "城市": "无关：“城市”指人口集中的居住区，与“虚拟世界”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电脑里像真世界一样的地方。", "primary_collocate": null, "pronunciation": "xū nǐ shì jiè", "ipa": "ɕy˥ ni˨˩˦ ʂɨ˥˩ tɕjɛ˥˩", "syllable_count": 4, "sentences": [{"text": "他每天晚上都在虚拟世界里玩游戏。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个虚拟世界看起来像真的一样。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在虚拟世界里有很多朋友。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不应该一直待在虚拟世界里。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戴上眼镜，你就能走进虚拟世界。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虚拟世界里的房子很漂亮。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在虚拟世界里开了一家小店。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏做了一个很大的虚拟世界。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人觉得虚拟世界比现实更有意思。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担心我太喜欢虚拟世界。", "target_word": "虚拟世界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虛擬世界", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由电脑做出来、像现实一样的网络空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚拟世界", "is_correct": true, "explanation": "正确：“虚拟世界”指电脑里像真实世界一样的空间，适合玩游戏。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是埋葬死者的地方，不能在里面玩游戏。"}, {"text": "鞋盒", "is_correct": false, "explanation": "语义：鞋盒是装鞋的小盒子，人不能每天晚上待在里面玩游戏。"}, {"text": "教堂", "is_correct": false, "explanation": "语义：教堂是宗教场所，与玩游戏的语境不符。"}], "explanations": {"虚拟世界": "正确：“虚拟世界”指电脑里像真实世界一样的空间，适合玩游戏。", "墓地": "语义：墓地是埋葬死者的地方，不能在里面玩游戏。", "鞋盒": "语义：鞋盒是装鞋的小盒子，人不能每天晚上待在里面玩游戏。", "教堂": "语义：教堂是宗教场所，与玩游戏的语境不符。"}, "sentence_index": 0, "correct_answer": "虚拟世界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷在虚拟世界里出生，又在虚拟世界里老去。", "explanation": "这里应该用〈现实世界〉。“虚拟世界”指电脑里的空间，人不能在其中出生、老去。"}, {"text": "这个虚拟世界是用石头砌成的，很结实。", "explanation": "这里应该用〈城堡〉。“虚拟世界”是电脑里的空间，不是石头砌成的实物。"}, {"text": "他把一个真的西瓜放进了虚拟世界。", "explanation": "这里应该用〈冰箱〉。“虚拟世界”是电脑里的空间，真的西瓜不能放进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚拟世界", "is_correct": true, "explanation": "正确：“虚拟世界”是电脑中的空间，可以在里面开店。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是用来装东西的，不能在里面开店。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是保存食物的电器，不能在里面开店。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛里”不是开店的场所，说法不通。"}], "explanations": {"虚拟世界": "正确：“虚拟世界”是电脑中的空间，可以在里面开店。", "书包": "语义：书包是用来装东西的，不能在里面开店。", "冰箱": "语义：冰箱是保存食物的电器，不能在里面开店。", "眼睛": "搭配：“眼睛里”不是开店的场所，说法不通。"}, "sentence_index": 6, "correct_answer": "虚拟世界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在虚拟世界里被大雨淋湿了。", "explanation": "这里应该用〈现实世界〉。“虚拟世界”指电脑里的空间，被大雨淋湿只能发生在现实世界。"}, {"text": "妈妈在虚拟世界里晒被子。", "explanation": "这里应该用〈现实生活〉。“虚拟世界”指电脑里的空间，晒被子要在现实生活中进行。"}, {"text": "爷爷在虚拟世界里种了一棵真的苹果树。", "explanation": "这里应该用〈土地〉。苹果树要种在真实的土地上，“虚拟世界”只是电脑里的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块虚拟世界很大。", "corrected_sentence": "这个虚拟世界很大。", "error_description": "量词用错：“虚拟世界”要用量词“个”，“块”用于片状的东西，不能用来量虚拟世界，应说“这个虚拟世界很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把虚拟世界很有意思。", "corrected_sentence": "这个虚拟世界很有意思。", "error_description": "量词用错：“虚拟世界”要用量词“个”，“把”用于有柄的器具，不能用来量虚拟世界，应说“这个虚拟世界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
