INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做各种事情，注重做事的态度与方法。", "primary_collocate": null, "pronunciation": "zuò shì", "ipa": "tswo˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "做事之前，先想一想后果。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢一个人做事，不爱麻烦别人。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事不能只图快，要做好。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别急，慢慢做事，不会错的。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她做事总是先想后做。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子小，不会做事，要多教他。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我现在心情不好，没法做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饱饭才有力气做事。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他边听音乐边做事，效率很高。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事要诚实，对人要有礼貌。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了事", "label": "体标（了）"}, {"form": "做过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "做事：做各种事情，强调做事的态度与方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。做事指做各种事情，强调做事的态度与方法。"}, {"text": "错事", "is_correct": false, "explanation": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。"}, {"text": "作诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。"}, {"text": "坐实", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}], "explanations": {"做事": "正确。做事指做各种事情，强调做事的态度与方法。", "错事": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。", "作诗": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。", "坐实": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}, "sentence_index": null, "correct_answer": "做事"}, "level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“做事之前，先想一想后果”指行动前要先考虑结果。"}, {"text": "打喷嚏", "is_correct": false, "explanation": "语义：打喷嚏是不由自主的反应，之前无法有意识地“先想一想后果”，句意不通。"}, {"text": "打哈欠", "is_correct": false, "explanation": "语义：打哈欠之前不需要想“后果”，句意不通。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“发呆之前”后接“先想一想后果”，语义矛盾。"}], "explanations": {"做事": "正确。“做事之前，先想一想后果”指行动前要先考虑结果。", "打喷嚏": "语义：打喷嚏是不由自主的反应，之前无法有意识地“先想一想后果”，句意不通。", "打哈欠": "语义：打哈欠之前不需要想“后果”，句意不通。", "发呆": "搭配：“发呆之前”后接“先想一想后果”，语义矛盾。"}, "sentence_index": 0, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头做事很认真，从来不偷懒。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，石头不能做事。"}, {"text": "他做事了一张桌子，很结实。", "explanation": "这里应该用〈做〉。“做事”不能带“一张桌子”这类具体物件作宾语，应说“做了一张桌子”。"}, {"text": "这把椅子做事很稳，坐上去很舒服。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，椅子不能做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“心情不好，没法做事”指因心情影响而无法工作或处理事情。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：人不会发芽，与“我心情不好”不合。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物的成长过程，与“心情不好”的原因无关。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“没法出生”不是可以因心情而受影响的行为，搭配不成立。"}], "explanations": {"做事": "正确。“心情不好，没法做事”指因心情影响而无法工作或处理事情。", "发芽": "语义：人不会发芽，与“我心情不好”不合。", "生长": "语义：“生长”指生物的成长过程，与“心情不好”的原因无关。", "出生": "搭配：“没法出生”不是可以因心情而受影响的行为，搭配不成立。"}, "sentence_index": 6, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥做事很稳，车来车往也不晃。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，桥不能做事。"}, {"text": "他做事了一锅饭，香极了。", "explanation": "这里应该用〈做〉。“做事”不能带“一锅饭”作宾语，应说“做了一锅饭”。"}, {"text": "这个灯泡做事很亮，照得屋里一片明亮。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，灯泡不能做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在厨房里做了事，忙个不停。", "corrected_sentence": "妈妈正在厨房里做事，忙个不停。", "error_description": "“做事”的“了”位置错误。“正在……”表示进行中，不能接“了”，应说“正在厨房里做事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事得很快，大家都夸他。", "corrected_sentence": "他做事做得很快，大家都夸他。", "error_description": "补语结构错误。“做事”后的补语要用“做得……”，缺少“做”会使句子不通，应说“做事做得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写文字，与“输”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与“输”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指行走或离开，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "写": "“写”指书写文字，与“输”没有反义关系。", "唱": "“唱”指发出歌声，与“输”没有反义关系。", "走": "“走”指行走或离开，与“输”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指把食物咽下，与“输”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看文字并发出声音，与“输”没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”指身体向上离开地面，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "吃": "“吃”指把食物咽下，与“输”没有反义关系。", "读": "“读”指看文字并发出声音，与“输”没有反义关系。", "跳": "“跳”指身体向上离开地面，与“输”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比赛或游戏中，没有赢。", "primary_collocate": null, "pronunciation": "shū", "ipa": "ʂu˥", "syllable_count": 1, "sentences": [{"text": "我们队输了这场球。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他玩游戏总是输。", "target_word": "输", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明和我下棋，我输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟输了，哭了起来。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁输了谁请客。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这局游戏我又输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打球从来不怕输。", "target_word": "输", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛结束了，红队输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输了比赛，他一点也不生气。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他输给了班里最小的同学。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "输了", "label": "体标（了）"}, {"form": "输过", "label": "体标（过）"}, {"form": "输掉", "label": "复合词"}, {"form": "输赢", "label": "复合词"}], "register": "通用", "sense_fingerprint": "比赛或游戏中没有赢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。"}, {"text": "属", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}], "explanations": {"输": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。", "熟": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。", "属": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。", "树": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“输了这场球”表示这场比赛没有赢，符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使物体跌落或撞击，“摔了这场球”不能表示比赛的结果。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，“扔了这场球”与比赛的语境不符。"}, {"text": "捡", "is_correct": false, "explanation": "语义：“捡”指拾取，“捡了这场球”不能表示比赛的结果。"}], "explanations": {"输": "“输了这场球”表示这场比赛没有赢，符合句意。", "摔": "语义：“摔”指使物体跌落或撞击，“摔了这场球”不能表示比赛的结果。", "扔": "语义：“扔”指丢弃，“扔了这场球”与比赛的语境不符。", "捡": "语义：“捡”指拾取，“捡了这场球”不能表示比赛的结果。"}, "sentence_index": 0, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子输了，弟弟哭了起来。", "explanation": "这里应该用〈打碎〉。输用于比赛或游戏中的胜负，杯子摔碎要用打碎。"}, {"text": "气球输了，弟弟哭了起来。", "explanation": "这里应该用〈爆〉。输用于比赛、竞争中的胜负，气球破裂要用爆。"}, {"text": "书包输了，弟弟哭了起来。", "explanation": "这里应该用〈丢〉。输只用于比赛、竞争中的胜负，书包丢失要用丢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是薯类，如土豆、红薯。"}, {"text": "竖", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}], "explanations": {"输": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。", "薯": "shǔ（第三声）与 shū（第一声）声调不同，意思是薯类，如土豆、红薯。", "竖": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。", "收": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“从来不怕输”表示不怕失败，符合打球的语境。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”指用手臂环绕，“不怕抱”与打球的语境不符，句子说不通。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不能与“怕”构成“不怕撕”这样的说法，不能表示对打球的态度。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧切断，“不怕砍”与打球的语境不符。"}], "explanations": {"输": "“从来不怕输”表示不怕失败，符合打球的语境。", "抱": "语义：“抱”指用手臂环绕，“不怕抱”与打球的语境不符，句子说不通。", "撕": "搭配：“撕”不能与“怕”构成“不怕撕”这样的说法，不能表示对打球的态度。", "砍": "语义：“砍”指用刀斧切断，“不怕砍”与打球的语境不符。"}, "sentence_index": 6, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫输了一只耳朵。", "explanation": "这里应该用〈掉〉。输用于比赛或游戏中的胜负，身体部位脱落要用掉。"}, {"text": "他因为生病输了视力。", "explanation": "这里应该用〈丧失〉。输用于比赛、竞争中的胜负，视力的丧失要用丧失。"}, {"text": "他输了信心，不想再练了。", "explanation": "这里应该用〈失去〉。输表示竞争中的失败，信心的失去要用失去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队这次输了很惨。", "corrected_sentence": "我们队这次输得很惨。", "error_description": "错误形式“输了很惨”，正确形式“输得很惨”。“很惨”是补语，须用结构助词“得”引出，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他输着三次比赛。", "corrected_sentence": "他输过三次比赛。", "error_description": "错误形式“输着三次比赛”，正确形式“输过三次比赛”。“着”表示状态的持续，描述已经发生过的经历要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合作", "is_correct": true, "explanation": "正确：“合作”与“竞争”相对，指共同努力完成同一目标。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食，与“竞争”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发出乐音，与“竞争”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写文字，与“竞争”没有反义关系。"}], "correct_answer": "合作", "explanations": {"合作": "正确：“合作”与“竞争”相对，指共同努力完成同一目标。", "吃": "吃是进食，与“竞争”没有反义关系。", "唱": "唱是发出乐音，与“竞争”没有反义关系。", "写": "写是书写文字，与“竞争”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合作", "is_correct": true, "explanation": "正确：“合作”与“竞争”相对，指共同努力完成同一目标。"}, {"text": "读", "is_correct": false, "explanation": "读是看着文字出声或默念，与“竞争”没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是用线条或颜色描绘，与“竞争”没有反义关系。"}, {"text": "游", "is_correct": false, "explanation": "游是在水中移动，与“竞争”没有反义关系。"}], "correct_answer": "合作", "explanations": {"合作": "正确：“合作”与“竞争”相对，指共同努力完成同一目标。", "读": "读是看着文字出声或默念，与“竞争”没有反义关系。", "画": "画是用线条或颜色描绘，与“竞争”没有反义关系。", "游": "游是在水中移动，与“竞争”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或很多人想得到一样东西，就要努力比一比谁更好。", "primary_collocate": null, "pronunciation": "jìng zhēng", "ipa": "tɕiŋ⁵¹ ʈʂɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "三个人为第一名竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司正在为这个客户竞争。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们为一个机会竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不想和朋友竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在市场上互相竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小公司很难和大公司竞争。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个学生一直在竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三个同学都想竞争班长这个职位。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公平地竞争，谁好谁赢。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意和别人竞争这个机会。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竞争着", "label": "体标"}, {"form": "竞争了", "label": "体标"}, {"form": "竞争者", "label": "复合"}, {"form": "竞争力", "label": "复合"}, {"form": "競爭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为了得到同一个目标而互相比较、争取", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争", "is_correct": true, "explanation": "正确：“为第一名竞争”指为争取第一名而互相比较，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，不能接“为第一名”作目的对象。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与争取第一名的语境无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与争取第一名无关，句意不通。"}], "explanations": {"竞争": "正确：“为第一名竞争”指为争取第一名而互相比较，符合句意。", "结婚": "配价：“结婚”是不及物动词，不能接“为第一名”作目的对象。", "睡觉": "语义：睡觉与争取第一名的语境无关，句意不通。", "散步": "语义：散步是悠闲的活动，与争取第一名无关，句意不通。"}, "sentence_index": 0, "correct_answer": "竞争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们在战场上竞争，保卫家乡。", "explanation": "这里应该用〈战斗〉。竞争指为争取同一目标而互相比较，不是武力对抗。"}, {"text": "我们在学校里竞争，帮助有困难的同学。", "explanation": "这里应该用〈合作〉。竞争是互相争取，不是共同完成事情。"}, {"text": "这两份报告我们竞争一下，看看有什么不同。", "explanation": "这里应该用〈比较〉。竞争指为争取同一目标而较量，核对两样东西的异同要用比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争", "is_correct": true, "explanation": "正确：“一直在竞争”指两人持续互相争取，符合句意。"}, {"text": "下雪", "is_correct": false, "explanation": "配价：“下雪”是无施事动词，不能以“这两个学生”作主语。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：打雷是自然现象，不能用来描述学生。"}, {"text": "扎根", "is_correct": false, "explanation": "语义：扎根指植物或思想深入，不能说学生“一直在扎根”。"}], "explanations": {"竞争": "正确：“一直在竞争”指两人持续互相争取，符合句意。", "下雪": "配价：“下雪”是无施事动词，不能以“这两个学生”作主语。", "打雷": "语义：打雷是自然现象，不能用来描述学生。", "扎根": "语义：扎根指植物或思想深入，不能说学生“一直在扎根”。"}, "sentence_index": 6, "correct_answer": "竞争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们准备竞争老师，看看谁更厉害。", "explanation": "这里应该用〈比〉。竞争的对象是机会、职位等可争取的目标，不能把老师当作竞争对象；与人比试高下要用〈比〉。"}, {"text": "他决定竞争妈妈，要比她更努力。", "explanation": "这里应该用〈超过〉。竞争的对象是可争取的目标，不能是妈妈这样的亲人；想比她更好应说〈超过〉。"}, {"text": "妈妈每天早上竞争我们快点吃早饭。", "explanation": "这里应该用〈催〉。竞争指为争取同一目标而互相比较，让别人快点做事要用催。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人正在竞争了这个职位。", "corrected_sentence": "两个人正在竞争这个职位。", "error_description": "“正在……了”错误：“正在”表示动作进行，不能与表示完成的“了”同用，应去掉“了”，说“正在竞争这个职位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们竞争的很激烈，每个人都想赢。", "corrected_sentence": "他们竞争得很激烈，每个人都想赢。", "error_description": "“的”误用：表示动作程度的补语要用“得”，应为“竞争得很激烈”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输", "is_correct": true, "explanation": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”指进食，与“赢”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”指歌唱，与“赢”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”指奔跑，与“赢”没有反义关系。"}], "correct_answer": "输", "explanations": {"输": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。", "吃": "无关：“吃”指进食，与“赢”没有反义关系。", "唱": "无关：“唱”指歌唱，与“赢”没有反义关系。", "跑": "无关：“跑”指奔跑，与“赢”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输", "is_correct": true, "explanation": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。"}, {"text": "走", "is_correct": false, "explanation": "无关：“走”指行走，与“赢”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”指睡觉，与“赢”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "无关：“读”指阅读，与“赢”没有反义关系。"}], "correct_answer": "输", "explanations": {"输": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。", "走": "无关：“走”指行走，与“赢”没有反义关系。", "睡": "无关：“睡”指睡觉，与“赢”没有反义关系。", "读": "无关：“读”指阅读，与“赢”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛或游戏中胜过对手，取得胜利。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "昨天的篮球比赛，我们班赢了。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下棋很厉害，每次都能赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥玩游戏，今天我赢了他两次。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个队赢了，哪个队就是第一名。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛太难了，我们不可能赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她赢过很多次跑步比赛。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队以三比一赢了对手。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩牌总想赢，输了就不高兴。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁先到终点，谁就赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我没赢，但是我很开心。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赢了", "label": "体标"}, {"form": "赢过", "label": "体标"}, {"form": "赢得", "label": "复合词"}, {"form": "赢家", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在比赛或游戏中胜过对手，取得胜利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影", "is_correct": false, "explanation": "yǐng（第三声）与 yíng（第二声）声调不同，意思是影子。"}, {"text": "赢", "is_correct": true, "explanation": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。"}, {"text": "硬", "is_correct": false, "explanation": "yìng（第四声）与 yíng（第二声）声调不同，意思是坚硬。"}, {"text": "银", "is_correct": false, "explanation": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子。"}], "explanations": {"影": "yǐng（第三声）与 yíng（第二声）声调不同，意思是影子。", "赢": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。", "硬": "yìng（第四声）与 yíng（第二声）声调不同，意思是坚硬。", "银": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子。"}, "sentence_index": null, "correct_answer": "赢"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "语义：“跑”指奔跑，与篮球比赛的胜负无关，无法说明“我们班”的结果。"}, {"text": "赢", "is_correct": true, "explanation": "正确：“赢”指在比赛中胜过对手，与“篮球比赛”和“我们班”的语境相符。"}, {"text": "踢", "is_correct": false, "explanation": "配价：“踢”是及物动词，需要“球”之类的宾语，“我们班踢了”缺少宾语，不能表示比赛结果。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与比赛的胜负无关。"}], "explanations": {"跑": "语义：“跑”指奔跑，与篮球比赛的胜负无关，无法说明“我们班”的结果。", "赢": "正确：“赢”指在比赛中胜过对手，与“篮球比赛”和“我们班”的语境相符。", "踢": "配价：“踢”是及物动词，需要“球”之类的宾语，“我们班踢了”缺少宾语，不能表示比赛结果。", "唱": "语义：“唱”指歌唱，与比赛的胜负无关。"}, "sentence_index": 0, "correct_answer": "赢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司工作，一个月赢了五千块。", "explanation": "这里应该用〈赚〉。“赢”用于比赛或游戏中取胜，工作挣钱要用“赚”。"}, {"text": "我们终于赢了困难。", "explanation": "这里应该用〈战胜〉。“赢”的对象是对手或比赛，克服困难要用“战胜”。"}, {"text": "这块蛋糕我赢了一半。", "explanation": "这里应该用〈吃〉。「赢」只用于比赛或游戏中取胜，吃东西要用「吃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "英", "is_correct": false, "explanation": "yīng（第一声）与 yíng（第二声）声调不同，意思是英国、英雄。"}, {"text": "赢", "is_correct": true, "explanation": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。"}, {"text": "鹰", "is_correct": false, "explanation": "yīng（第一声）与 yíng（第二声）声调不同，意思是老鹰。"}, {"text": "应", "is_correct": false, "explanation": "yìng（第四声）与 yíng（第二声）声调不同，意思是回应、答复。"}], "explanations": {"英": "yīng（第一声）与 yíng（第二声）声调不同，意思是英国、英雄。", "赢": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。", "鹰": "yīng（第一声）与 yíng（第二声）声调不同，意思是老鹰。", "应": "yìng（第四声）与 yíng（第二声）声调不同，意思是回应、答复。"}, "sentence_index": null, "correct_answer": "赢"}, "level_3": {"options": [{"text": "输", "is_correct": false, "explanation": "配价：“输”不能直接带“对手”作宾语，应说“输给对手”，这里不成立。"}, {"text": "赢", "is_correct": true, "explanation": "正确：“赢”指胜过对手，与“以三比一”的比分和“对手”搭配。"}, {"text": "碰", "is_correct": false, "explanation": "语义：“碰”指接触，与“三比一”的比分无关，不能表示战胜。"}, {"text": "帮", "is_correct": false, "explanation": "语义：“帮”指帮助，与比赛的胜负矛盾，语境不通。"}], "explanations": {"输": "配价：“输”不能直接带“对手”作宾语，应说“输给对手”，这里不成立。", "赢": "正确：“赢”指胜过对手，与“以三比一”的比分和“对手”搭配。", "碰": "语义：“碰”指接触，与“三比一”的比分无关，不能表示战胜。", "帮": "语义：“帮”指帮助，与比赛的胜负矛盾，语境不通。"}, "sentence_index": 6, "correct_answer": "赢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期他赢了很多节课。", "explanation": "这里应该用〈上〉。「赢」用于胜过对手，上课要用「上」。"}, {"text": "我今天赢了一封信。", "explanation": "这里应该用〈收到〉。“赢”不用于收信，收到信件要用“收到”。"}, {"text": "这个月他的体重赢了三公斤。", "explanation": "这里应该用〈增加〉。“赢”用于比赛中胜出，体重增加要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队以前赢了过几场比赛。", "corrected_sentence": "我们队以前赢过几场比赛。", "error_description": "错误：“赢了过”。正确：“赢过”。表示曾经有过的经历时，“过”已足够，不能同时加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛我没赢了他。", "corrected_sentence": "这次比赛我没赢他。", "error_description": "错误：“没赢了”。正确：“没赢”。“没”否定已经发生的动作时，“赢”后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
