INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做完一件事。", "primary_collocate": null, "pronunciation": "wán chéng", "ipa": "wan˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我已经完成作业了。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个小时就完成了工作。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天能完成这件事吗？", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于完成了这幅画。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个任务太难，我没完成。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在明天以前完成报告。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起完成了这个计划。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有完成过这么大的工作。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些练习完成了再回家。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业完成以后，我才可以玩手机。", "target_word": "完成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完成了", "label": "体标"}, {"form": "完成过", "label": "体标"}, {"form": "没完成", "label": "否定"}], "register": "中性", "sense_fingerprint": "完成|把一件事做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完成", "is_correct": true, "explanation": "正确。完成指把事情做完，“我已经完成作业了”符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语多为饮料等液体，不能说喝作业。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能说唱作业。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带“作业”作宾语。"}], "explanations": {"完成": "正确。完成指把事情做完，“我已经完成作业了”符合句意。", "喝": "搭配：“喝”的宾语多为饮料等液体，不能说喝作业。", "唱": "搭配：“唱”的宾语是歌曲，不能说唱作业。", "睡": "配价：“睡”是不及物动词，后面不能直接带“作业”作宾语。"}, "sentence_index": 0, "correct_answer": "完成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段恋爱终于完成了。", "explanation": "这里应该用〈结束〉。完成多用于任务、工作，恋爱的终止要说结束。"}, {"text": "他终于完成了冠军。", "explanation": "这里应该用〈获得〉。完成是把任务做完，拿到冠军要说获得，不能说完成冠军。"}, {"text": "这种病终于完成了。", "explanation": "这里应该用〈消失〉。完成指做完某件事，病症的消失要说消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完成", "is_correct": true, "explanation": "正确。完成指把事情做完，“我们一起完成了这个计划”符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，计划是抽象的事情，不能咬。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指整个咽下，计划无法被吞下，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语多为衣物，不能说穿计划。"}], "explanations": {"完成": "正确。完成指把事情做完，“我们一起完成了这个计划”符合句意。", "咬": "语义：“咬”指用牙齿夹住，计划是抽象的事情，不能咬。", "吞": "语义：“吞”指整个咽下，计划无法被吞下，句意不通。", "穿": "搭配：“穿”的宾语多为衣物，不能说穿计划。"}, "sentence_index": 6, "correct_answer": "完成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题终于完成了。", "explanation": "这里应该用〈解决〉。完成指做完任务，问题得到处理要说解决。"}, {"text": "这种情况很少完成。", "explanation": "这里应该用〈出现〉。完成指做完某件事，情况的显现要说出现，不能说完成。"}, {"text": "他的钥匙完成了。", "explanation": "这里应该用〈丢失〉。完成指把事情做完，东西遗失要说丢失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天不完成作业。", "corrected_sentence": "我昨天没完成作业。", "error_description": "“不”应改为“没”：表示过去没有做完，要用“没”来否定，不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校从未完成了这种项目。", "corrected_sentence": "这所学校从未完成过这种项目。", "error_description": "“了”应改为“过”：“从未”表示从来没有过的经历，要与“过”搭配，不能与“了”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
