INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23622, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指真的情况。", "primary_collocate": null, "pronunciation": "shí jì shàng", "ipa": "ʂɨ˧˥ tɕi˥˩ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "大家都说我去过北京，实际上我从来没去过。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都怪他，实际上这件事是我的错。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为他是老师，他实际上是学生。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说他刚知道，实际上我们昨天就知道了。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着很年轻，实际上比我大三岁。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上说不好吃，实际上这家饭店的菜很好吃。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上说喜欢，实际上一点儿也不喜欢这份工作。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都试过了，这个办法实际上没有用。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为明天要上课，实际上明天不用去学校。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问我饿不饿，我实际上已经吃过饭了。", "target_word": "实际上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说明事情本来的真实情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52c220fe-4ca5-4e18-bbc7-fbfacac2c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实际上", "is_correct": true, "explanation": "正确：点明与“大家都说”相反的真实情况。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经发生，与“从来没去过”的否定经历不搭配。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“从来没去过”的经历性否定不相容。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生的动作，不能引出“从来没去过”这类经历。"}], "explanations": {"实际上": "正确：点明与“大家都说”相反的真实情况。", "已经": "搭配：“已经”表示已经发生，与“从来没去过”的否定经历不搭配。", "一直": "语义：“一直”表示持续不断，与“从来没去过”的经历性否定不相容。", "立刻": "语义：“立刻”表示马上发生的动作，不能引出“从来没去过”这类经历。"}, "sentence_index": 0, "correct_answer": "实际上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府要实际上保障老人的权益。", "explanation": "这里应该用〈切实〉（副词，指认真、实实在在地做）。实际上只说明情况，不表示做事的态度。"}, {"text": "这个办法的实际上效果很好。", "explanation": "这里应该用〈实际〉（形容词，修饰“效果”）。实际上是副词，不能放在“的”之后修饰名词。"}, {"text": "我们要按实际上的数据来算。", "explanation": "这里应该用〈实际〉（形容词，修饰“数据”）。实际上是副词，不能加“的”修饰名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实际上", "is_correct": true, "explanation": "正确：“嘴上说喜欢”与“一点儿也不喜欢”形成反差，需要点明真实情况的“实际上”。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈之下的行为，不能用来描述态度。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙行动，与表示态度的“不喜欢”不搭。"}, {"text": "更加", "is_correct": false, "explanation": "搭配：“更加”表示程度递进，不能与“一点儿也不”搭配。"}], "explanations": {"实际上": "正确：“嘴上说喜欢”与“一点儿也不喜欢”形成反差，需要点明真实情况的“实际上”。", "只好": "语义：“只好”表示无奈之下的行为，不能用来描述态度。", "赶紧": "语义：“赶紧”表示急忙行动，与表示态度的“不喜欢”不搭。", "更加": "搭配：“更加”表示程度递进，不能与“一点儿也不”搭配。"}, "sentence_index": 6, "correct_answer": "实际上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对实际上的困难一直不肯说。", "explanation": "这里应该用〈实际〉（形容词，修饰“困难”）。实际上是副词，不能加“的”修饰名词。"}, {"text": "我们要从实际上考虑这个问题。", "explanation": "这里应该用〈实际〉（名词，“从实际出发”的“实际”）。实际上是副词，不能作“从”的宾语。"}, {"text": "这份工作的实际上待遇很低。", "explanation": "这里应该用〈实际〉（形容词，修饰“待遇”）。实际上是副词，不能放在“的”之后修饰名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都以为他很懂，实际上了连基本概念都不清楚。", "corrected_sentence": "大家都以为他很懂，实际上连基本概念都不清楚。", "error_description": "错误形式：“实际上了”；正确形式：“实际上”。“了”是动态助词，不能附着在副词“实际上”之后；这里只需陈述真实情况，不需要“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说自己很忙，实际上实际上一直在玩游戏。", "corrected_sentence": "他说自己很忙，实际上一直在玩游戏。", "error_description": "错误形式：“实际上实际上一直”；正确形式：“实际上一直”。“实际上”是副词，同一句中只出现一次，引出与“说自己很忙”相反的真实情况；重复使用语序不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6651a80d-9ff8-4af5-98fb-ee2d392b3a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
