INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一些东西放在一起变成一个新的东西。", "primary_collocate": null, "pronunciation": "zǔ chéng", "ipa": "tsu˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "几个同学组成了一个学习小组。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些字母组成一个英文词。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把几个朋友组成一个小乐队。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些词可以组成一个句子。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把句子组成一段话。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把十个人组成两个小队。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小零件能组成一台小机器。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一个队员组成一支足球队。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这三种颜色组成新的图案。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小块可以组成一幅完整的图画。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组成部分", "label": "复合"}], "register": "中性", "sense_fingerprint": "把若干东西合在一起，做成新的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23632, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：把若干东西合在一起，做成新的整体，正是这里要的词。"}, {"text": "赌城", "is_correct": false, "explanation": "“赌城”与“组成”声母不同，意思是以赌博闻名的城市（拉斯维加斯的别称）。"}, {"text": "府城", "is_correct": false, "explanation": "“府城”与“组成”声母不同，意思是旧时府一级行政机构所在的城市。"}, {"text": "铸成", "is_correct": false, "explanation": "“铸成”(zhùchéng)与“组成”声母、声调不同，意思是浇铸而成，如“铸成大错”。"}], "explanations": {"组成": "组成：把若干东西合在一起，做成新的整体，正是这里要的词。", "赌城": "“赌城”与“组成”声母不同，意思是以赌博闻名的城市（拉斯维加斯的别称）。", "府城": "“府城”与“组成”声母不同，意思是旧时府一级行政机构所在的城市。", "铸成": "“铸成”(zhùchéng)与“组成”声母、声调不同，意思是浇铸而成，如“铸成大错”。"}, "sentence_index": null, "correct_answer": "组成"}, "level_3": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：几个同学合在一起成为一个学习小组，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与同学、小组不搭，句子说不通。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能说“提高了一个小组”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与几个人合成一个小组无关。"}], "explanations": {"组成": "组成：几个同学合在一起成为一个学习小组，符合句意。", "吃": "语义：“吃”与同学、小组不搭，句子说不通。", "提高": "搭配：“提高”用于水平、质量，不能说“提高了一个小组”。", "洗": "语义：“洗”指清洗，与几个人合成一个小组无关。"}, "sentence_index": 0, "correct_answer": "组成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们组成了一个计划。", "explanation": "这里应该用〈制定〉。“组成”指把人或物拼合成实体，计划是抽象的，要说“制定计划”。"}, {"text": "我们组成了一场比赛。", "explanation": "这里应该用〈组织〉。“组成”用于把人或物拼成实体，比赛是活动，要说“组织比赛”。"}, {"text": "他组成了一棵树。", "explanation": "这里应该用〈种〉。“组成”指把现成的零件或材料拼合成一个东西，树是生长出来的，要说“种树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23632, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：把若干东西合在一起，做成新的整体，正是这里要的词。"}, {"text": "主城", "is_correct": false, "explanation": "“主城”与“组成”只有声母不同（翘舌与平舌），意思是城市的中心城区。"}, {"text": "古城", "is_correct": false, "explanation": "“古城”与“组成”声母不同，意思是古老的城市。"}, {"text": "筑城", "is_correct": false, "explanation": "“筑城”(zhùchéng)与“组成”声母、声调不同，意思是修筑城墙。"}], "explanations": {"组成": "组成：把若干东西合在一起，做成新的整体，正是这里要的词。", "主城": "“主城”与“组成”只有声母不同（翘舌与平舌），意思是城市的中心城区。", "古城": "“古城”与“组成”声母不同，意思是古老的城市。", "筑城": "“筑城”(zhùchéng)与“组成”声母、声调不同，意思是修筑城墙。"}, "sentence_index": null, "correct_answer": "组成"}, "level_3": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：把零件拼成一台机器，符合句意。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”用于乐曲、乐器，不能用于机器。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与机器不搭，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与零件拼成机器无关。"}], "explanations": {"组成": "组成：把零件拼成一台机器，符合句意。", "演奏": "搭配：“演奏”用于乐曲、乐器，不能用于机器。", "喝": "语义：“喝”与机器不搭，句子说不通。", "唱": "语义：“唱”指发声演唱，与零件拼成机器无关。"}, "sentence_index": 6, "correct_answer": "组成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她组成了良好的习惯。", "explanation": "这里应该用〈养成〉。“组成”指把东西拼成实体，习惯要说“养成习惯”。"}, {"text": "我们组成了一次讨论。", "explanation": "这里应该用〈进行〉。“组成”不用于活动，讨论要说“进行讨论”。"}, {"text": "她组成了远大的理想。", "explanation": "这里应该用〈怀有〉。理想是抽象的心愿，不能“组成”，要说“怀有理想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把同学们组成了几张小组。", "corrected_sentence": "老师把同学们组成了几个小组。", "error_description": "“小组”的量词应该用“个”，不能用“张”。“张”多用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把钢管组成的一个架子。", "corrected_sentence": "工人们把钢管组成了一个架子。", "error_description": "动态助词“了”应紧跟在“组成”之后，表示动作完成，应说“组成了”；写成“组成的”后整句变成名词短语，没有谓语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
