INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很奇怪的动物或东西。", "primary_collocate": null, "pronunciation": "guài wù", "ipa": "kwaɪ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "湖里好像有一只大怪物，很多人都见过。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是一只小怪物，有六条腿。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里传来怪声，大家以为有怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边看见一只怪物，马上跑回家。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，孩子们打扮成各种怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的怪物有大大的头和小小的身体。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只怪物不吃肉，只喝水。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，天上的云像一只大怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说山里以前有怪物，可是没人见过。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天梦见了一个绿色的怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}], "register": "口语", "sense_fingerprint": "样子很奇怪、让人害怕的动物或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怪物", "is_correct": true, "explanation": "正确：怪物指一种很奇怪的动物或东西，与“湖里好像有一只大怪物”相合。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不生活在湖里，“湖里好像有一只大老虎”与常识相反。"}, {"text": "熊猫", "is_correct": false, "explanation": "语义：熊猫不生活在湖里，与“很多人都见过”的语境不符。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“大”与“小猫”自相矛盾，“一只大小猫”搭配不当。"}], "explanations": {"怪物": "正确：怪物指一种很奇怪的动物或东西，与“湖里好像有一只大怪物”相合。", "老虎": "语义：老虎不生活在湖里，“湖里好像有一只大老虎”与常识相反。", "熊猫": "语义：熊猫不生活在湖里，与“很多人都见过”的语境不符。", "小猫": "搭配：“大”与“小猫”自相矛盾，“一只大小猫”搭配不当。"}, "sentence_index": 0, "correct_answer": "怪物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天冷了，我穿上了一件厚厚的怪物。", "explanation": "这里应该用〈衣服〉。穿在身上保暖的是衣服，“怪物”指很奇怪的动物或东西。"}, {"text": "我每天早上喝一杯怪物。", "explanation": "这里应该用〈牛奶〉。早上喝的是牛奶，“怪物”不能喝。"}, {"text": "他每天坐怪物去上班。", "explanation": "这里应该用〈地铁〉。上班坐的是交通工具，“怪物”指很奇怪的动物或东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怪物", "is_correct": true, "explanation": "正确：怪物指一种很奇怪的动物或东西，与“不吃肉，只喝水”相合。"}, {"text": "狼", "is_correct": false, "explanation": "语义：狼是肉食动物，“这只狼不吃肉”与常识相反。"}, {"text": "鳄鱼", "is_correct": false, "explanation": "语义：鳄鱼是肉食动物，“这只鳄鱼不吃肉”与常识相反。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼是肉食动物，“这只鲨鱼不吃肉”与常识相反。"}], "explanations": {"怪物": "正确：怪物指一种很奇怪的动物或东西，与“不吃肉，只喝水”相合。", "狼": "语义：狼是肉食动物，“这只狼不吃肉”与常识相反。", "鳄鱼": "语义：鳄鱼是肉食动物，“这只鳄鱼不吃肉”与常识相反。", "鲨鱼": "语义：鲨鱼是肉食动物，“这只鲨鱼不吃肉”与常识相反。"}, "sentence_index": 6, "correct_answer": "怪物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我口渴了，想喝一杯怪物。", "explanation": "这里应该用〈水〉。口渴要喝水，“怪物”不能喝。"}, {"text": "他每天骑怪物去学校。", "explanation": "这里应该用〈自行车〉。上学骑的是自行车，“怪物”指很奇怪的动物或东西。"}, {"text": "我用怪物给妈妈打电话。", "explanation": "这里应该用〈手机〉。打电话用手机，“怪物”指很奇怪的动物或东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖里有一本大怪物，把船都弄翻了。", "corrected_sentence": "湖里有一只大怪物，把船都弄翻了。", "error_description": "量词错误：“怪物”用量词“只”，“本”用于书籍，不能用于怪物，应说“一只大怪物”，不说“一本大怪物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟说房间里有很怪物，其实是他的玩具。", "corrected_sentence": "我弟弟说房间里有一个怪物，其实是他的玩具。", "error_description": "程度副词误加：“很”只修饰形容词，不能修饰名词“怪物”。应说“有一个怪物”，不说“有很怪物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
