INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在游戏或比赛中，把对方赢了。", "primary_collocate": null, "pronunciation": "dǎ bài", "ipa": "ta˨˩ pai̯˥˩", "syllable_count": 2, "sentences": [{"text": "昨天我在比赛中打败了他。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟玩游戏时打败了我。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班打败了二班，拿了第一。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在棋赛中打败了老师。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队打败了去年的冠军。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了一年，终于在乒乓球赛中打败了哥哥。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在游戏里打败了最后的怪物。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队打败了日本队，进了决赛。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李下棋时打败了爷爷。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红队打败蓝队，大家都很高兴。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打败了", "label": "体标"}, {"form": "打败过", "label": "体标"}, {"form": "打不败", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "在游戏或比赛中赢了对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“昨天我在比赛中打败了他”指在比赛中赢了对方，符合句意。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”不表示比赛中赢了对方，与“比赛中”的语境不符。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的宾语须是文件，不能指人。"}, {"text": "打捞", "is_correct": false, "explanation": "配价：“打捞”指从水中取出物体，不能用于比赛中的人。"}], "explanations": {"打败": "正确：“昨天我在比赛中打败了他”指在比赛中赢了对方，符合句意。", "打扮": "语义：“打扮”不表示比赛中赢了对方，与“比赛中”的语境不符。", "打印": "搭配：“打印”的宾语须是文件，不能指人。", "打捞": "配价：“打捞”指从水中取出物体，不能用于比赛中的人。"}, "sentence_index": 0, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打败了这盘棋。", "explanation": "这里应该用〈赢〉。棋局可以说赢，“打败”的对象须是对手，不能是“这盘棋”。"}, {"text": "我们打败了这场考试。", "explanation": "这里应该用〈通过〉。考试要说通过，“打败”的对象须是对手，不能用于考试。"}, {"text": "这次比赛我们打败了好成绩。", "explanation": "这里应该用〈取得〉。成绩要说取得，“打败”的对象须是对手，不能用于成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“在游戏里打败了最后的怪物”指在游戏中战胜对手，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场地，与战胜怪物无关。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄破物体，不能用来表示在游戏中的战胜。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}], "explanations": {"打败": "正确：“在游戏里打败了最后的怪物”指在游戏中战胜对手，符合句意。", "打扫": "语义：“打扫”指清理场地，与战胜怪物无关。", "打碎": "语义：“打碎”指弄破物体，不能用来表示在游戏中的战胜。", "打开": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}, "sentence_index": 6, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在教室里打败了一块黑板。", "explanation": "这里应该用〈擦〉。擦黑板要用擦，“打败”的对象须是对手，不能用于黑板。"}, {"text": "他把一袋大米打败了。", "explanation": "这里应该用〈搬〉。搬大米要用搬，“打败”的对象须是对手，不能用于大米。"}, {"text": "妈妈在厨房里打败了两个鸡蛋。", "explanation": "这里应该用〈打〉。把鸡蛋打开要说“打鸡蛋”，“打败”的对象须是对手，不能用于鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在上周的棋赛中打败着了表哥。", "corrected_sentence": "我在上周的棋赛中打败了表哥。", "error_description": "错误在于体标的叠用。“着”表示动作持续，“了”表示完成，二者不能同时用在“打败”之后，写成“打败着了”是错误。正确形式是“打败了表哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周的足球赛，我们队打败着三班。", "corrected_sentence": "上周的足球赛，我们队打败了三班。", "error_description": "错误在于体标。“打败”是一下子完成的结果，不能用表示持续的“着”。比赛已经结束，要用“了”表示完成。正确形式是“打败了三班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "“失败”与“成功”是反义词，指没有做成想做的事。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是慢慢走路放松身体的动作，与“成功”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音唱曲子，与“成功”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“成功”没有反义关系。"}], "correct_answer": "失败", "explanations": {"失败": "“失败”与“成功”是反义词，指没有做成想做的事。", "散步": "“散步”是慢慢走路放松身体的动作，与“成功”没有反义关系。", "唱歌": "“唱歌”指用声音唱曲子，与“成功”没有反义关系。", "旅行": "“旅行”指到外地游览，与“成功”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "“失败”与“成功”是反义词，指没有做成想做的事。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中运动，与“成功”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”指用笔作画，与“成功”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "“跳舞”指随音乐做动作，与“成功”没有反义关系。"}], "correct_answer": "失败", "explanations": {"失败": "“失败”与“成功”是反义词，指没有做成想做的事。", "游泳": "“游泳”指在水中运动，与“成功”没有反义关系。", "画画": "“画画”指用笔作画，与“成功”没有反义关系。", "跳舞": "“跳舞”指随音乐做动作，与“成功”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做了想做的事，得到了好结果。", "primary_collocate": null, "pronunciation": "chéng gōng", "ipa": "ʈʂʰɤŋ³⁵ kʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们的实验成功了。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了五次，终于成功了。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，她成功地拿到了第一名。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的办法成功了没有？", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭发射成功，大家都很高兴。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生做的手术成功了。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次做蛋糕就成功了。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不放弃，你一定会成功。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有成功，但是学到了很多。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李成功地爬上了那座山。", "target_word": "成功", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成功了", "label": "体标"}, {"form": "成功过", "label": "体标"}, {"form": "成功地", "label": "状语形式"}, {"form": "成功率", "label": "复合"}], "register": "中性", "sense_fingerprint": "成功|动词|做成想做的事，得到好结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成功", "is_correct": true, "explanation": "“成功”指做成想做的事，这里说我们的实验做成了。"}, {"text": "生气", "is_correct": false, "explanation": "语义：实验不会生气，“我们的实验生气了”说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：实验不会咳嗽，这句话没有意义。"}, {"text": "失去", "is_correct": false, "explanation": "配价：“失去”后面要带宾语，这个句子缺少宾语。"}], "explanations": {"成功": "“成功”指做成想做的事，这里说我们的实验做成了。", "生气": "语义：实验不会生气，“我们的实验生气了”说不通。", "咳嗽": "语义：实验不会咳嗽，这句话没有意义。", "失去": "配价：“失去”后面要带宾语，这个句子缺少宾语。"}, "sentence_index": 0, "correct_answer": "成功"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很成功。", "explanation": "这里应该用〈高〉。“成功”指做事取得好结果，形容个子高矮要用“高”。"}, {"text": "他每天早上成功一杯牛奶。", "explanation": "这里应该用〈喝〉。“成功”指做事取得好结果，不能带“一杯牛奶”这样的宾语；喝牛奶要用“喝”。"}, {"text": "她的身体很成功。", "explanation": "这里应该用〈健康〉。“成功”指做事取得好结果，形容身体状况要用“健康”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成功", "is_correct": true, "explanation": "“成功”指做成想做的事，这里说她第一次做蛋糕就做成了。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：做蛋糕不能“毕业”，这与“做蛋糕”的语境矛盾。"}, {"text": "退休", "is_correct": false, "explanation": "语义：第一次做蛋糕的人不会“退休”，这句话说不通。"}, {"text": "赞助", "is_correct": false, "explanation": "配价：“赞助”后面要带宾语，这个句子缺少宾语。"}], "explanations": {"成功": "“成功”指做成想做的事，这里说她第一次做蛋糕就做成了。", "毕业": "语义：做蛋糕不能“毕业”，这与“做蛋糕”的语境矛盾。", "退休": "语义：第一次做蛋糕的人不会“退休”，这句话说不通。", "赞助": "配价：“赞助”后面要带宾语，这个句子缺少宾语。"}, "sentence_index": 6, "correct_answer": "成功"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小李成功了很多新朋友。", "explanation": "这里应该用〈交〉。“成功”指做事取得好结果，不能带“朋友”作宾语；认识新朋友要用“交”。"}, {"text": "小李昨天成功了一场感冒。", "explanation": "这里应该用〈得〉。“成功”指做成想做的事，生病不是想做的事；得病要用“得”。"}, {"text": "小李在书店成功了一本书。", "explanation": "这里应该用〈买〉。“成功”不能带“一本书”这样的宾语；买东西要用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的计划成功着。", "corrected_sentence": "他们的计划成功了。", "error_description": "“成功”表示达到结果，是瞬间完成的变化，不能用“着”表示进行。应用“了”，即“成功了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他成功的完成了任务。", "corrected_sentence": "他成功地完成了任务。", "error_description": "“成功”修饰动词“完成”时要用状语标记“地”，不能用“的”。应为“成功地完成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
