INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你给我帮忙，我也给你帮忙。", "primary_collocate": null, "pronunciation": "hù xiāng bāng zhù", "ipa": "xu˥˩ ɕjɑŋ˥ pɑŋ˥ ʈʂu˥˩", "syllable_count": 4, "sentences": [{"text": "我们是好朋友，有事就互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，我和邻居互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人互相帮助，一起学汉语。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外，中国同学们常常互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你教我英语，我教你汉语，我们互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟姐妹应该互相帮助，不要吵架。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩住在一起，互相帮助，过得很开心。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友之间不用客气，互相帮助是应该的。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我和哥哥总是互相帮助。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们互相帮助，再难的事也不怕。", "target_word": "互相帮助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "互相幫助", "label": "繁体"}], "register": "口语", "sense_fingerprint": "你帮我、我帮你，朋友家人之间的日常帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互相帮助", "is_correct": true, "explanation": "正确：“好朋友”之间“有事就”彼此帮忙，与句意一致。"}, {"text": "疏远", "is_correct": false, "explanation": "配价：“疏远”需要带宾语（如疏远某人），放在这里句子不完整，也与“好朋友”矛盾。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：与“好朋友”的关系矛盾，好朋友有事时不会嫌弃对方。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“有事就逃避”与好朋友之间应有的互相帮助态度相反。"}], "explanations": {"互相帮助": "正确：“好朋友”之间“有事就”彼此帮忙，与句意一致。", "疏远": "配价：“疏远”需要带宾语（如疏远某人），放在这里句子不完整，也与“好朋友”矛盾。", "嫌弃": "语义：与“好朋友”的关系矛盾，好朋友有事时不会嫌弃对方。", "逃避": "语义：“有事就逃避”与好朋友之间应有的互相帮助态度相反。"}, "sentence_index": 0, "correct_answer": "互相帮助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几家基金会每年互相帮助贫困学生。", "explanation": "这里应该用〈资助〉。互相帮助指双方彼此帮忙，基金会向贫困学生提供经费是单方面的，应该用“资助”。"}, {"text": "几位教练每周互相帮助队员训练。", "explanation": "这里应该用〈指导〉。互相帮助要求双方彼此帮忙，教练训练队员是单向的，应该用“指导”。"}, {"text": "几个护士轮流互相帮助病人。", "explanation": "这里应该用〈照顾〉。互相帮助指彼此帮忙，护士对病人是单方面的照料，应该用“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互相帮助", "is_correct": true, "explanation": "正确：“住在一起”的两人彼此帮忙，才会“过得很开心”。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵会让人不开心，与“过得很开心”矛盾。"}, {"text": "冷落", "is_correct": false, "explanation": "配价：“冷落”需要带宾语（如冷落某人），单独使用句子不完整。"}, {"text": "独自生活", "is_correct": false, "explanation": "语义：与“住在一起”矛盾，两人住在一起不能说独自生活。"}], "explanations": {"互相帮助": "正确：“住在一起”的两人彼此帮忙，才会“过得很开心”。", "争吵": "语义：争吵会让人不开心，与“过得很开心”矛盾。", "冷落": "配价：“冷落”需要带宾语（如冷落某人），单独使用句子不完整。", "独自生活": "语义：与“住在一起”矛盾，两人住在一起不能说独自生活。"}, "sentence_index": 6, "correct_answer": "互相帮助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸互相帮助我去医院。", "explanation": "这里应该用〈陪〉。“互相”指双方彼此帮忙，这里只有“我爸爸”一方，应该用“陪”。"}, {"text": "几位老师常常互相帮助学生们。", "explanation": "这里应该用〈鼓励〉。互相帮助指双方彼此帮忙，老师对学生是单方面的鼓励，应该用“鼓励”。"}, {"text": "几位同学常常互相帮助失恋的他。", "explanation": "这里应该用〈安慰〉。互相帮助指彼此帮忙，同学对失恋的他是单方面的抚慰，应该用“安慰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们两个人互相互相帮助，一起学习汉语。", "corrected_sentence": "我们两个人互相帮助，一起学习汉语。", "error_description": "重复错误：“互相”已表示“彼此”，不能再叠加使用，应只说“互相帮助”，去掉多余的第二个“互相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩住在一起，常常把互相帮助，日子过得很开心。", "corrected_sentence": "他们俩住在一起，常常互相帮助，日子过得很开心。", "error_description": "“把”字句错误：“互相帮助”是不带宾语的动词，不能用在“把”字句中，应去掉“把”，说“常常互相帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
