INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手得到一样东西。", "primary_collocate": null, "pronunciation": "ná dào", "ipa": "na˧˥ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "我拿到了新手机。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口拿到了一封信。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拿到了妈妈给他的礼物。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿到钥匙了吗？", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在商店拿到了一个大袋子。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，学生们都拿到了自己的作业本。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在桌子上拿到了你的笔。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出手，拿到了树上的苹果。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子终于拿到了爸爸买的玩具。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在邮局拿到了朋友寄来的包。", "target_word": "拿到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿到了", "label": "完成体"}, {"form": "拿到过", "label": "经历体"}, {"form": "没拿到", "label": "否定式"}], "register": "中性", "sense_fingerprint": "用手把东西弄到手，得到某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23642, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拿到", "is_correct": true, "explanation": "正确答案。拿到：用手得到一样东西。"}, {"text": "来到", "is_correct": false, "explanation": "lái 与 ná 声母不同（l 与 n），声调相同，意思是到达某地，与“拿到”不同。"}, {"text": "那道", "is_correct": false, "explanation": "nà（第四声）与 ná（第二声）声调不同，意思是“那一道”（菜、题），与“拿到”不同。"}, {"text": "哪道", "is_correct": false, "explanation": "nǎ（第三声）与 ná（第二声）声调不同，意思是“哪一道”（菜、题），与“拿到”不同。"}, {"text": "拿刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是手里握着刀，与“拿到”不同。"}], "explanations": {"拿到": "正确答案。拿到：用手得到一样东西。", "来到": "lái 与 ná 声母不同（l 与 n），声调相同，意思是到达某地，与“拿到”不同。", "那道": "nà（第四声）与 ná（第二声）声调不同，意思是“那一道”（菜、题），与“拿到”不同。", "哪道": "nǎ（第三声）与 ná（第二声）声调不同，意思是“哪一道”（菜、题），与“拿到”不同。", "拿刀": "dāo（第一声）与 dào（第四声）声调不同，意思是手里握着刀，与“拿到”不同。"}, "sentence_index": null, "correct_answer": "拿到"}, "level_3": {"options": [{"text": "拿到", "is_correct": true, "explanation": "正确。“我拿到了新手机”表示用手或以其他方式得到新手机。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”用于水、茶等液体，手机不能喝。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，手机不能吃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多用于衣物、身体等，手机不能被洗。"}], "explanations": {"拿到": "正确。“我拿到了新手机”表示用手或以其他方式得到新手机。", "喝": "语义：“喝”用于水、茶等液体，手机不能喝。", "吃": "语义：“吃”指把食物咽下去，手机不能吃。", "洗": "搭配：“洗”多用于衣物、身体等，手机不能被洗。"}, "sentence_index": 0, "correct_answer": "拿到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下子拿到了一个晚上。", "explanation": "这里应该用〈度过〉。拿到只用于能用手取得的实物，时间要说度过。"}, {"text": "他一下车就拿到了火车站。", "explanation": "这里应该用〈到达〉。拿到表示用手取得实物，火车站是地点，不能拿到，要说到达。"}, {"text": "我在路上拿到了老同学。", "explanation": "这里应该用〈遇到〉。拿到只用于能用手取得的实物，人不能被拿到，遇见朋友要说遇到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿到", "is_correct": true, "explanation": "正确。“拿到了你的笔”表示用手取得你的笔。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字、信件，不能用“写”带“笔”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与桌上的笔无关。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，笔不能被穿。"}], "explanations": {"拿到": "正确。“拿到了你的笔”表示用手取得你的笔。", "写": "搭配：“写”的对象是文字、信件，不能用“写”带“笔”作宾语。", "唱": "语义：“唱”指发出歌声，与桌上的笔无关。", "穿": "搭配：“穿”用于衣服、鞋袜，笔不能被穿。"}, "sentence_index": 6, "correct_answer": "拿到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于拿到了一场雨，全家都很高兴。", "explanation": "这里应该用〈下〉。拿到只用于能用手取得的实物，雨是天气现象，要说下雨。"}, {"text": "这首歌让我拿到了温暖。", "explanation": "这里应该用〈感受到〉。拿到只用于能用手取得的东西，温暖是感觉，要说感受到。"}, {"text": "我在山顶拿到了美丽的景色。", "explanation": "这里应该用〈看到〉。拿到只用于能用手取得的东西，景色要用眼睛看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天拿到着一本新书。", "corrected_sentence": "我昨天拿到了一本新书。", "error_description": "错误：“拿到着”。正确：“拿到了”。“着”表示动作持续，而“昨天拿到”是一次性完成的动作，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天在学校没拿到了一本旧字典。", "corrected_sentence": "我今天在学校没拿到一本旧字典。", "error_description": "错误：“没拿到了”。正确：“没拿到”或“拿到了”。否定“没”与完成“了”不能同时用在同一个动词上，否定未发生的动作时要去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
