INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人排在一起走或站。", "primary_collocate": null, "pronunciation": "duì wu", "ipa": "twei˥˩ wu", "syllable_count": 2, "sentences": [{"text": "售票处前排着一条长长的队伍。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游行的队伍慢慢走过街道。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们排成整齐的队伍走进教室。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票的队伍一直排到了门口。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上，银行门口已经有很长的队伍。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们的队伍从广场前走过。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍太长了，我们等了半个小时。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家跟着队伍往前走。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在队伍的最后面，一直等着。", "target_word": "队伍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，队伍里的人都打开了伞。", "target_word": "队伍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条队伍", "label": "量词"}], "register": "中性", "sense_fingerprint": "队伍·排成行的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队伍", "is_correct": true, "explanation": "正确答案。“售票处前排着一条长长的队伍”指排队的人群，句意通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然水体，不能排在售票处前。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”是数量，不能说“排着一条人数”。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：“灯光”不能排列成长长的一条，与售票处前的场景不符。"}], "explanations": {"队伍": "正确答案。“售票处前排着一条长长的队伍”指排队的人群，句意通顺。", "河流": "语义：“河流”是自然水体，不能排在售票处前。", "人数": "搭配：“人数”是数量，不能说“排着一条人数”。", "灯光": "语义：“灯光”不能排列成长长的一条，与售票处前的场景不符。"}, "sentence_index": 0, "correct_answer": "队伍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这条队伍放进了抽屉里。", "explanation": "这里的“队伍”指走或站的一群人，不能当作放进抽屉的东西。"}, {"text": "我把这条队伍折成了纸船。", "explanation": "这里的“队伍”指排队的一群人，不能当作折成纸船的材料。"}, {"text": "他把买票的队伍装进了包里。", "explanation": "这里的“队伍”指排队的人群，不能当作装进包里的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队伍", "is_correct": true, "explanation": "正确答案。“队伍太长了，我们等了半个小时”指排队的人群很长，句意通顺。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“座位”说的是位置，不能说“座位太长”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是等待的对象，“声音太长了”与等待的语境不符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”是物体的尺寸，不能用来指等待的对象。"}], "explanations": {"队伍": "正确答案。“队伍太长了，我们等了半个小时”指排队的人群很长，句意通顺。", "座位": "搭配：“座位”说的是位置，不能说“座位太长”。", "声音": "语义：“声音”不是等待的对象，“声音太长了”与等待的语境不符。", "长度": "语义：“长度”是物体的尺寸，不能用来指等待的对象。"}, "sentence_index": 6, "correct_answer": "队伍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他把这条队伍装进了伞里。", "explanation": "这里的“队伍”指排队的一群人，不能当作装进伞里的东西。"}, {"text": "我们把队伍放进了冰箱。", "explanation": "这里的“队伍”指一群人，不能当作放进冰箱的食物。"}, {"text": "下雨了，这条队伍被他折成了一把伞。", "explanation": "这里的“队伍”指一群人，不能当作折成雨伞的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口排着一只长长的队伍。", "corrected_sentence": "门口排着一条长长的队伍。", "error_description": "错误在于量词。排队的“队伍”量词是“条”，不能用“只”，正确说法是“一条长长的队伍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站外面排着一只很长的队伍。", "corrected_sentence": "车站外面排着一条很长的队伍。", "error_description": "错误在于量词。排队的“队伍”量词是“条”，不能用“只”，正确说法是“一条很长的队伍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
