INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "有时赢，有时输，不是一直赢。", "primary_collocate": null, "pronunciation": "yǒu shū yǒu yíng", "ipa": "joʊ̯˨˩˦ ʂu˥˥ joʊ̯˨˩˦ iŋ˧˥", "syllable_count": 4, "sentences": [{"text": "今天我打牌有输有赢，不算太差。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他玩这个游戏有输有赢，不是每次都赢。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们赛跑有输有赢，我也赢过两次。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她练习打羽毛球的时候，常常有输有赢。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去年打球有输有赢，不是一直赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老李下棋总是赢，我和他下却有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人一直赢也没意思，有输有赢才好玩。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一年他们踢球有输有赢，排名在中间。", "target_word": "有输有赢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每个周末打篮球，结果都是有输有赢。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们玩了一下午，有输有赢，最后谁也没赢多少。", "target_word": "有输有赢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "有时赢有时输，并非总是赢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有输有赢", "is_correct": true, "explanation": "正确。这里说打牌时有时赢有时输，结果有起伏，所以“不算太差”。"}, {"text": "全输", "is_correct": false, "explanation": "语义：“全输”说一直落败，与“不算太差”的评价相矛盾。"}, {"text": "连输", "is_correct": false, "explanation": "语义：“连输”指接连失败，同样与“不算太差”的评价不协调。"}, {"text": "全赢", "is_correct": false, "explanation": "语义：“全赢”说次次获胜，与“不算太差”的平淡评价不协调。"}], "explanations": {"有输有赢": "正确。这里说打牌时有时赢有时输，结果有起伏，所以“不算太差”。", "全输": "语义：“全输”说一直落败，与“不算太差”的评价相矛盾。", "连输": "语义：“连输”指接连失败，同样与“不算太差”的评价不协调。", "全赢": "语义：“全赢”说次次获胜，与“不算太差”的平淡评价不协调。"}, "sentence_index": 0, "correct_answer": "有输有赢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天天气有输有赢，大家都不知道该穿什么。", "explanation": "这里应该用〈忽冷忽热〉。有输有赢只用于比赛或竞争，天气的冷暖变化要说忽冷忽热。"}, {"text": "他跑步的速度有输有赢。", "explanation": "这里应该用〈时快时慢〉。有输有赢指比赛的胜负，速度的快慢变化要说时快时慢。"}, {"text": "这个地区的雨量有输有赢。", "explanation": "这里应该用〈忽大忽小〉。有输有赢只用于竞争的胜负，雨量的多少变化要说忽大忽小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有输有赢", "is_correct": true, "explanation": "正确。这里说有赢也有输，因此一直赢才没意思。"}, {"text": "全赢", "is_correct": false, "explanation": "语义：“全赢”放在“才好玩”前表示次次获胜，与句中的正面评价相矛盾。"}, {"text": "一直输", "is_correct": false, "explanation": "语义：“一直输”表示次次落败，与“才好玩”的评价说不通。"}, {"text": "赢光", "is_correct": false, "explanation": "搭配：“赢光”指把对方的东西全部拿走，不用来描述比赛中的反复胜负。"}], "explanations": {"有输有赢": "正确。这里说有赢也有输，因此一直赢才没意思。", "全赢": "语义：“全赢”放在“才好玩”前表示次次获胜，与句中的正面评价相矛盾。", "一直输": "语义：“一直输”表示次次落败，与“才好玩”的评价说不通。", "赢光": "搭配：“赢光”指把对方的东西全部拿走，不用来描述比赛中的反复胜负。"}, "sentence_index": 6, "correct_answer": "有输有赢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写报告有输有赢，老板很满意。", "explanation": "这里应该用〈有板有眼〉。有输有赢只用于比赛或竞争，做事的条理和分寸要说有板有眼。"}, {"text": "我们一路有输有赢，聊得很开心。", "explanation": "这里应该用〈有说有笑〉。有输有赢只用于比赛或竞争，一路上的谈笑要说有说有笑。"}, {"text": "这篇文章写得有输有赢，很吸引人。", "explanation": "这里应该用〈有声有色〉。有输有赢只用于比赛或竞争，文章的精彩程度要说有声有色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这周踢球，很有输有赢。", "corrected_sentence": "我们这周踢球，有输有赢。", "error_description": "“有输有赢”前面不能加程度副词“很”。正确的说法是直接用“有输有赢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一场比赛我们有输有赢。", "corrected_sentence": "这几场比赛我们有输有赢。", "error_description": "“有输有赢”指多次比赛中有时赢有时输，一场比赛只有一个结果，不能说“有输有赢”。应把“一场”改为“几场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失分", "is_correct": true, "explanation": "正确：“失分”与“得分”构成反义，指比赛中失去分数。"}, {"text": "投篮", "is_correct": false, "explanation": "投篮：是得分的一种手段，不与“得分”相反。"}, {"text": "抢断", "is_correct": false, "explanation": "抢断：指夺取对方的球权，与“得分”没有反义关系。"}, {"text": "传球", "is_correct": false, "explanation": "传球：是进攻配合的动作，与“得分”不构成反义。"}], "correct_answer": "失分", "explanations": {"失分": "正确：“失分”与“得分”构成反义，指比赛中失去分数。", "投篮": "投篮：是得分的一种手段，不与“得分”相反。", "抢断": "抢断：指夺取对方的球权，与“得分”没有反义关系。", "传球": "传球：是进攻配合的动作，与“得分”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失分", "is_correct": true, "explanation": "正确：“失分”与“得分”构成反义，指比赛中失去分数。"}, {"text": "防守", "is_correct": false, "explanation": "防守：是阻止对方得分的行为，与“得分”不构成反义。"}, {"text": "运球", "is_correct": false, "explanation": "运球：是带球移动的动作，与“得分”没有反义关系。"}, {"text": "犯规", "is_correct": false, "explanation": "犯规：指违反比赛规则，与“得分”不构成反义。"}], "correct_answer": "失分", "explanations": {"失分": "正确：“失分”与“得分”构成反义，指比赛中失去分数。", "防守": "防守：是阻止对方得分的行为，与“得分”不构成反义。", "运球": "运球：是带球移动的动作，与“得分”没有反义关系。", "犯规": "犯规：指违反比赛规则，与“得分”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛或游戏中得到分数。", "primary_collocate": null, "pronunciation": "dé fēn", "ipa": "tɤ˧˥ fən˥˥", "syllable_count": 2, "sentences": [{"text": "他一投篮就得分了。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在游戏里很快就得分了。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪个队先得分，哪个队就有机会赢。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天没得分，但是传球很好。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红队在比赛开始五分钟就得分了。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想在游戏里得分，你要先找到钥匙。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她接住球，跑过去得分。", "target_word": "得分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们踢了一个小时，还是没有得分。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟玩游戏时，每次得分都很高兴。", "target_word": "得分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跳起来投球，轻松得分。", "target_word": "得分", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "得分了", "label": "体标"}, {"form": "得分手", "label": "复合"}], "register": "中性", "sense_fingerprint": "在比赛或游戏中得到分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b89829-f41d-414c-8971-ebd909ad5235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得分", "is_correct": true, "explanation": "正确：“一投篮就得分了”指投篮后获得分数，符合篮球语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与投篮得分的比赛情境无关，句子不成立。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：投篮不会让人毕业，句子不通。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“一投篮就搬家了”不合情理，搬家与投篮无关。"}], "explanations": {"得分": "正确：“一投篮就得分了”指投篮后获得分数，符合篮球语境。", "睡觉": "语义：“睡觉”与投篮得分的比赛情境无关，句子不成立。", "毕业": "语义：投篮不会让人毕业，句子不通。", "搬家": "语义：“一投篮就搬家了”不合情理，搬家与投篮无关。"}, "sentence_index": 0, "correct_answer": "得分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在图书馆看书，很快就得分了。", "explanation": "这里把“得分”用成了“读完、完成（阅读）”的意思，与本释义“在比赛或游戏中得到分数”不符。"}, {"text": "我昨天在超市买东西，一下子得分了很多钱。", "explanation": "这里把“得分”用成了“花费、支出（钱）”的意思，与本释义不符。"}, {"text": "小狗在院子里跑来跑去，已经得分了两次。", "explanation": "这里把“得分”用成了“计数、记作（次数）”的意思，与本释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得分", "is_correct": true, "explanation": "正确：“跑过去得分”指跑到位置后获得分数，符合篮球或足球语境。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：接住球后又放弃，与句中“跑过去”的行动意图矛盾。"}, {"text": "输掉", "is_correct": false, "explanation": "语义：“输掉”是比赛结果，与“接住球、跑过去”的动作不相合。"}, {"text": "落后", "is_correct": false, "explanation": "搭配：“跑过去”后不能接“落后”，二者没有搭配关系。"}], "explanations": {"得分": "正确：“跑过去得分”指跑到位置后获得分数，符合篮球或足球语境。", "放弃": "语义：接住球后又放弃，与句中“跑过去”的行动意图矛盾。", "输掉": "语义：“输掉”是比赛结果，与“接住球、跑过去”的动作不相合。", "落后": "搭配：“跑过去”后不能接“落后”，二者没有搭配关系。"}, "sentence_index": 6, "correct_answer": "得分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上起床，身体就得分了。", "explanation": "这里把“得分”用成了“得到、增长（健康状况）”的意思，与本释义不符。"}, {"text": "老师讲完课以后，我们都得分了很多新知识。", "explanation": "这里把“得分”用成了“学到（知识）”的意思，与本释义“在比赛或游戏中得到分数”不符。"}, {"text": "妈妈去银行存钱，利息得分了很多。", "explanation": "这里把“得分”用成了“增加、增长（金额）”的意思，与本释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最后时刻把我们队得分了。", "corrected_sentence": "他最后时刻为我们队得分了。", "error_description": "介词错误：“得分”是离合词，引出对象须用介词“为”，不能用“把”，应说“为我们队得分了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟跑到球门前，一脚就得分着。", "corrected_sentence": "弟弟跑到球门前，一脚就得分了。", "error_description": "“着”错误：“得分”表示一次性完成的动作，不能用“着”表示持续，应说“得分了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
