INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和你一起做一件事的人。", "primary_collocate": null, "pronunciation": "duì yǒu", "ipa": "twei˥˩ jou˨˩", "syllable_count": 2, "sentences": [{"text": "玩这个游戏时，我有两个队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做小组作业时，我的队友很认真。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们爬山时，队友一直在等我。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我在比赛中最好的队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行我们是队友，要一起走完。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个队友一起参加比赛。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队友太慢了，我只好一个人做。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你，你是个很好的队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里的队友都在等你开始。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的队友在山下等着我们。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "队友们", "label": "复数"}, {"form": "隊友", "label": "繁体"}], "register": "口语", "sense_fingerprint": "游戏、作业、旅行等活动中和你一起行动的搭档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友」指一起玩游戏的人，与语境相符。"}, {"text": "老板", "is_correct": false, "explanation": "语义：「老板」是雇用你的人，不会是一起玩游戏的人。"}, {"text": "房东", "is_correct": false, "explanation": "语义：「房东」是出租房屋的人，与玩游戏无关。"}, {"text": "长辈", "is_correct": false, "explanation": "语义：「长辈」指年长的亲属，不是一起玩游戏的人，与语境不合。"}], "explanations": {"队友": "正确：「队友」指一起玩游戏的人，与语境相符。", "老板": "语义：「老板」是雇用你的人，不会是一起玩游戏的人。", "房东": "语义：「房东」是出租房屋的人，与玩游戏无关。", "长辈": "语义：「长辈」指年长的亲属，不是一起玩游戏的人，与语境不合。"}, "sentence_index": 0, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上遇到一个队友，我们擦肩而过，互不相识。", "explanation": "这里应该用〈路人〉。「队友」指和你一起做事的人，擦肩而过的陌生人应说「路人」。"}, {"text": "我的队友每天为病人看病，我们从没一起做过事。", "explanation": "这里应该用〈医生〉。「队友」指和你一起做事的人，为病人看病的人应说「医生」，且「从没一起做过事」与「队友」矛盾。"}, {"text": "我的队友上周批改了我的作业，他从没和我一起做过事。", "explanation": "这里应该用〈老师〉。「队友」指和你一起做事的人，批改作业的人应说「老师」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友」是一起做事的同伴，太慢时只好自己做，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：「作业」是要完成的任务，不能作为会「太慢」行动的同伴。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是家具，不会做事，不能说「桌子太慢了」，也不是一起做事的人。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不会做事，不能说「太慢了」，也不能成为一起做事的人。"}], "explanations": {"队友": "正确：「队友」是一起做事的同伴，太慢时只好自己做，符合语境。", "作业": "语义：「作业」是要完成的任务，不能作为会「太慢」行动的同伴。", "桌子": "语义：「桌子」是家具，不会做事，不能说「桌子太慢了」，也不是一起做事的人。", "天气": "语义：「天气」不会做事，不能说「太慢了」，也不能成为一起做事的人。"}, "sentence_index": 6, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛时，队友在场上和我们对抗。", "explanation": "这里应该用〈对手〉。「队友」是同一队的人，在场上对抗我们的应说「对手」。"}, {"text": "这场比赛的队友判我犯规了。", "explanation": "这里应该用〈裁判〉。「队友」是参赛的人，不能判罚犯规；判罚的是「裁判」。"}, {"text": "这位队友买完东西就走了，我们没有一起做过任何事。", "explanation": "这里应该用〈顾客〉。「队友」指和你一起做事的人，只是来买东西、没有一起做事的人应说「顾客」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们是很好队友。", "corrected_sentence": "我们是很好的队友。", "error_description": "「很好」修饰名词「队友」时要加「的」。应说「很好的队友」，少了「的」就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个队友们都很认真。", "corrected_sentence": "每个队友都很认真。", "error_description": "「每个」后面不能加「们」。应说「每个队友」或「队友们」，二者不能合用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf369d4-aa4f-4ace-874e-273aacb8e532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
