INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做你想让他们做的事。", "primary_collocate": null, "pronunciation": "zhǐ huī", "ipa": "tʂɻ̩˨˩ xweɪ˥", "syllable_count": 2, "sentences": [{"text": "你别总想指挥我做事。", "target_word": "指挥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢指挥别人，自己却不动手。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥总是指挥弟弟去拿东西。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不是你的工人，你不要指挥我。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理坐在椅子上，只会指挥别人干活。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的妻子常常指挥他洗碗。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁给你的权力指挥我？", "target_word": "指挥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们不喜欢大人指挥自己玩游戏。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总想指挥全班同学听他的。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她太爱指挥人了，朋友都有点烦。", "target_word": "指挥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指挥了", "label": "完成体"}, {"form": "指挥着", "label": "持续体"}, {"form": "指挥过", "label": "经历体"}, {"form": "指揮", "label": "繁体"}], "register": "口语", "sense_fingerprint": "日常中支使、命令别人按自己的想法做事，常带不满的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指挥", "is_correct": true, "explanation": "指挥 zhǐ huī：让别人按自己的意思做事，带有支使的意味。"}, {"text": "智慧", "is_correct": false, "explanation": "智慧 zhì huì 与 zhǐ huī 两个音节的声调都不同（第四声对第三声，第四声对第一声），意思是聪明才智。"}, {"text": "只会", "is_correct": false, "explanation": "只会 zhǐ huì 与 zhǐ huī 只有第二个音节声调不同（huì 第四声，huī 第一声），意思是只能、只知道。"}, {"text": "止回", "is_correct": false, "explanation": "止回 zhǐ huí 与 zhǐ huī 只有第二个音节声调不同（huí 第二声，huī 第一声），意思是阻止回流，如止回阀。"}, {"text": "知会", "is_correct": false, "explanation": "知会 zhī huì 与 zhǐ huī 两个音节的声调都不同（第一声对第三声，第四声对第一声），意思是通知、告知。"}], "explanations": {"指挥": "指挥 zhǐ huī：让别人按自己的意思做事，带有支使的意味。", "智慧": "智慧 zhì huì 与 zhǐ huī 两个音节的声调都不同（第四声对第三声，第四声对第一声），意思是聪明才智。", "只会": "只会 zhǐ huì 与 zhǐ huī 只有第二个音节声调不同（huì 第四声，huī 第一声），意思是只能、只知道。", "止回": "止回 zhǐ huí 与 zhǐ huī 只有第二个音节声调不同（huí 第二声，huī 第一声），意思是阻止回流，如止回阀。", "知会": "知会 zhī huì 与 zhǐ huī 两个音节的声调都不同（第一声对第三声，第四声对第一声），意思是通知、告知。"}, "sentence_index": null, "correct_answer": "指挥"}, "level_3": {"options": [{"text": "指挥", "is_correct": true, "explanation": "正确。此处为动词，指支使对方按自己的意思做事，与“别总想……我做事”相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“总想感谢我做事”语义不通，“感谢”不能表示支使对方做事。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“我”作宾语。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“我”作宾语。"}], "explanations": {"指挥": "正确。此处为动词，指支使对方按自己的意思做事，与“别总想……我做事”相合。", "感谢": "语义：“总想感谢我做事”语义不通，“感谢”不能表示支使对方做事。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“我”作宾语。", "游泳": "配价：“游泳”是不及物动词，不能带“我”作宾语。"}, "sentence_index": 0, "correct_answer": "指挥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我指挥你原谅我的失误。", "explanation": "这里应该用〈请求〉。指挥是让人按自己的意思去做事，希望对方原谅要用“请求”。"}, {"text": "朋友指挥我，让我别难过。", "explanation": "这里应该用〈安慰〉。指挥含有发令、支使的意思，让人别难过要用“安慰”。"}, {"text": "老师指挥这个学生画得好。", "explanation": "这里应该用〈夸奖〉。指挥表示支使、发令，称赞别人的作品要用“夸奖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指挥", "is_correct": true, "explanation": "正确。此处为动词，指支使我、命令我做事，与“权力”的语境相合。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“呼吸”不能以人作宾语，“呼吸我”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“我”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“我”作宾语。"}], "explanations": {"指挥": "正确。此处为动词，指支使我、命令我做事，与“权力”的语境相合。", "呼吸": "配价：“呼吸”不能以人作宾语，“呼吸我”不成立。", "睡觉": "配价：“睡觉”是不及物动词，不能带“我”作宾语。", "散步": "配价：“散步”是不及物动词，不能带“我”作宾语。"}, "sentence_index": 6, "correct_answer": "指挥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我指挥你的选择。", "explanation": "这里应该用〈尊重〉。指挥是让人按自己的意思做事，对别人的选择表示尊重要用“尊重”。"}, {"text": "老师指挥了我的作文。", "explanation": "这里应该用〈修改〉。指挥是发令让人行动，对作文做批改、修订要用“修改”，作文不能被指挥。"}, {"text": "大家指挥他获奖。", "explanation": "这里应该用〈祝贺〉。获奖是结果，不能被指挥；对他获奖表示祝贺要用“祝贺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他指挥我了半天。", "corrected_sentence": "他指挥了我半天。", "error_description": "“了”应紧跟动词，说“指挥了我半天”，不能放在宾语“我”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总把我指挥团团转。", "corrected_sentence": "她总把我指挥得团团转。", "error_description": "“指挥”后面表示结果的补语要用“得”，应说“指挥得团团转”，不能省略“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
