INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看一个人或东西是不是真的很好。", "primary_collocate": null, "pronunciation": "kǎo yàn", "ipa": "kʰaʊ˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "时间会考验一个人是不是真朋友。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种手机质量好不好，要用时间来考验。", "target_word": "考验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难可以考验出谁是真心的朋友。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想考验一下女朋友是不是爱他。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用一个小任务考验新来的员工。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走很远的路，才能考验鞋好不好。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他假装没钱，想考验朋友会不会帮他。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风雨考验着这座老房子。", "target_word": "考验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想考验孩子是不是诚实。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有大雨才能考验屋顶好不好。", "target_word": "考验", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考验了", "label": "体标：完成"}, {"form": "考验着", "label": "体标：持续"}, {"form": "考验过", "label": "体标：经历"}], "register": "通用", "sense_fingerprint": "试一试人或东西是不是真的好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考验", "is_correct": true, "explanation": "正确：「考验」指试一试人或事物是不是真的好，与句意相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」表示喜爱称赞，不能用来检验朋友是不是真的。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」的对象是物品，不能与「是不是真朋友」这样的判断搭配。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：「咨询」需要以问题或专家为对象，不能接「一个人是不是真朋友」。"}], "explanations": {"考验": "正确：「考验」指试一试人或事物是不是真的好，与句意相合。", "欣赏": "语义：「欣赏」表示喜爱称赞，不能用来检验朋友是不是真的。", "收藏": "搭配：「收藏」的对象是物品，不能与「是不是真朋友」这样的判断搭配。", "咨询": "搭配：「咨询」需要以问题或专家为对象，不能接「一个人是不是真朋友」。"}, "sentence_index": 0, "correct_answer": "考验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都考验妈妈的照顾，却从不说一句谢谢。", "explanation": "这里应该用〈感谢〉。「考验」是试一试人或东西好不好，对妈妈的照顾表示谢意要用「感谢」。"}, {"text": "他每天都考验生病的妈妈。", "explanation": "这里应该用〈照顾〉。「考验」是试一试人或东西好不好，照顾生病的人要用「照顾」。"}, {"text": "妈妈考验孩子，不让他受到伤害。", "explanation": "这里应该用〈保护〉。「考验」是试探，不表示保护；使孩子不受伤害要用「保护」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考验", "is_correct": true, "explanation": "正确：「考验」指试探朋友会不会帮忙、是否真心，与句意相合。"}, {"text": "回报", "is_correct": false, "explanation": "语义：「回报」是报答别人，不是试探朋友。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：「打扮」是修饰外貌，与试探朋友的语境无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：「搬运」的对象是具体物品，不能接「朋友」。"}], "explanations": {"考验": "正确：「考验」指试探朋友会不会帮忙、是否真心，与句意相合。", "回报": "语义：「回报」是报答别人，不是试探朋友。", "打扮": "语义：「打扮」是修饰外貌，与试探朋友的语境无关。", "搬运": "搭配：「搬运」的对象是具体物品，不能接「朋友」。"}, "sentence_index": 6, "correct_answer": "考验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都考验宝宝吃饭。", "explanation": "这里应该用〈喂〉。「考验」是试一试人或东西好不好，喂孩子吃饭要用「喂」。"}, {"text": "她用彩灯考验房间。", "explanation": "这里应该用〈装饰〉。「考验」是试一试好不好，用彩灯美化房间要用「装饰」。"}, {"text": "老师轻声考验哭泣的学生，让他别难过。", "explanation": "这里应该用〈安慰〉。「考验」是试一试人或东西是不是真的好，让哭泣的学生别难过要用「安慰」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想考验了这台新机器的耐用性。", "corrected_sentence": "我想考验一下这台新机器的耐用性。", "error_description": "「想」表示打算，不能与表示完成的「了」搭配；表示试一试要用「一下」，应说「想考验一下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双新鞋我不考验过它的质量。", "corrected_sentence": "这双新鞋我还没考验过它的质量。", "error_description": "表示「从来没有过这种经历」要用「没」，应说「没考验过」；用「不」否定「过」表示的经历不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
