INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "伙伴就是和你一起玩或一起做事的人。", "primary_collocate": null, "pronunciation": "huǒ bàn", "ipa": "xwo pan", "syllable_count": 2, "sentences": [{"text": "我的伙伴今天没来学校。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他和伙伴们一起踢足球。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的伙伴在哪儿？", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明有很多好伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们几个伙伴一起做作业。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把玩具给了新伙伴。", "target_word": "伙伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和伙伴约好周末去爬山。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏需要两个伙伴。", "target_word": "伙伴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的伙伴帮他找到了书包。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都是好伙伴，要互相帮助。", "target_word": "伙伴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "伙伴们", "label": "复数"}, {"form": "小伙伴", "label": "复合词"}, {"form": "夥伴", "label": "繁体"}], "register": "口语", "sense_fingerprint": "伙伴：一起玩或一起做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伙伴", "is_correct": true, "explanation": "正确：“伙伴”指一起玩或一起做事的人，能够“没来学校”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能“没来学校”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地方，不是能够来学校的人，句子说不通。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“来”要求有生命的主语，“作业”不能来学校。"}], "explanations": {"伙伴": "正确：“伙伴”指一起玩或一起做事的人，能够“没来学校”。", "窗户": "语义：窗户不是人，不能“没来学校”。", "教室": "语义：教室是地方，不是能够来学校的人，句子说不通。", "作业": "配价：“来”要求有生命的主语，“作业”不能来学校。"}, "sentence_index": 0, "correct_answer": "伙伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车上坐满了伙伴。", "explanation": "这里应该用“乘客”。“伙伴”指一起玩或一起做事的人，不指乘车的人。"}, {"text": "医院里住着很多伙伴。", "explanation": "这里应该用“病人”。“伙伴”指一起玩或做事的人，不指看病住院的人。"}, {"text": "他是我的伙伴，我们正在打擂台，争个你死我活。", "explanation": "这里应该用“对手”。“伙伴”指一起做事、相互合作的人，与“你死我活”的竞争关系相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伙伴", "is_correct": true, "explanation": "正确：“伙伴”指一起做事的人，能够和人约好一起去爬山。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“约好”需要能与人约定的对象，闹钟不能和人约定去爬山。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李不能与人约好一起去爬山。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能和人约好周末去爬山。"}], "explanations": {"伙伴": "正确：“伙伴”指一起做事的人，能够和人约好一起去爬山。", "闹钟": "配价：“约好”需要能与人约定的对象，闹钟不能和人约定去爬山。", "行李": "语义：行李不能与人约好一起去爬山。", "雨伞": "语义：雨伞是物品，不能和人约好周末去爬山。"}, "sentence_index": 6, "correct_answer": "伙伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器里有两个伙伴坏了，需要换掉。", "explanation": "这里应该用“零件”。“伙伴”指共同做事、相互合作的人，不指机器的部件。"}, {"text": "剧场里坐满了伙伴。", "explanation": "这里应该用“观众”。“伙伴”指一起玩或做事的人，不指只来看演出的人。"}, {"text": "车站里站满了伙伴。", "explanation": "这里应该用“旅客”。“伙伴”指一起做事的人，不指等车出行的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有两个好伙伴们。", "corrected_sentence": "他有两个好伙伴。", "error_description": "“们”的误用：“伙伴”前已有数量词“两个”，不能再加复数后缀“们”。正确说法是“两个好伙伴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和弟弟是很好地伙伴。", "corrected_sentence": "我和弟弟是很好的伙伴。", "error_description": "结构助词错误：修饰名词“伙伴”要用“的”，不能用“地”。正确说法是“很好的伙伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
