INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都要遵守的做事方法。", "primary_collocate": null, "pronunciation": "guī zé", "ipa": "kweɪ˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "请大家遵守学校的规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的规则很简单。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心违反了比赛规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了新规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路要遵守交通规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司制定了一个新规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先看看规则，再开始玩。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都按规则排队买票。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规则是大家一起定的，不能随便改。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点以后不能玩手机，这是我家的规则。", "target_word": "规则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "交通规则", "label": "复合"}, {"form": "游戏规则", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家共同遵守的做事规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规则", "is_correct": true, "explanation": "“规则”是“遵守”的对象，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“遵守”的对象一般是规定、纪律，不能说“遵守课本”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，与“遵守”无关，句子不通。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是场地，不是可以遵守的东西，与句意不合。"}], "explanations": {"规则": "“规则”是“遵守”的对象，符合句意。", "课本": "搭配：“遵守”的对象一般是规定、纪律，不能说“遵守课本”。", "椅子": "语义：椅子是家具，与“遵守”无关，句子不通。", "操场": "语义：操场是场地，不是可以遵守的东西，与句意不合。"}, "sentence_index": 0, "correct_answer": "规则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个花园的规则很整齐。", "explanation": "这里应该用〈布局〉。“规则”指做事的规定，不能用来描述花园布局是否整齐，要说“布局”。"}, {"text": "这个鸡蛋的规则很圆。", "explanation": "这里应该用〈形状〉。“规则”指做事的规定，不能描述物体的圆度，应说“这个鸡蛋的形状很圆”。"}, {"text": "老师给我们讲了一朵规则。", "explanation": "这里应该用〈条〉。“朵”用于花等，“规则”应用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规则", "is_correct": true, "explanation": "“规则”是“看”的对象，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用鼻子闻或用嘴尝来感知，不能用“看”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音要用耳朵听来感知，与“看”不合。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声要用耳朵听，不能“看看”。"}], "explanations": {"规则": "“规则”是“看”的对象，符合句意。", "味道": "语义：味道要用鼻子闻或用嘴尝来感知，不能用“看”。", "声音": "语义：声音要用耳朵听来感知，与“看”不合。", "歌声": "语义：歌声要用耳朵听，不能“看看”。"}, "sentence_index": 6, "correct_answer": "规则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批产品终于达到了规则。", "explanation": "这里应该用〈标准〉。“达到”后接“标准”或“要求”，“规则”不能作达到的目标。"}, {"text": "他的规则很高，大家都很佩服。", "explanation": "这里应该用〈水平〉。“规则”指大家遵守的做事方法，不能用来形容能力高低，说能力强要用“水平”。"}, {"text": "这棵树的规则很粗。", "explanation": "这里应该用〈树干〉。“规则”指做事的规定，不能描述树的粗细，应说“这棵树的树干很粗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班刚制定了一本新规则。", "corrected_sentence": "我们班刚制定了一条新规则。", "error_description": "“规则”的量词应用“条”，不能说“一本规则”，“本”用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些规则们很简单。", "corrected_sentence": "这些规则很简单。", "error_description": "“规则”是无生命的名词，不能加后缀“们”表示复数。应说“这些规则很简单”，不说“这些规则们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
