INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你学习后知道了新东西。", "primary_collocate": null, "pronunciation": "xué dào", "ipa": "ɕɥe˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今天我学到了一个新字。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天在学校学到什么了？", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里学到了很多东西。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看视频学到了做蛋糕的方法。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学到了怎么骑自行车。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我在北京学到了一点汉语。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从朋友那里学到了很多唱歌的技巧。", "target_word": "学到", "complexity_tier": "T3", "furigana": "Tā cóng péng you nà lǐ xué dào le hěn duō chàng gē de jì qiǎo.", "sentence_source": "generated"}, {"text": "这个星期你学到了几个词？", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学到了很多国家的名字。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟学到了怎么游泳，很高兴。", "target_word": "学到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學到", "label": "繁体"}, {"form": "学到了", "label": "体标（了）"}, {"form": "学到过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "学习之后知道了新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学到", "is_correct": true, "explanation": "学到：表示通过学习获得了新字，与“一个新字”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的对象是食物，“新字”不能被吃。"}, {"text": "买", "is_correct": false, "explanation": "搭配：买的对象是可购买的物品，字不能买。"}, {"text": "进入", "is_correct": false, "explanation": "配价：进入带的是处所宾语，不能接“一个新字”作宾语，句子不成立。"}], "explanations": {"学到": "学到：表示通过学习获得了新字，与“一个新字”搭配，符合句意。", "吃": "搭配：吃的对象是食物，“新字”不能被吃。", "买": "搭配：买的对象是可购买的物品，字不能买。", "进入": "配价：进入带的是处所宾语，不能接“一个新字”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "学到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我心里学到了一阵温暖。", "explanation": "这里应该用〈感到〉。学到的宾语是知识或技能，不能指感受，表示感觉要说“感到”。"}, {"text": "他在抽奖中学到了一台电脑。", "explanation": "这里应该用〈得到〉。学到的宾语是知识或技能，不能指奖品。"}, {"text": "我在街上学到了老同学。", "explanation": "这里应该用〈遇见〉。学到不能用于人，也不表示偶然碰见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学到", "is_correct": true, "explanation": "学到：她从朋友那里获得了唱歌的技巧，与“从朋友那里”搭配，符合句意。"}, {"text": "撕掉", "is_correct": false, "explanation": "搭配：撕掉的对象是纸张等，技巧不能被撕掉。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉指丢弃，与“从朋友那里”的获取方向相反，句意不通。"}, {"text": "删去", "is_correct": false, "explanation": "语义：删去多用于文字或文件，不能指从朋友那里删去技巧。"}], "explanations": {"学到": "学到：她从朋友那里获得了唱歌的技巧，与“从朋友那里”搭配，符合句意。", "撕掉": "搭配：撕掉的对象是纸张等，技巧不能被撕掉。", "扔掉": "语义：扔掉指丢弃，与“从朋友那里”的获取方向相反，句意不通。", "删去": "语义：删去多用于文字或文件，不能指从朋友那里删去技巧。"}, "sentence_index": 6, "correct_answer": "学到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在桌子下学到了一只小猫。", "explanation": "这里应该用〈发现〉。学到指通过学习获得知识，不能指找到具体的动物。"}, {"text": "我在河边学到了一只白鹭。", "explanation": "这里应该用〈看见〉。学到的宾语是知识或技能，不能指看见的鸟。"}, {"text": "他在新学校学到了很多好朋友。", "explanation": "这里应该用〈交到〉。学到不能用来指结交的朋友，应说交到朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在网上学到着不少英语词汇。", "corrected_sentence": "我在网上学到了不少英语词汇。", "error_description": "错误形式：“学到着”；正确形式：“学到了”。“着”表示持续或进行中的状态，不能用于已经完成的“学到”，完成义应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从老师那里学到着很多知识。", "corrected_sentence": "我从老师那里学到了很多知识。", "error_description": "错误形式：“学到着”；正确形式：“学到了”。“学到”表示学习有了结果，是已经完成的，不能加表示持续的“着”。完成义应该用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "正确：“开始”与“结束”构成反义，表示事情的起头。"}, {"text": "下棋", "is_correct": false, "explanation": "“下棋”与“结束”之间没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”与“结束”之间没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“结束”之间没有反义关系。"}], "correct_answer": "开始", "explanations": {"开始": "正确：“开始”与“结束”构成反义，表示事情的起头。", "下棋": "“下棋”与“结束”之间没有反义关系。", "洗澡": "“洗澡”与“结束”之间没有反义关系。", "读书": "“读书”与“结束”之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "正确：“开始”与“结束”构成反义，表示事情的起头。"}, {"text": "种树", "is_correct": false, "explanation": "“种树”与“结束”之间没有反义关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "“煮饭”与“结束”之间没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "“跳舞”与“结束”之间没有反义关系。"}], "correct_answer": "开始", "explanations": {"开始": "正确：“开始”与“结束”构成反义，表示事情的起头。", "种树": "“种树”与“结束”之间没有反义关系。", "煮饭": "“煮饭”与“结束”之间没有反义关系。", "跳舞": "“跳舞”与“结束”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情完成了，不再继续。", "primary_collocate": null, "pronunciation": "jié shù", "ipa": "tɕjɛ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "晚会九点结束。", "target_word": "结束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的谈话结束了。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一天的工作结束后，他回到家里。", "target_word": "结束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出结束时，大家都鼓掌了。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行结束了，我们坐飞机回家。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次练习马上就要结束。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的时间太长，还没有结束。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天结束了，天气慢慢变冷。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学期结束，我就去工作。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的比赛结束得很晚。", "target_word": "结束", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "结束了", "label": "体标"}, {"form": "结束语", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情做完，到此为止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：jiéshù 即“结束”，指事情完成，不再继续。"}, {"text": "届数", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是届次的数目。"}, {"text": "节税", "is_correct": false, "explanation": "shuì 与 shù 的韵母不同（多一个 i），意思是节省税款。"}, {"text": "解暑", "is_correct": false, "explanation": "jiě 与 jié、shǔ 与 shù 声调都不同（第三声），意思是消除暑热。"}], "explanations": {"结束": "正确：jiéshù 即“结束”，指事情完成，不再继续。", "届数": "jiè（第四声）与 jié（第二声）声调不同，意思是届次的数目。", "节税": "shuì 与 shù 的韵母不同（多一个 i），意思是节省税款。", "解暑": "jiě 与 jié、shǔ 与 shù 声调都不同（第三声），意思是消除暑热。"}, "sentence_index": null, "correct_answer": "结束"}, "level_3": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：“结束”表示活动到此为止，与“晚会九点”的时间语境相合。"}, {"text": "放假", "is_correct": false, "explanation": "语义：晚会是活动，不会“放假”。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”的主语须是能移动的人，晚会不能出发。"}, {"text": "落成", "is_correct": false, "explanation": "语义：“落成”指建筑物建成，不用于晚会。"}], "explanations": {"结束": "正确：“结束”表示活动到此为止，与“晚会九点”的时间语境相合。", "放假": "语义：晚会是活动，不会“放假”。", "出发": "配价：“出发”的主语须是能移动的人，晚会不能出发。", "落成": "语义：“落成”指建筑物建成，不用于晚会。"}, "sentence_index": 0, "correct_answer": "结束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他结束了一杯咖啡。", "explanation": "这里应该用“喝完”。“结束”用于活动或事情，不能直接带“咖啡”这类具体事物作宾语。"}, {"text": "风一吹，蜡烛就结束了。", "explanation": "这里应该用“熄灭”。“结束”指事情完成、不再继续，不用于蜡烛火焰的熄灭。"}, {"text": "比赛中间结束了一下，队员们喝了口水，然后继续。", "explanation": "这里应该用“暂停”。“结束”表示事情完成、不再继续，不能用于暂时停下、之后还会继续的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结束", "is_correct": true, "explanation": "正确：“结束”表示会议等活动到此为止，与“还没有……”相合。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：会议的时间长短与下雪无关，句子说不通。"}, {"text": "竣工", "is_correct": false, "explanation": "语域：“竣工”用于工程建设，不用于会议。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”的主语须是生物，会议不能生长。"}], "explanations": {"结束": "正确：“结束”表示会议等活动到此为止，与“还没有……”相合。", "下雪": "语义：会议的时间长短与下雪无关，句子说不通。", "竣工": "语域：“竣工”用于工程建设，不用于会议。", "生长": "配价：“生长”的主语须是生物，会议不能生长。"}, "sentence_index": 6, "correct_answer": "结束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她结束了那只碗，然后放进了柜子里。", "explanation": "这里应该用“洗好”。“结束”用于活动或事情的完成，不用于具体器物的清洗完成。"}, {"text": "这锅菜已经结束了，我们可以吃了。", "explanation": "这里应该用“做好”。“结束”用于活动或事情的完成，不用于说菜肴做好。"}, {"text": "他结束了那张照片。", "explanation": "这里应该用“删除”。“结束”不能用来说删掉一张照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚会结束的很晚。", "corrected_sentence": "晚会结束得很晚。", "error_description": "结构助词错误：“结束”后的补语要用“得”，不能用“的”。正确说法是“结束得很晚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考试结束着，同学们都松了一口气。", "corrected_sentence": "考试结束了，同学们都松了一口气。", "error_description": "“着”的误用：“结束”表示动作完成，不能带“着”表示持续。正确说法是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
