INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种语言，很多人用它说话和写字。", "primary_collocate": null, "pronunciation": "yīng yǔ", "ipa": "iŋ˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天早上读半小时英语。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的英语老师是英国人。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在唱英语歌。", "target_word": "英语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这封信是用英语写的。", "target_word": "英语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的英语比我好多了。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学好英语，去国外工作。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字用英语怎么说？", "target_word": "英语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她会说英语和法语。", "target_word": "英语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥正在看英语书。", "target_word": "英语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试以前，我要多练习英语。", "target_word": "英语", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "英语课", "label": "复合"}, {"form": "英语老师", "label": "复合"}], "register": "通用", "sense_fingerprint": "很多人用来说话和写字的一种语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2f9cf7-edee-4641-928c-f58f95f044af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "英语", "is_correct": true, "explanation": "英语 yīngyǔ：主要在英国、美国等国家使用的语言。"}, {"text": "阴雨", "is_correct": false, "explanation": "阴雨 yīnyǔ 与 英语 yīngyǔ 只有第一个音节的韵尾不同（in 与 ing），意思是阴天下雨。"}, {"text": "冰雨", "is_correct": false, "explanation": "冰雨 bīngyǔ 的第一个音节声母是 b，英语 yīngyǔ 的声母是零声母 y，其余相同，意思是冰冻的雨。"}, {"text": "盈余", "is_correct": false, "explanation": "盈余 yíngyú 两个音节的声调都与英语不同（第二声与第一声、第二声与第三声），意思是剩余的钱或利润。"}], "explanations": {"英语": "英语 yīngyǔ：主要在英国、美国等国家使用的语言。", "阴雨": "阴雨 yīnyǔ 与 英语 yīngyǔ 只有第一个音节的韵尾不同（in 与 ing），意思是阴天下雨。", "冰雨": "冰雨 bīngyǔ 的第一个音节声母是 b，英语 yīngyǔ 的声母是零声母 y，其余相同，意思是冰冻的雨。", "盈余": "盈余 yíngyú 两个音节的声调都与英语不同（第二声与第一声、第二声与第三声），意思是剩余的钱或利润。"}, "sentence_index": null, "correct_answer": "英语"}, "level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "搭配：“读”的对象是文字或读物，“读半小时蛋糕”不成立。"}, {"text": "英语", "is_correct": true, "explanation": "英语：指所学的英语内容，与“读半小时”的语境相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“读椅子”句意不通，椅子不是可以阅读的东西。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是文字或学习材料，不能用“读”，句意不通。"}], "explanations": {"蛋糕": "搭配：“读”的对象是文字或读物，“读半小时蛋糕”不成立。", "英语": "英语：指所学的英语内容，与“读半小时”的语境相符。", "椅子": "语义：“读椅子”句意不通，椅子不是可以阅读的东西。", "汽车": "语义：汽车不是文字或学习材料，不能用“读”，句意不通。"}, "sentence_index": 0, "correct_answer": "英语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的家人一直住在英语。", "explanation": "这里应该用〈英国〉。英国是地方，表示“住在”的地点；英语是语言，不能作为居住的地点。"}, {"text": "他把英语放进冰箱了。", "explanation": "这里应该用〈牛奶〉。英语是语言，不是东西，不能放进冰箱。"}, {"text": "这个孩子是村里的英语。", "explanation": "这里应该用〈英雄〉。英雄指人，英语是语言，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "搭配：“用椅子怎么说”没有意义，椅子不是表达的语言或方式。"}, {"text": "英语", "is_correct": true, "explanation": "英语：表示语言，“用英语怎么说”是常用的问法。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是表达所用的语言，“用数学怎么说”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是表达的手段，与“怎么说”的语境不合。"}], "explanations": {"椅子": "搭配：“用椅子怎么说”没有意义，椅子不是表达的语言或方式。", "英语": "英语：表示语言，“用英语怎么说”是常用的问法。", "数学": "语义：数学是学科，不是表达所用的语言，“用数学怎么说”句意不通。", "桌子": "搭配：“桌子”不是表达的手段，与“怎么说”的语境不合。"}, "sentence_index": 6, "correct_answer": "英语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸去英语出差了。", "explanation": "这里应该用〈英国〉。英国是地方，表示去的地点；英语是语言，不能作为目的地。"}, {"text": "他会用英语切菜，很厉害。", "explanation": "这里应该用〈菜刀〉。英语是语言，不能用来切菜；切菜要用「菜刀」。"}, {"text": "这本书卖五个英语。", "explanation": "这里应该用〈英镑〉。英镑是货币单位，用来表示价钱；英语是语言，不能当作钱数来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学过一个英语。", "corrected_sentence": "我学过英语。", "error_description": "量词错误：“英语”是语言，不用“一个”计量；应说“学过英语”，去掉多余的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这封信翻译英语了。", "corrected_sentence": "我把这封信翻译成英语了。", "error_description": "结果补语“成”缺失：应说“翻译成英语了”，不能说“翻译英语了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd226ebe4-c57a-4e4c-9505-fe601732452d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
