INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人与人随意地说话、闲谈。", "primary_collocate": null, "pronunciation": "liáo tiān", "ipa": "ljɑʊ˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "我想找你聊天。", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们坐在桌子旁聊天。", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明和同学在电话里聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们好久没见，今天聊天聊得很开心。", "target_word": "聊天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢和奶奶聊天。", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车上，我和旁边的人聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要大声聊天。", "target_word": "聊天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃饭的时候，我们一边吃一边聊天。", "target_word": "聊天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每晚都和我聊天。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不太爱聊天，一直很安静。", "target_word": "聊天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "聊聊天", "label": "重叠"}, {"form": "聊了天", "label": "体标"}, {"form": "聊天儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "两个人在一起说话闲谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聊天", "is_correct": true, "explanation": "聊天：两个人闲谈，符合“我想找你”后的动作语境。"}, {"text": "下雨", "is_correct": false, "explanation": "配价：“下雨”是天气动词，不能表示“找你”的目的，句子不通。"}, {"text": "发光", "is_correct": false, "explanation": "语义：“发光”不能表示“找你”的目的，句意不通。"}, {"text": "打雷", "is_correct": false, "explanation": "配价：“打雷”是天气现象，不能表示“找你”的目的，句子不通。"}], "explanations": {"聊天": "聊天：两个人闲谈，符合“我想找你”后的动作语境。", "下雨": "配价：“下雨”是天气动词，不能表示“找你”的目的，句子不通。", "发光": "语义：“发光”不能表示“找你”的目的，句意不通。", "打雷": "配价：“打雷”是天气现象，不能表示“找你”的目的，句子不通。"}, "sentence_index": 0, "correct_answer": "聊天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天聊天了一封信。", "explanation": "这里应该用〈写〉。“聊天”是闲谈，不能带“信”这类书面作品作宾语，写信要说“写”。"}, {"text": "我们在会上聊天了新方案。", "explanation": "这里应该用〈讨论〉。“聊天”不能带“方案”这类宾语，讨论方案要说“讨论”。"}, {"text": "他去北京聊天了老朋友。", "explanation": "这里应该用〈拜访〉。“聊天”不能带“老朋友”作宾语，去看望朋友要说“拜访”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聊天", "is_correct": true, "explanation": "聊天：两个人闲谈，符合“请不要大声”后的语境，表示不要大声说话。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能与“大声”搭配，句子不通。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”是不说话，与“大声”的要求相矛盾，不能搭配。"}, {"text": "做", "is_correct": false, "explanation": "配价：“做”需要带宾语，“请不要大声做”后面缺少宾语，不成立。"}], "explanations": {"聊天": "聊天：两个人闲谈，符合“请不要大声”后的语境，表示不要大声说话。", "下雨": "语义：“下雨”是天气现象，不能与“大声”搭配，句子不通。", "沉默": "语义：“沉默”是不说话，与“大声”的要求相矛盾，不能搭配。", "做": "配价：“做”需要带宾语，“请不要大声做”后面缺少宾语，不成立。"}, "sentence_index": 6, "correct_answer": "聊天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向经理聊天了服务。", "explanation": "这里应该用〈投诉〉。“聊天”不能带“服务”作宾语，对服务表示不满要说“投诉”。"}, {"text": "我去医院聊天了这个问题。", "explanation": "这里应该用〈咨询〉。“聊天”不能带“问题”作宾语，向医生请教问题要说“咨询”。"}, {"text": "他在会上聊天了工作。", "explanation": "这里应该用〈报告〉。“聊天”不能带“工作”作宾语，汇报工作要说“报告”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚和朋友的一个聊天很愉快。", "corrected_sentence": "昨晚和朋友的一次聊天很愉快。", "error_description": "错在量词：“聊天”作名词时用“次”计量，不能用“个”，应为“一次聊天”，不能说“一个聊天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们聊天得很晚。", "corrected_sentence": "他们聊天聊得很晚。", "error_description": "错在补语结构：“V得”补语前要重复动词，应为“聊天聊得很晚”，不能只说“聊天得很晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
