INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23684, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是真的，是想出来的。", "primary_collocate": null, "pronunciation": "xū nǐ", "ipa": "ɕy˥ ni˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子们喜欢在虚拟世界里玩游戏。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手是虚拟的，不是真人。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上有一个虚拟的朋友。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以用电脑做一个虚拟教室。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虚拟货币只能在网上用。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏中的城市是虚拟的，玩家可以自由探索。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在虚拟商店里买了一件衣服。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戴上眼镜，你就能进入虚拟的海边。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的角色都是虚拟的，玩家可以和他们说话。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想做一个虚拟的城市。", "target_word": "虚拟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虚拟的", "label": "的字结构"}, {"form": "虚拟世界", "label": "复合"}, {"form": "虚拟现实", "label": "复合"}], "register": "书面", "sense_fingerprint": "不是真实存在的，是想象或用电脑做出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚拟", "is_correct": true, "explanation": "虚拟指不是真实存在的，与“世界”和“玩游戏”相合，句意通顺。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”形容价格高，不能修饰“世界”。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”描述形状，与玩游戏的世界不相合。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”形容分量大，不适合描述游戏的世界。"}], "explanations": {"虚拟": "虚拟指不是真实存在的，与“世界”和“玩游戏”相合，句意通顺。", "昂贵": "搭配：“昂贵”形容价格高，不能修饰“世界”。", "圆形": "语义：“圆形”描述形状，与玩游戏的世界不相合。", "沉重": "语义：“沉重”形容分量大，不适合描述游戏的世界。"}, "sentence_index": 0, "correct_answer": "虚拟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次演出的票价很虚拟，学生都买得起。", "explanation": "这里应该用〈便宜〉。“虚拟”指不真实、模拟出来的，不用来形容价格高低，说价格低要用“便宜”。"}, {"text": "这块蛋糕是虚拟的，我们每个人都吃了两大块。", "explanation": "这里应该用〈真的〉。“虚拟”指不真实，与“吃了两大块”矛盾，能吃的东西要说“真的”。"}, {"text": "他的朋友很虚拟，每次都说假话。", "explanation": "这里应该用〈虚伪〉。虚拟指不真实或模拟，形容人说假话要说虚伪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚拟", "is_correct": true, "explanation": "虚拟修饰“商店”，指网上或模拟的商店，与“买了一件衣服”相合。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不能修饰商店。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，商店不能是柔软的。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”形容表面，不适用于描述商店。"}], "explanations": {"虚拟": "虚拟修饰“商店”，指网上或模拟的商店，与“买了一件衣服”相合。", "陡峭": "搭配：“陡峭”形容地势，不能修饰商店。", "柔软": "语义：“柔软”形容质地，商店不能是柔软的。", "粗糙": "语义：“粗糙”形容表面，不适用于描述商店。"}, "sentence_index": 6, "correct_answer": "虚拟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的颜色很虚拟，非常好看。", "explanation": "这里应该用〈鲜艳〉。“虚拟”指不真实、想出来的，花的颜色是真实可见的，形容颜色亮丽要说“鲜艳”。"}, {"text": "他的心里很虚拟，总觉得没有什么意思。", "explanation": "这里应该用〈空虚〉。虚拟指不真实或想出来的，形容心里没有着落要说空虚。"}, {"text": "这个城市的虚拟很大。", "explanation": "词性：虚拟是形容词，不能当名词用；说城市的规模要用“规模”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在电脑上做了一个虚拟得教室。", "corrected_sentence": "我们在电脑上做了一个虚拟的教室。", "error_description": "错误：“虚拟”修饰名词“教室”时应用“的”，不能用“得”。“得”用于补语，不用于修饰名词。正确：“做了一个虚拟的教室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在虚拟地世界里交到了很多朋友。", "corrected_sentence": "她在虚拟的世界里交到了很多朋友。", "error_description": "错误：“虚拟”修饰名词“世界”时应加“的”，不能用“地”。“地”用于修饰动词或形容词。正确：“虚拟的世界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
