INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "衣服或纸上的折痕，像一条线。", "primary_collocate": null, "pronunciation": "zhě zhòu", "ipa": "ʈʂɤ˨˩ ʈʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "地图上有一道褶皱，是折过的地方。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张纸上的褶皱压平。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裤子上的褶皱像一条直线。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的封面有一道褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的白衬衫没有一点褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完的衣服一干，褶皱就出来了。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把纸对折后，中间会留下一条褶皱。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的裙子上有几道细细的褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片的角上有一道长长的褶皱。", "target_word": "褶皱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看到信纸上的褶皱，知道有人打开过。", "target_word": "褶皱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "褶皺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "褶皱：衣服或纸上像线一样的折痕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：香味是闻到的气味，不能用“一道”计量，也不是折过的地方。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子由光线形成，不会因折叠而留下，与后半句的语义冲突。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“道”不与“公路”搭配，公路应说“一条”；而且公路本身也不是折过的地方。"}, {"text": "褶皱", "is_correct": true, "explanation": "“褶皱”指纸面上的折痕，与“是折过的地方”相呼应，符合地图上的折痕语境。"}], "explanations": {"香味": "语义：香味是闻到的气味，不能用“一道”计量，也不是折过的地方。", "影子": "语义：影子由光线形成，不会因折叠而留下，与后半句的语义冲突。", "公路": "搭配：“道”不与“公路”搭配，公路应说“一条”；而且公路本身也不是折过的地方。", "褶皱": "“褶皱”指纸面上的折痕，与“是折过的地方”相呼应，符合地图上的折痕语境。"}, "sentence_index": 0, "correct_answer": "褶皱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玻璃杯上多了几道褶皱。", "explanation": "这里应该用〈划痕〉。褶皱是柔软材料折叠或挤压形成的痕迹；玻璃杯是硬质器物，表面被刮擦留下的痕迹要说“划痕”。"}, {"text": "这张木桌的表面有清晰的褶皱。", "explanation": "这里应该用〈纹路〉。褶皱是折叠或挤压形成的痕迹，木材本身的花纹要用纹路。"}, {"text": "这块挡风玻璃上有一道褶皱。", "explanation": "这里应该用〈裂纹〉。裂纹是材料受力断开形成的细缝，玻璃破裂要用裂纹；褶皱指衣物、纸张折叠或挤压形成的痕迹，玻璃上不会有褶皱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤疤", "is_correct": false, "explanation": "语义：伤疤是皮肤愈合后的痕迹，纸张对折不会在中间形成伤疤。"}, {"text": "褶皱", "is_correct": true, "explanation": "“褶皱”指纸对折后留下的折痕，与“把纸对折后”的语境一致。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：墨水是液体，不用“一条”计量，应说“一滴”或“一摊”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体物件，不会因为纸对折而留在纸的中间。"}], "explanations": {"伤疤": "语义：伤疤是皮肤愈合后的痕迹，纸张对折不会在中间形成伤疤。", "褶皱": "“褶皱”指纸对折后留下的折痕，与“把纸对折后”的语境一致。", "墨水": "搭配：墨水是液体，不用“一条”计量，应说“一滴”或“一摊”。", "石头": "语义：石头是固体物件，不会因为纸对折而留在纸的中间。"}, "sentence_index": 6, "correct_answer": "褶皱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信的信纸上有一朵褶皱。", "explanation": "这里应该用〈道〉。“朵”用于花朵、云朵等，不用于褶皱这种线状折痕。"}, {"text": "枕巾上有一张褶皱。", "explanation": "这里应该用〈道〉。“张”用于纸、桌子等平面的东西，褶皱是线状的折痕，应用“道”或“条”。"}, {"text": "他的衬衫袖口有一颗褶皱。", "explanation": "这里应该用〈道〉。“颗”用于圆形的小颗粒，不用于褶皱这种线状痕迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把桌布上的褶皱熨。", "corrected_sentence": "他把桌布上的褶皱熨平了。", "error_description": "把字句错误：“把”字句的动词不能单独出现，后面要有结果补语等成分，应说“熨平了”，说明褶皱被处理后的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床单上有一只褶皱。", "corrected_sentence": "床单上有一道褶皱。", "error_description": "“褶皱”是线状的折痕，量词应用“道”。“只”多用于动物或成对事物中的一个，此处用“只”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚假", "is_correct": true, "explanation": "「虚假」与「真实」在“不是假的”这一义项上构成反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "「漂亮」形容外貌，与「真实」不构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "「聪明」形容智力，与「真实」不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "「高兴」形容情绪，与「真实」不构成反义关系。"}], "correct_answer": "虚假", "explanations": {"虚假": "「虚假」与「真实」在“不是假的”这一义项上构成反义关系。", "漂亮": "「漂亮」形容外貌，与「真实」不构成反义关系。", "聪明": "「聪明」形容智力，与「真实」不构成反义关系。", "高兴": "「高兴」形容情绪，与「真实」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚假", "is_correct": true, "explanation": "「虚假」与「真实」在“不是假的”这一义项上构成反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "「迅速」形容速度，与「真实」不构成反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或感情，与「真实」不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "「安静」形容声音或环境，与「真实」不构成反义关系。"}], "correct_answer": "虚假", "explanations": {"虚假": "「虚假」与「真实」在“不是假的”这一义项上构成反义关系。", "迅速": "「迅速」形容速度，与「真实」不构成反义关系。", "温暖": "「温暖」形容温度或感情，与「真实」不构成反义关系。", "安静": "「安静」形容声音或环境，与「真实」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真实就是不是假的。", "primary_collocate": null, "pronunciation": "zhēn shí", "ipa": "ʈʂən˥ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个真实的故事。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话很真实。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的生活非常真实。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道真实的情况。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影看起来很真实。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想说出真实的名字。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是真实的，不是编的。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的感觉是真实的，不用怕。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的日记很真实。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想听我们真实的想法。", "target_word": "真实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不真实", "label": "否定式"}], "register": "中性", "sense_fingerprint": "形容词，指事情或情况符合实际，不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真实", "is_correct": true, "explanation": "「真实」是正确答案，指事情或情况不是假的，与句中的用法一致。"}, {"text": "真是", "is_correct": false, "explanation": "「shí（第二声）」与「shì（第四声）」声调不同，「真是」意思是“的确是”。"}, {"text": "珍视", "is_correct": false, "explanation": "「shí（第二声）」与「shì（第四声）」声调不同，「珍视」意思是“重视、珍惜”。"}, {"text": "诊室", "is_correct": false, "explanation": "「zhēn（第一声）」与「zhěn（第三声）」、「shí」与「shì」声调均不同，「诊室」意思是“看病的房间”。"}, {"text": "阵势", "is_correct": false, "explanation": "「zhēn（第一声）」与「zhèn（第四声）」、「shí」与「shì」声调均不同，「阵势」意思是“气势、架势”。"}], "explanations": {"真实": "「真实」是正确答案，指事情或情况不是假的，与句中的用法一致。", "真是": "「shí（第二声）」与「shì（第四声）」声调不同，「真是」意思是“的确是”。", "珍视": "「shí（第二声）」与「shì（第四声）」声调不同，「珍视」意思是“重视、珍惜”。", "诊室": "「zhēn（第一声）」与「zhěn（第三声）」、「shí」与「shì」声调均不同，「诊室」意思是“看病的房间”。", "阵势": "「zhēn（第一声）」与「zhèn（第四声）」、「shí」与「shì」声调均不同，「阵势」意思是“气势、架势”。"}, "sentence_index": null, "correct_answer": "真实"}, "level_3": {"options": [{"text": "真实", "is_correct": true, "explanation": "「真实」修饰“故事”，表示不是假的，句意通顺。"}, {"text": "矮", "is_correct": false, "explanation": "语义：「矮」描述高度，不能用来修饰“故事”，句子说不通。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：「咸」只用于描述味道，不能修饰“故事”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」指形状，用来形容“故事”语义不合。"}], "explanations": {"真实": "「真实」修饰“故事”，表示不是假的，句意通顺。", "矮": "语义：「矮」描述高度，不能用来修饰“故事”，句子说不通。", "咸": "搭配：「咸」只用于描述味道，不能修饰“故事”。", "圆": "语义：「圆」指形状，用来形容“故事”语义不合。"}, "sentence_index": 0, "correct_answer": "真实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑步的速度很真实。", "explanation": "这里应该用〈快〉。真实表示“不是假的”，用于事情、情况或言论，不用来形容速度；说速度快要用〈快〉。"}, {"text": "这个月很真实。", "explanation": "这里应该用〈漫长〉。真实表示“不是假的”，不用来描述时间段的长短，说一段时间长要用〈漫长〉。"}, {"text": "这个孩子的个子很真实。", "explanation": "这里应该用〈高〉。真实表示“不是假的”，不用来形容个子的高矮；说个子高要用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真实", "is_correct": true, "explanation": "「真实」作谓语，表示故事不是假的，与“不是编的”前后呼应。"}, {"text": "冷", "is_correct": false, "explanation": "语义：「冷」形容温度，不能用来说故事“是冷的”。"}, {"text": "近视", "is_correct": false, "explanation": "搭配：「近视」形容视力，不能用来修饰“故事”。"}, {"text": "硬", "is_correct": false, "explanation": "语义：「硬」形容质地，用来形容故事语义不合。"}], "explanations": {"真实": "「真实」作谓语，表示故事不是假的，与“不是编的”前后呼应。", "冷": "语义：「冷」形容温度，不能用来说故事“是冷的”。", "近视": "搭配：「近视」形容视力，不能用来修饰“故事”。", "硬": "语义：「硬」形容质地，用来形容故事语义不合。"}, "sentence_index": 6, "correct_answer": "真实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面很真实。", "explanation": "这里应该用〈好吃〉。「真实」用于事情、情况或言论，不能用来形容食物的味道。"}, {"text": "今天天气很真实。", "explanation": "这里应该用〈晴朗〉。「真实」表示“不是假的”，不用于描述天气。"}, {"text": "这个房间的面积很真实。", "explanation": "这里应该用〈大〉。真实表示“不是假的”，不用来形容面积；说面积大要用〈大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是一个真实人。", "corrected_sentence": "那是一个真实的人。", "error_description": "「真实」作定语修饰单独的名词时，通常要加「的」，应说「真实的人」，不说「真实人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个故事比那个最真实。", "corrected_sentence": "这个故事比那个更真实。", "error_description": "程度副词错误。「比」字句中不能用「最」，应用「更」表示程度加深，「比那个最真实」应改为「比那个更真实」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
