INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "完全进入一种状态，像泡在水里一样。", "primary_collocate": null, "pronunciation": "chén jìn", "ipa": "ʈʂʰən˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我沉浸在书里，忘了时间。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在游戏里，不想吃饭。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩沉浸在画画的快乐里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她沉浸在歌声中，闭上了眼睛。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们沉浸在学习中，教室里很安静。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸沉浸在棋局里，没有听见电话响。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家沉浸在比赛的紧张里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在工作中，忘了回家。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶沉浸在旧照片里，看了很久。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌太好听，我整个人都沉浸进去了。", "target_word": "沉浸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉浸着", "label": "体标"}, {"form": "沉浸了", "label": "体标"}, {"form": "沉浸式", "label": "复合"}], "register": "中性", "sense_fingerprint": "完全进入某种状态，像泡在水里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": false, "explanation": "配价：“离开”要直接带处所宾语，不能说“离开在……里”，这个结构不成立。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵与“在书里，忘了时间”的安静读书状态相矛盾。"}, {"text": "厌烦", "is_correct": false, "explanation": "搭配：“厌烦”通常直接带对象，不接“在……里”的处所结构，搭配不当。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指完全进入某种状态，与“在书里，忘了时间”的描述相符。"}], "explanations": {"离开": "配价：“离开”要直接带处所宾语，不能说“离开在……里”，这个结构不成立。", "争吵": "语义：争吵与“在书里，忘了时间”的安静读书状态相矛盾。", "厌烦": "搭配：“厌烦”通常直接带对象，不接“在……里”的处所结构，搭配不当。", "沉浸": "沉浸指完全进入某种状态，与“在书里，忘了时间”的描述相符。"}, "sentence_index": 0, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把大部分积蓄沉浸在股市里，一年就输光了。", "explanation": "这里应该用〈投入〉。〈沉浸〉指心神沉入某种状态，不用来说把钱投进去。"}, {"text": "我的成绩沉浸在班级前十里。", "explanation": "这里应该用〈位列〉。〈沉浸〉的主语须是人，表示全神贯注，成绩不能沉浸，应说位列班级前十。"}, {"text": "他沉浸了一碗面条，很快就吃完了。", "explanation": "这里应该用〈吃〉。〈沉浸〉不能直接带宾语，吃面条要说吃，不能说沉浸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
